import { 
 BarChart3, 
 CheckCircle2, 
 AlertTriangle,
 ArrowRight,
 ShieldAlert,
 Info
} from "lucide-react";
import { toast } from "sonner";
import { useAuth } from "@/providers/AuthProvider";
