}

'use client';

import { useState, useEffect, useMemo } from 'react';
import { useTranslations } from 'next-intl';
import { useRouter, Link } from '@/i18n/navigation';
import { useGRNList, type GRNSummary } from '@/features/purchasing/hooks/useGRNList';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { ColumnDef } from '@tanstack/react-table';
import { StatusBadge, type BadgeStatus } from '@/components/shared/StatusBadge';
import { Button } from '@/components/ui/button';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { PageHeader } from '@/components/shared/PageHeader';
import { Plus, Filter, Search, CheckCircle2, Clock, Inbox, ArrowRight } from 'lucide-react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Input } from '@/components/ui/input';

import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { MetricCard } from '@/components/ui/metric-card';
import { EmptyState } from '@/components/shared/EmptyState';
import { format } from 'date-fns';
import { HydrationSafe } from '@/components/shared/HydrationSafe';
import { isPendingStatus, isPostedStatus, type DocumentStatus } from '@/core/workflow/document-engine';
import { GRN_STATUS } from '@/contracts/statuses';
import { QueryBoundary } from '@/core/query/QueryBoundary';
import { PageSkeleton } from '@/components/shared/PageSkeleton';

export function GRNListClient({
 initialStatus,
 initialPage,
 locale,
}: {
 initialStatus?: string;
 initialPage: number;
 locale: 'ar' | 'en';
}) {
 const t = useTranslations('procurement.grn');
 const tc = useTranslations('common');
 const router = useRouter();

 const [status, setStatus] = useState<string | undefined>(initialStatus);
 const [page, setPage] = useState(initialPage);
 const [search, setSearch] = useState('');
 const [debouncedSearch, setDebouncedSearch] = useState('');

 // Debounce search input
 useEffect(() => {
 const timer = setTimeout(() => setDebouncedSearch(search), 500);
 return () => clearTimeout(timer);
 }, [search]);

 const { data, isLoading } = useGRNList({ status, page, search: debouncedSearch });

 const columns = useMemo<ColumnDef<GRNSummary, unknown>[]>(() => [
 {
 accessorKey: 'status',
 header: tc('status_label'),
 cell: ({ row }) => <StatusBadge status={row.original.status as BadgeStatus} />,
 },
 {
 accessorKey: 'document_number',
 header: tc('doc_number'),
 cell: ({ row }) => (
 <div className="flex flex-col gap-0.5">
 <span dir="ltr" className="font-mono text-cyan-500 font-semibold text-body-md">{row.original.document_number}</span>
 <span className="text-label-xxs font-semibold uppercase opacity-30">{t('received_manifest_sub')}</span>
 </div>
 ),
 },
 {
 accessorKey: 'supplier_id',
 header: tc('supplier'),
 cell: ({ row }) => (
 <div className="flex flex-col">
 <span dir="ltr" className="text-label-xs font-semibold text-foreground/80 text-start">{row.original.supplier_id}</span>
 <span className="text-label-xxs font-medium opacity-40 uppercase">{t('verified_vendor_sub')}</span>
 </div>
 ),
 },
 {
 accessorKey: 'posted_at',
 header: tc('posted_at'),
 cell: ({ row }) =>
 row.original.posted_at ? (
  <div className="flex items-center gap-2">
    <HydrationSafe fallback={<span className="text-label-xs opacity-10 font-mono">--/--/----</span>}>
      <span dir="ltr" className="text-label-xs opacity-60 font-mono font-medium">
        {format(new Date(row.original.posted_at), 'dd/MM/yyyy')}
      </span>
    </HydrationSafe>
  </div>
 ) : <span className="opacity-10 text-label-xs font-semibold italic">{t('pending_label')}</span>,
 },
 {
 id: 'actions',
 header: '',
 cell: ({ row }) => (
 <div className="flex justify-end">
 <PermissionGate action="view" resource="grn">
 <Button
 variant="ghost"
 size="sm"
 className="text-label-xxs font-semibold uppercase text-cyan-500 hover:text-white hover:bg-cyan-500/20 h-8 px-4 rounded-md transition-all group"
 onClick={(e) => {
 e.stopPropagation();
   router.push(`/goods-received/${row.original.id}`);
 }}
 >
 {tc('view')}
 <ArrowRight className="w-3 h-3 ms-2 opacity-0 group-hover:opacity-100 transition-all translate-x-[-4px] group-hover:translate-x-0 rtl:translate-x-[4px] rtl:group-hover:translate-x-0 rtl:rotate-180" />
 </Button>
 </PermissionGate>
 </div>
 ),
 },
 ], [locale, router, t, tc]);

 const totalGRNs = data?.meta?.total || 0;
 const postedCount = data?.data?.filter(p => isPostedStatus('GRN', p.status as DocumentStatus)).length || 0;
 const draftCount = data?.data?.filter(p => isPendingStatus('GRN', p.status as DocumentStatus)).length || 0;

 return (
 <div className="p-10 max-w-[1600px] mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-6 duration-1000">
 <div className="space-y-4">
 <Breadcrumb 
 items={[
   { label: tc('sidebar.dashboard'), href: '/dashboard' },
 { label: tc('sidebar.grn') }
 ]} 
 />
 <PageHeader
 title={t('title')}
 description={t('description')}
 actions={
 <div className="flex items-center gap-6">
 <PermissionGate action="create" resource="grn">
   <Link href="/goods-received/new">
 <Button className="h-11 px-8 bg-cyan-600 hover:bg-cyan-500 text-white text-label-xs font-semibold uppercase rounded-md transition-all shadow-lg shadow-cyan-900/10 border-none">
 <Plus className="w-3.5 h-3.5 me-2" />
 {t('create_new')}
 </Button>
 </Link>
 </PermissionGate>
 </div>
 }
 />
 </div>

 <QueryBoundary 
        isLoading={isLoading} 
        error={data === undefined && !isLoading ? new Error('Failed to load data') : null}
        loadingFallback={<PageSkeleton />}
      >
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          <MetricCard
            label={t('stats.total_manifests')}
            value={totalGRNs}
            icon={Inbox}
            color="cyan"
          />
          <MetricCard
            label={t('stats.committed_batches')}
            value={postedCount}
            icon={CheckCircle2}
            color="emerald"
          />
          <MetricCard
            label={t('stats.awaiting_audit')}
            value={draftCount}
            icon={Clock}
            color="amber"
          />
        </div>

        <div className="bg-surface-container-lowest border border-surface-variant/5 rounded-lg p-1">
          <DataTable
            columns={columns}
            data={data?.data || []}
            onRowClick={(row: GRNSummary) => router.push(`/goods-received/${row.id}`)}
            collectionName="procurement_grn"
            enableVirtualization={true}
            containerHeight="600px"
            emptyState={
              <EmptyState 
                title={t('no_grns_title') || 'No Goods Received Notes'} 
                description={t('no_grns_desc') || 'Create a new GRN when goods are delivered to update stock levels.'} 
                action={
                  <PermissionGate action="create" resource="grn">
                    <Link href="/goods-received/new">
                      <Button className="h-10 px-6 bg-cyan-500 hover:bg-cyan-400 text-black text-label-xs font-semibold uppercase rounded-md transition-all">
                        <Plus className="w-3.5 h-3.5 me-2" />
                        {t('create_new')}
                      </Button>
                    </Link>
                  </PermissionGate>
                }
              />
            }
            pagination={data?.meta ? {
              page: data.meta.page,
              pageSize: data.meta.page_size,
              total: data.meta.total,
              totalPages: data.meta.total_pages,
              onPageChange: setPage
            } : undefined}
            filters={
              <div className="flex flex-wrap items-end gap-8 w-full py-6 px-8 bg-surface-container-low border-b border-surface-variant/10">
                <div className="flex flex-col gap-3 min-w-[240px] flex-1">
                  <label className="text-label-xs font-semibold uppercase text-muted-foreground/40">{tc('status_filtering')}</label>
                  <Select
                    value={status || 'ALL'} 
                    onValueChange={(val) => { setStatus(val === 'ALL' ? undefined : (val ?? undefined)); setPage(1); }}
                  >
                    <SelectTrigger className="w-full bg-surface-container-highest/20 border-surface-variant/5 h-12 px-4 text-label-xs font-semibold uppercase focus:ring-cyan-500/10 rounded-md">
                      <SelectValue placeholder={tc('status.all')} />
                    </SelectTrigger>
                    <SelectContent className="bg-surface-container-high border-surface-variant/5 rounded-md">
                      <SelectItem value="ALL" className="text-label-xs font-semibold uppercase">{tc('status.all')}</SelectItem>
                      <SelectItem value={GRN_STATUS.DRAFT} className="text-label-xs font-semibold uppercase">{tc('status.draft')}</SelectItem>
                      <SelectItem value={GRN_STATUS.POSTED} className="text-label-xs font-semibold uppercase">{tc('status.posted')}</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div className="flex flex-col gap-3 min-w-[300px] flex-[2]">
                  <label className="text-label-xs font-semibold uppercase text-muted-foreground/40">{t('stream_identifier')}</label>
                  <div className="relative">
                    <Input
                      placeholder={t('search_placeholder')}
                      value={search}
                      onChange={(e) => { setSearch(e.target.value); setPage(1); }}
                      className="w-full bg-surface-container-highest/20 border-surface-variant/5 h-12 ps-12 pe-4 text-label-sm font-semibold focus:ring-cyan-500/10 placeholder:text-muted-foreground/20 rounded-md"
                    />
                    <Search className="absolute start-4 top-1/2 -translate-y-1/2 w-4 h-4 text-cyan-500/40" />
                    {search && (
                      <button 
                        onClick={() => { setSearch(''); setPage(1); }}
                        className="absolute end-4 top-1/2 -translate-y-1/2 text-label-xs font-semibold uppercase text-muted-foreground/40 hover:text-cyan-500 transition-colors"
                      >
                        {tc('reset')}
                      </button>
                    )}
                  </div>
                </div>

                <Button 
                  variant="outline"
                  onClick={() => { setStatus(undefined); setSearch(''); setPage(1); }}
                  className="h-12 px-10 bg-surface-container-highest/30 hover:bg-surface-container-highest text-label-xs font-semibold uppercase rounded-md transition-all border border-surface-variant/5 group"
                >
                  <Filter className="w-4 h-4 me-2 group-hover:text-cyan-500 transition-colors" />
                  {tc('reset')}
                </Button>
              </div>
            }
          />
        </div>
      </QueryBoundary>
 </div>
 );
}

'use client';

import * as React from 'react';
import { useTranslations } from 'next-intl';
import { useRouter } from '@/i18n/navigation';
import { 
  ArrowLeft, 
  Wallet, 
  PackageSearch, 
  Warehouse, 
  MessageSquare, 
  TrendingUp, 
  History, 
  Package 
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { StatusBadge, type BadgeStatus } from '@/components/shared/StatusBadge';
import { DocumentReadOnlyOverlay } from '@/components/shared/DocumentReadOnlyOverlay';
import { StatusTimeline, type Status } from '@/components/shared/StatusTimeline';
import { DocumentLineItemTable } from '@/components/shared/DocumentLineItemTable/DocumentLineItemTable';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Card } from '@/components/ui/card';
import { useAdminSettings } from '@/features/admin/hooks/useAdminSettings';
import { formatCurrency } from '@/utils/currency';
import { PageSkeleton } from '@/components/shared/PageSkeleton';

import type { GRN, GRNLineItem } from '@/types/documents';

interface AuditLogEntry {
  status: string;
  created_at: string;
  user_name?: string;
}

interface GRNViewerDocument extends Omit<GRN, 'lines'> {
  supplier_name?: string;
  po_number?: string | null;
  audit_log?: AuditLogEntry[];
  lines: GRNLineItem[];
}

interface GRNViewerProps {
  document: GRNViewerDocument;
  locale: 'ar' | 'en';
  actions?: React.ReactNode;
}

/**
 * GRNViewer - Strict Immutable Rendering for Goods Received Notes.
 * Displays data in a read-only format without initializing form state or mutation hooks.
 */
export function GRNViewer({ document, locale, actions }: GRNViewerProps) {
  const t = useTranslations('procurement.grn');
  const tc = useTranslations('common');
  const router = useRouter();

  const { data: settings, isLoading: loadingSettings } = useAdminSettings();
  const baseCurrency = settings?.base_currency || 'SAR';

  const totalForeign = document?.lines?.reduce((acc: number, line: GRNLineItem) => acc + (line.received_qty * (line.unit_cost_foreign || 0)), 0) || 0;
  const currentFxRate = document?.fx_rate || 1;

  const timelineEntries = document?.audit_log?.map((e: AuditLogEntry) => ({
    status: e.status.toLowerCase() as Status,
    at: e.created_at,
    by: e.user_name || tc('system')
  })) || [
    { status: (document?.status || 'DRAFT').toLowerCase() as Status, at: document?.created_at || new Date().toISOString(), by: 'System' }
  ];

  if (loadingSettings) {
    return <PageSkeleton />;
  }

  return (
    <div className="space-y-10 w-full bg-surface-container-low min-h-screen p-6 lg:p-10 animate-in fade-in duration-500">
      {/* Structural Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 bg-surface-container-lowest p-8 rounded-[2rem] border border-surface-variant/5 shadow-sm">
        <div className="flex items-center gap-4">
          <div className="p-3 rounded-2xl bg-emerald-500/10 text-emerald-500">
            <Package className="w-6 h-6" />
          </div>
          <div>
            <h3 className="text-title-lg font-semibold text-emerald-500 uppercase">{t('detail_title') || t('title')}</h3>
            <div className="flex items-center gap-2 mt-0.5">
              <p className="text-label-xs font-bold text-muted-foreground/40 uppercase">{tc('read_only_view')}</p>
              <span className="text-muted-foreground/20">•</span>
              <span className="font-mono text-label-xs font-semibold text-muted-foreground/60">
                {document?.document_number}
              </span>
            </div>
          </div>
        </div>
        
        <div className="flex items-center gap-3">
          <StatusBadge status={document?.status as BadgeStatus} />
          {actions && (
            <>
              <div className="w-px h-8 bg-surface-variant/10 mx-1" />
              {actions}
            </>
          )}
        </div>
      </div>

      <div className="max-w-[1400px] mx-auto space-y-10">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {/* Supplier Info */}
          <div className="bg-surface-container-lowest p-6 rounded-2xl shadow-sm flex flex-col gap-1 group border border-surface-variant/5">
            <p className="text-label-xs font-semibold uppercase text-primary/30 group-hover:text-primary transition-colors">{tc('supplier')}</p>
            <p className="font-bold text-title-sm mt-2 italic uppercase text-foreground">{document?.supplier_name || 'Supply Co'}</p>
          </div>

          {/* Currency Info */}
          <div className="bg-surface-container-lowest p-6 rounded-2xl shadow-sm flex flex-col gap-1 group relative overflow-hidden border border-surface-variant/5">
            <div className="absolute top-0 end-0 p-4 opacity-[0.02]">
              <Wallet className="w-12 h-12" />
            </div>
            <p className="text-label-xs font-semibold uppercase text-primary/30 group-hover:text-primary transition-colors">{tc('order_currency')}</p>
            <p className="font-mono font-semibold text-title-sm text-primary mt-2">{document?.currency_id}</p>
          </div>

          {/* Linked PO */}
          <div className="bg-surface-container-lowest p-6 rounded-2xl shadow-sm flex flex-col gap-1 group relative overflow-hidden border border-surface-variant/5">
            <div className="absolute top-0 end-0 p-4 opacity-[0.02]">
              <PackageSearch className="w-12 h-12" />
            </div>
            <p className="text-label-xs font-semibold uppercase text-primary/30 group-hover:text-primary transition-colors">{tc('ref_document')}</p>
            <div className="mt-2">
              {document?.po_number ? (
                <Badge variant="outline" className="h-8 px-4 bg-primary/5 text-primary border-primary/20 text-label-xs font-semibold uppercase rounded-lg">
                  <span dir="ltr" className="font-mono">{document.po_number}</span>
                </Badge>
              ) : (
                <p className="font-semibold text-title-sm text-primary/10 italic uppercase">{t('direct_receipt')}</p>
              )}
            </div>
          </div>

          {/* Warehouse */}
          <div className="bg-surface-container-lowest p-6 rounded-2xl shadow-sm flex flex-col gap-1 group relative overflow-hidden border border-surface-variant/5">
            <div className="absolute top-0 end-0 p-4 opacity-[0.02]">
              <Warehouse className="w-12 h-12" />
            </div>
            <p className="text-label-xs font-semibold uppercase text-primary/30 group-hover:text-primary transition-colors">{tc('warehouse')}</p>
            <p className="font-bold text-title-sm mt-2 uppercase italic text-foreground">{document?.warehouse_id === 'wh-1' ? 'Main Warehouse' : 'Kitchen Store'}</p>
          </div>

          {/* Notes */}
          <div className="col-span-full bg-surface-container-lowest p-6 rounded-2xl shadow-sm flex flex-col gap-1 group relative overflow-hidden border border-surface-variant/5">
            <div className="absolute top-0 end-0 p-4 opacity-[0.02]">
              <MessageSquare className="w-12 h-12" />
            </div>
            <p className="text-label-xs font-semibold uppercase text-primary/30 group-hover:text-primary transition-colors">{tc('notes')}</p>
            <div className="mt-2 p-4 bg-surface-container-low rounded-xl text-body-md font-medium text-foreground/70 italic">
              {document?.notes || tc('no_notes')}
            </div>
          </div>
        </div>

        {/* Lines Table */}
        <DocumentReadOnlyOverlay isPosted={true}>
          <div className="bg-surface-container-lowest rounded-[2rem] overflow-hidden shadow-sm border border-surface-variant/5">
            <DocumentLineItemTable 
              lines={document?.lines || []} 
              locale={locale} 
              isReadOnly={true}
              extraColumns={[
                {
                  header: tc('table_headers.received_qty'),
                  cell: (line: GRNLineItem) => (
                    <span dir="ltr" className="font-mono font-bold text-foreground/80">{line.received_qty}</span>
                  )
                },
                {
                  header: tc('table_headers.lot_allocation'),
                  cell: (line: GRNLineItem) => (
                    <span dir="ltr" className="font-mono text-label-xs font-semibold uppercase text-operational-cyan">
                      {line.lot?.lot_number || 'N/A'}
                    </span>
                  )
                }
              ]}
            />
          </div>
        </DocumentReadOnlyOverlay>

        {/* Financial Summary */}
        <div className="flex flex-col md:flex-row justify-end items-start md:items-center gap-8 pt-10">
          <div className="flex flex-col items-end gap-1 px-6 border-e border-surface-container-high/20">
            <p className="text-label-xs font-semibold uppercase text-muted-foreground/50">
              {t('finalized_rate')}
            </p>
            <div className="flex items-center gap-2 text-amber-500">
              <TrendingUp className="w-3 h-3" />
              <p dir="ltr" className="text-label-sm font-mono font-semibold">
                1 {document?.currency_id} = {currentFxRate} {baseCurrency}
              </p>
            </div>
          </div>

