            </span>
          </HydrationSafe>
          <span className="text-label-xxs uppercase opacity-30 font-semibold">{t('expected_date')}</span>
        </div>
      ),
    },
    {
      accessorKey: 'supplier_total_amount',
      header: t('total_amount'),
      cell: ({ row }) => (
        <div className="flex flex-col text-end">
          <span dir="ltr" className="text-body-md font-mono font-semibold text-foreground/90">
            {formatCurrency(row.original.supplier_total_amount, row.original.currency_code, locale)}
          </span>
          <span className="text-label-xxs uppercase text-muted-foreground/60 font-semibold">{t('total_amount')}</span>
        </div>
      ),
    },
    {
      id: 'actions',
      header: '',
      cell: ({ row }) => (
        <div className="flex justify-end">
          <PermissionGate action="view" resource="po">
            <Button 
              variant="ghost" 
              size="icon" 
              className="w-8 h-8 rounded-xl bg-surface-variant/10 hover:bg-amber-500/20 text-muted-foreground/60 hover:text-amber-500 transition-all group"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/purchase-orders/${row.original.id}`);
              }}
            >
              <ArrowUpRight className="w-4 h-4 transition-transform group-hover:translate-x-0.5 rtl:group-hover:-translate-x-0.5 group-hover:-translate-y-0.5 rtl:-scale-x-100" />
            </Button>
          </PermissionGate>
        </div>
      ),
    },
  ], [t, tc, locale, router]);

  const breadcrumbs = [
    { label: tc('sidebar.dashboard'), href: '/dashboard' },
    { label: t('title'), href: '/purchase-orders' },
  ];

  const totalPOs = data?.meta?.total || 0;
  
  // Metrics calculation (Note: calculated from current page data.data)
  const approvedCount = data?.data?.filter(p => isApprovedStatus('PO', p.status as DocumentStatus)).length || 0;
  const pendingCount = data?.data?.filter(p => isPendingStatus('PO', p.status as DocumentStatus)).length || 0;

 return (
 <div className="p-8 max-w-[1600px] mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-1000">
 <div className="space-y-4">
 <Breadcrumb items={breadcrumbs} />
 <PageHeader 
 title={t('title')} 
 description={t('description')}
 actions={
 <PermissionGate action="create" resource="po">
 <Link href="/purchase-orders/new">
              <Button className="h-14 px-10 bg-amber-600 hover:brightness-110 text-white text-label-xs font-black uppercase tracking-widest rounded-2xl transition-all shadow-2xl shadow-amber-900/30 border-none">
                <Plus className="w-5 h-5 me-3" />
                {t('create_new')}
              </Button>
 </Link>
 </PermissionGate>
 }
 />
 </div>

 <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
 <MetricCard
 label={t('metrics.total')}
 value={totalPOs}
 icon={ClipboardList}
 color="amber"
 />
 <MetricCard
 label={t('metrics.approved')}
 value={approvedCount}
 icon={CheckCircle2}
 color="emerald"
 />
 <MetricCard
 label={t('metrics.pending')}
 value={pendingCount}
 icon={Clock}
 color="cyan"
 />
 </div>

 <div className="bg-surface-container-low rounded-sm overflow-hidden border border-surface-variant/10 shadow-2xl shadow-primary/5">
 <DataTable 
 columns={columns}
 data={data?.data || []}
 isLoading={isLoading}
 onRowClick={(row: POSummary) => router.push(`/purchase-orders/${row.id}`)}
 collectionName="procurement_po"
 emptyState={
 <EmptyState 
 title={t('no_orders_title')}
 description={t('no_orders_desc')}
 icon={Truck}
 action={
 <PermissionGate action="create" resource="po">
 <Link href="/purchase-orders/new">
 <Button className="h-10 px-6 bg-amber-600 hover:bg-amber-500 text-white text-label-xs font-semibold uppercase rounded-sm transition-all shadow-lg">
 <Plus className="w-3.5 h-3.5 me-2" />
 {t('create_new')}
 </Button>
 </Link>
 </PermissionGate>
 }
 />
 }
 pagination={data?.meta ? {
 page: page,
 pageSize: 10,
 total: data.meta.total,
 totalPages: data.meta.total_pages,
 onPageChange: setPage
 } : undefined}
 filters={
 <div className="flex flex-wrap items-center gap-6 w-full py-6 px-8 border-b border-surface-variant/10">
 <div className="flex flex-col gap-2 min-w-[200px]">
 <label className="text-label-xxs font-semibold uppercase text-muted-foreground/60 ps-1">{tc('status_filtering')}</label>
 <Select
 value={status || 'ALL'} onValueChange={(val) => { setStatus(val === 'ALL' ? '' : (val ?? '')); setPage(1); }}
 >
 <SelectTrigger className="w-full bg-surface-variant/10 border-none h-11 px-5 text-label-xs font-bold rounded-sm shadow-inner shadow-black/5">
 <div className="flex items-center gap-2">
 <ListFilter className="w-3.5 h-3.5 text-muted-foreground/60" />
 <SelectValue placeholder={tc('status.all')} />
 </div>
 </SelectTrigger>
              <SelectContent className="bg-surface-container-highest border border-surface-variant/10 shadow-2xl rounded-sm">
                <SelectItem value="ALL" className="text-label-xs font-bold">{tc('status.all')}</SelectItem>
                <SelectItem value={PO_STATUS.DRAFT} className="text-label-xs font-bold">{tc('status.draft')}</SelectItem>
                <SelectItem value={PO_STATUS.SUBMITTED} className="text-label-xs font-bold">{tc('status.submitted')}</SelectItem>
                <SelectItem value={PO_STATUS.APPROVED} className="text-label-xs font-bold">{tc('status.approved')}</SelectItem>
                <SelectItem value={PO_STATUS.REJECTED} className="text-label-xs font-bold">{tc('status.rejected')}</SelectItem>
              </SelectContent>
 </Select>
 </div>

 <div className="flex flex-col gap-2 flex-1 min-w-[300px]">
 <label className="text-label-xxs font-semibold uppercase text-muted-foreground/60 ps-1">{tc('search')}</label>
 <div className="relative group">
 <Input
 placeholder={t('search_placeholder')}
 className="w-full bg-surface-variant/10 border-none h-11 px-11 text-label-xs font-bold rounded-sm shadow-inner shadow-black/5 transition-all focus:bg-surface-container-high"
 />
 <Search className="absolute start-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/60 group-focus-within:text-amber-500 transition-colors" />
 </div>
 </div>

 <Button variant="ghost" className="h-11 px-6 text-muted-foreground/60 hover:text-amber-500 text-label-xxs font-semibold uppercase border border-dashed border-surface-variant/10 rounded-sm hover:bg-amber-500/5 hover:border-amber-500/20 transition-all mt-6">
 <Filter className="w-3.5 h-3.5 me-2" />
 {tc('filters_button')}
 </Button>
 </div>
 }
 />
 </div>
 </div>
 );
}

'use client';

import { useTranslations } from 'next-intl';
import { useRouter } from '@/i18n/navigation';
import { usePO } from '@/features/purchasing/hooks/usePO';
import { Button } from '@/components/ui/button';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { PurchaseOrderForm } from '@/features/purchasing/components/purchase-order-form';

import { CheckCircle } from 'lucide-react';
import { isDocumentLocked, type DocumentStatus } from '@/core/workflow/document-engine';
import { ActionGuard } from '@/core/workflow/ActionGuard';
import { useAuth } from '@/providers/AuthProvider';
import { useConflictHandler } from '@/core/concurrency/useConflictHandler';
import { ConflictDialog } from '@/core/concurrency/ConflictDialog';
import { PO_STATUS } from '@/contracts/statuses';

interface PODetailClientProps {
  id: string | null;
}

/**
 * PODetailClient - Dispatcher Pattern for Purchase Orders.
 */
export function PODetailClient({ id }: PODetailClientProps) {
  const t = useTranslations('procurement.po');
  const tCommon = useTranslations('common');
  const router = useRouter();
  const { user } = useAuth();
  const { data: po, isLoading } = usePO(id || '');
  const { open, handleReload, handleClose, triggerConflict } = useConflictHandler('purchase-order', id || '');

  if (isLoading) {
    return (
      <div className="flex flex-col h-[60vh] items-center justify-center bg-surface-container-low rounded-lg animate-pulse">
        <div className="relative">
          <div className="w-12 h-12 border-4 border-primary/20 border-t-primary rounded-full animate-spin" />
        </div>
        <p className="mt-6 text-label-xs font-semibold uppercase text-primary/60">{tCommon('loading')}</p>
      </div>
    );
  }

  const isNew = !id || id === 'new';
  const status = (po?.status || PO_STATUS.DRAFT) as DocumentStatus;


  // Generate actions for the viewer (strictly navigation or read-only triggers)
  const actions = (
    <div className="flex items-center gap-3">
      <ActionGuard documentType="PO" status={status} action="APPROVE" role={user?.role || 'WH_KEEPER'}>
        <PermissionGate action="approve" resource="po">
          <Button
            onClick={() => router.push(`/purchase-orders/${id}/approve`)}
            className="bg-surface-container-highest text-foreground hover:bg-surface-container-high h-10 px-6 rounded-lg transition-all font-bold uppercase text-label-xs border border-outline-variant/50"
          >
            <CheckCircle className="w-4 h-4 me-2" />
            {t('actions.go_to_approval')}
          </Button>
        </PermissionGate>
      </ActionGuard>
    </div>
  );

  return (
    <>
      <PurchaseOrderForm 
        initialData={po} 
        mode={isNew ? 'create' : 'edit'} 
        onConflict={triggerConflict}
        actions={actions}
      />
      <ConflictDialog 
        open={open}
        onReload={handleReload}
        onClose={handleClose}
      />
    </>
  );
}

'use client';

import { useState } from 'react';
import { useRouter } from '@/i18n/navigation';
import { useTranslations, useLocale } from 'next-intl';
import { usePO } from '@/features/purchasing/hooks/usePO';
import { useApprovePO } from '@/features/purchasing/hooks/useApprovePO';
import { useRejectPO } from '@/features/purchasing/hooks/useRejectPO';
import { Button } from '@/components/ui/button';
import { PageHeader } from '@/components/shared/PageHeader';
import { Card, CardContent } from '@/components/ui/card';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';
import { useQueryClient } from '@tanstack/react-query';
import { useAuth } from '@/providers/AuthProvider';
import { canPerformActionV2, type DocumentStatus } from '@/core/workflow/document-engine';
import { 
  CheckCircle2, 
  XCircle, 
  AlertCircle, 
  FileText, 
  ClipboardCheck, 
  MessageSquare,
  ArrowLeft,
  ShieldCheck
} from 'lucide-react';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';
import { PostConfirmDialog } from '@/components/shared/PostConfirmDialog';
import { formatCurrency } from '@/utils/currency';

interface Props {
  id: string;
  locale: 'ar' | 'en';
}

export function POApproveClient({ id }: Props) {
  const t = useTranslations('procurement.po');
  const tc = useTranslations('common');
  const locale = useLocale();
  const router = useRouter();
  const { user } = useAuth();
  
  const { data: po, isLoading } = usePO(id);
  const queryClient = useQueryClient();
  const approveMutation = useApprovePO();
  const rejectMutation = useRejectPO();
  
  const [comment, setComment] = useState('');
  const [isRejecting, setIsRejecting] = useState(false);
  const [approveConfirmOpen, setApproveConfirmOpen] = useState(false);
  const [rejectConfirmOpen, setRejectConfirmOpen] = useState(false);

  const canApprove = po ? canPerformActionV2('PO', po.status as DocumentStatus, 'APPROVE', user?.role) : false;
  const canReject = po ? canPerformActionV2('PO', po.status as DocumentStatus, 'REJECT', user?.role) : false;

  if (isLoading) {
    return <PageSkeleton />;
  }

  if (!po) {
    return <ErrorState message={tc('not_found')} onRetry={() => queryClient.invalidateQueries({ queryKey: ['purchase-order', id] })} />;
  }

  const handleApprove = async () => {
    try {
      await approveMutation.mutateAsync({ id, version: po.version || 1 });
      toast.success(t('approval.approve_success'));
      router.push('/purchase-orders');
    } catch (e) {
      console.error(e);
      toast.error(tc('error'));
    }
  };

  const handleReject = async () => {
    if (!comment || comment.length < 15) {
      toast.error(t('approval.rejection_reason_min_chars'));
      return;
    }
    
    try {
      await rejectMutation.mutateAsync({ id, reason: comment, version: po.version || 1 });
      toast.success(t('approval.reject_success'));
      router.push('/purchase-orders');
    } catch (e) {
      console.error(e);
      toast.error(tc('error'));
    }
  };

  return (
    <div className="flex flex-col gap-8 pb-20 max-w-5xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex items-center gap-4 mb-2">
        <Button 
          variant="ghost" 
          size="sm" 
          onClick={() => router.back()}
          className="rounded-full hover:bg-surface-container-high text-muted-foreground"
        >
          <ArrowLeft className="w-4 h-4 me-2" />
          {tc('back')}
        </Button>
      </div>

      <div className="flex flex-col gap-4">
        <div className="flex items-center gap-2 text-label-xs font-semibold uppercase text-operational-cyan/60">
          <ShieldCheck className="w-3.5 h-3.5" />
          <span>{t('approval.workflow')}</span>
        </div>
        <PageHeader
          title={t('approval.title')}
          description={`${t('approval.description')} #${po.document_number}`}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          {/* Summary Card */}
          <Card className="bg-surface-container-low border-none rounded-3xl shadow-sm overflow-hidden">
            <CardContent className="p-8 space-y-8">
              <div className="flex items-center gap-4 pb-6 border-b border-white/5">
                <div className="w-12 h-12 rounded-2xl bg-operational-cyan/10 flex items-center justify-center">
                  <ClipboardCheck className="w-6 h-6 text-operational-cyan" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold uppercase text-foreground">
                    {t('approval.summary_title')}
                  </h3>
                  <p className="text-label-xs font-bold text-muted-foreground/60 uppercase mt-1">
                    {t('approval.summary_subtitle')}
                  </p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-8">
                <div className="space-y-1.5">
                  <p className="text-label-xs font-semibold uppercase text-muted-foreground/40">{tc('supplier')}</p>
                  <p className="font-bold text-title-sm">{po.supplier_name || po.supplier_id}</p>
                </div>
                <div className="space-y-1.5">
                  <p className="text-label-xs font-semibold uppercase text-muted-foreground/40">{t('approval.order_total')}</p>
                  <p className="font-mono font-semibold text-title-lg text-operational-cyan">
                    {formatCurrency(po.total || 0, po.currency_id, locale as 'ar' | 'en')}
                  </p>
                </div>
                <div className="space-y-1.5">
                  <p className="text-label-xs font-semibold uppercase text-muted-foreground/40">{t('approval.target_warehouse')}</p>
                  <p className="font-bold text-title-sm">{po.warehouse_name || po.target_warehouse_id}</p>
                </div>
                <div className="space-y-1.5">
                  <p className="text-label-xs font-semibold uppercase text-muted-foreground/40">{t('approval.expected_delivery_date')}</p>
                  <p dir="ltr" className="font-mono font-bold text-title-sm">{po.expected_delivery_date || '—'}</p>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Comment Area */}
          <Card className="bg-surface-container-low border-none rounded-3xl shadow-sm overflow-hidden">
            <CardContent className="p-8 space-y-6">
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 rounded-xl bg-tertiary-container/10 flex items-center justify-center">
                  <MessageSquare className="w-5 h-5 text-tertiary" />
                </div>
                <Label className="text-label-xs font-semibold uppercase text-foreground">
                  {t('approval.rejection_reason_label')}
                </Label>
              </div>
              
              <Textarea 
                placeholder={t('approval.rejection_reason_placeholder')}
                value={comment}
                onChange={(e) => setComment(e.target.value)}
                className="min-h-[120px] bg-surface-container-high/40 border-none rounded-2xl p-4 text-body-md font-medium focus:ring-1 focus:ring-operational-cyan/30 resize-none transition-all"
              />
              
              {isRejecting && (!comment || comment.length < 15) && (
                <div className="flex items-center gap-2 text-rose-400 p-4 bg-rose-400/5 rounded-2xl border border-rose-400/10">
                  <AlertCircle className="w-4 h-4" />
                  <p className="text-label-xs font-semibold uppercase">{t('approval.rejection_reason_min_chars')}</p>
                </div>
              )}
            </CardContent>
          </Card>
        </div>

        {/* Action Panel */}
        <div className="space-y-8">
          <Card className="bg-surface-container-low border-none rounded-3xl shadow-sm overflow-hidden sticky top-24">
            <CardContent className="p-8 space-y-8">
              <div className="space-y-6">
                <Button
                  onClick={() => setApproveConfirmOpen(true)}
                  disabled={approveMutation.isPending || rejectMutation.isPending || isRejecting || !canApprove}
                  className="w-full bg-operational-cyan text-primary-foreground hover:brightness-110 h-14 rounded-2xl transition-all font-black uppercase text-label-xs tracking-widest shadow-[0_8px_20px_rgba(var(--operational-cyan-rgb),0.2)]"
                >
                  <CheckCircle2 className="w-5 h-5 me-3" />
                  {t('approval.approve_po')}
                </Button>

                <div className="relative">
                  <div className="absolute inset-0 flex items-center">
                    <span className="w-full border-t border-white/5" />
                  </div>
                  <div className="relative flex justify-center text-label-xs uppercase font-semibold text-muted-foreground/30">
                    <span className="bg-surface-container-low px-4">{tc('or')}</span>
                  </div>
                </div>

                {!isRejecting ? (
                  <Button
                    variant="outline"
                    onClick={() => setIsRejecting(true)}
                    disabled={!canReject}
                    className="w-full border-red-500/20 text-red-400 hover:bg-red-500/5 h-14 rounded-2xl font-black uppercase text-label-xs tracking-widest transition-all"
                  >
                    <XCircle className="w-5 h-5 me-3" />
                    {t('approval.reject_po')}
                  </Button>
                ) : (
                  <div className="space-y-4">
                    <Button
                      onClick={() => setRejectConfirmOpen(true)}
                      disabled={!comment || comment.length < 15 || rejectMutation.isPending}
                      className="w-full bg-red-500 text-white hover:bg-red-600 h-14 rounded-2xl font-black uppercase text-label-xs tracking-widest transition-all shadow-[0_8px_20px_rgba(239,68,68,0.2)]"
                    >
                      <XCircle className="w-5 h-5 me-3" />
                      {t('approval.confirm_rejection')}
                    </Button>
                    <Button
                      variant="ghost"
                      onClick={() => {
                        setIsRejecting(false);
                        setComment("");
                      }}
                      className="w-full text-muted-foreground/60 hover:text-foreground h-12 rounded-xl font-black uppercase text-label-xs tracking-widest transition-all"
                    >
                      {tc('cancel')}
                    </Button>
                  </div>
                )}
              </div>

              <div className="p-6 bg-surface-container-high/40 rounded-2xl space-y-4">
                <div className="flex items-center gap-2 opacity-40">
                  <AlertCircle className="w-4 h-4" />
                  <p className="text-label-xs font-semibold uppercase">{t('approval.legal_notice.title')}</p>
                </div>
                <p className="text-label-xs text-muted-foreground leading-relaxed font-medium">
                  {t('approval.legal_notice.text')}
                </p>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>

      <PostConfirmDialog
        open={approveConfirmOpen}
        onOpenChange={setApproveConfirmOpen}
        onConfirm={handleApprove}
        title={t('approval.approve_confirm_title')}
        description={t('approval.approve_confirm_desc')}
        confirmText={t('approval.approve_po')}
        variant="default"
      />

      <PostConfirmDialog
        open={rejectConfirmOpen}
        onOpenChange={setRejectConfirmOpen}
        onConfirm={handleReject}
        title={t('approval.reject_confirm_title')}
        description={t('approval.reject_confirm_desc')}
        confirmText={t('approval.reject_po')}
        variant="destructive"
        icon="reject"
        disabled={comment.length < 15}
      />
    </div>
  );
}

