'use client';

import { useState, useMemo } from 'react';
import { useRouter, Link } from '@/i18n/navigation';
import { useTranslations, useLocale } from 'next-intl';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { ColumnDef } from '@tanstack/react-table';
import { usePRList, PRSummary } from '@/features/purchasing/hooks/usePRList';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { Button } from '@/components/ui/button';
import { Plus, Filter, ClipboardList, CheckCircle2, Clock, ArrowUpRight, ListFilter, Search } from 'lucide-react';
import { format } from 'date-fns';
import { StatusBadge, type BadgeStatus } from '@/components/shared/StatusBadge';
import { HydrationSafe } from '@/components/ui/HydrationSafe';
import { PageHeader } from '@/components/shared/PageHeader';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { MetricCard } from '@/components/ui/metric-card';
import { EmptyState } from '@/components/shared/EmptyState';
import { isDocumentLocked, canPerformActionV2, DocumentStatus, isApprovedStatus, isPendingStatus } from '@/core/workflow/document-engine';
import { PR_STATUS } from '@/contracts/statuses';

export function PRListClient() {
 const locale = useLocale();
 const t = useTranslations('procurement.pr');
 const tc = useTranslations('common');
 const router = useRouter();

 const [page, setPage] = useState(1);
 const [status, setStatus] = useState<string>('');

 const { data, isLoading } = usePRList({ status, page });

 const columns = useMemo<ColumnDef<PRSummary, unknown>[]>(() => [
 {
 accessorKey: 'status',
 header: tc('status_label'),
 cell: ({ row }) => <StatusBadge status={row.original.status as BadgeStatus} />,
 },
 {
 accessorKey: 'document_number',
 header: tc('doc_number'),
 cell: ({ row }) => (
 <span dir="ltr" className="font-mono text-cyan-500 font-bold drop-shadow-[0_0_8px_rgba(6,182,212,0.4)]">
 {row.original.document_number}
 </span>
 ),
 },
 {
 accessorKey: 'warehouse_id',
 header: tc('warehouse'),
 cell: ({ row }) => (
 <div className="flex flex-col">
 <span className="opacity-90 font-bold text-body-md text-start">{row.original.warehouse_id}</span>
 <span className="text-label-xxs uppercase text-muted-foreground/60 font-semibold text-start">{tc('warehouse')}</span>
 </div>
 ),
 },
 {
 accessorKey: 'created_at',
 header: tc('created_at'),
 cell: ({ row }) => (
 <div className="flex flex-col">
 <span dir="ltr" className="text-label-xs font-mono font-semibold text-foreground/80">
 <HydrationSafe>{format(new Date(row.original.created_at), 'dd/MM/yyyy HH:mm')}</HydrationSafe>
 </span>
 <span className="text-label-xxs uppercase opacity-30 font-semibold text-start">{tc('created_at')}</span>
 </div>
 ),
 },
 {
 accessorKey: 'created_by',
 header: t('requested_by'),
 cell: ({ row }) => (
 <div className="flex flex-col">
 <span className="opacity-90 font-bold text-body-md text-start">{row.original.created_by}</span>
 <span className="text-label-xxs uppercase text-muted-foreground/60 font-semibold text-start">{t('requested_by')}</span>
 </div>
 ),
 },
 {
 id: 'actions',
 header: '',
 cell: ({ row }) => (
 <div className="flex justify-end">
 <PermissionGate action="view" resource="pr">
 <Button 
 variant="ghost" 
 size="icon" 
 className="w-8 h-8 rounded-xl bg-surface-variant/10 hover:bg-cyan-500/20 text-muted-foreground/60 hover:text-cyan-500 transition-all group"
 onClick={() => {
  router.push(`/purchase-requests/${row.original.id}`);
 }}
 >
 <ArrowUpRight className="w-4 h-4 transition-transform group-hover:translate-x-0.5 rtl:group-hover:-translate-x-0.5 group-hover:-translate-y-0.5 rtl:-scale-x-100" />
 </Button>
 </PermissionGate>
 </div>
 ),
 },
 ], [t, tc, locale, router]);

 const breadcrumbs = [
  { label: tc('sidebar.dashboard'), href: '/dashboard' },
  { label: t('title'), href: '/purchase-requests' },
 ];

  const totalPRs = data?.meta?.total || 0;
  
  // Metrics calculation (Note: calculated from current page data.data)
  const approvedCount = data?.data?.filter(p => isApprovedStatus('PR', p.status as DocumentStatus)).length || 0;
  const pendingCount = data?.data?.filter(p => isPendingStatus('PR', p.status as DocumentStatus)).length || 0;

 return (
 <div className="p-8 max-w-[1600px] mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-1000">
 <div className="space-y-4">
 <Breadcrumb items={breadcrumbs} />
 <PageHeader 
 title={t('title')} 
 description={t('description')}
 actions={
 <PermissionGate action="create" resource="pr">
  <Link href="/purchase-requests/new">
              <Button className="h-14 px-10 bg-operational-cyan hover:brightness-110 text-white text-label-xs font-black uppercase tracking-widest rounded-2xl transition-all shadow-2xl shadow-operational-cyan/30 border-none">
                <Plus className="w-5 h-5 me-3" />
                {t('create_new')}
              </Button>
 </Link>
 </PermissionGate>
 }
 />
 </div>

 <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
 <MetricCard
 label={t('metrics.total')}
 value={totalPRs}
 icon={ClipboardList}
 color="cyan"
 />
 <MetricCard
 label={t('metrics.approved')}
 value={approvedCount}
 icon={CheckCircle2}
 color="emerald"
 />
 <MetricCard
 label={t('metrics.pending')}
 value={pendingCount}
 icon={Clock}
 color="amber"
 />
 </div>

 <div className="bg-surface-container-low rounded-sm overflow-hidden border border-surface-variant/10 shadow-2xl shadow-primary/5">
 <DataTable 
 columns={columns}
 data={data?.data || []}
 isLoading={isLoading}
  onRowClick={(row: PRSummary) => router.push(`/purchase-requests/${row.id}`)}
 collectionName="procurement_pr"
 emptyState={
 <EmptyState 
 title={t('no_requests_title')}
 description={t('no_requests_desc')}
 action={
 <PermissionGate action="create" resource="pr">
  <Link href="/purchase-requests/new">
 <Button className="h-10 px-6 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-semibold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
 <Plus className="w-3.5 h-3.5 me-2" />
 {t('create_new')}
 </Button>
 </Link>
 </PermissionGate>
 }
 />
 }
 pagination={data?.meta ? {
 page: page,
 pageSize: 10,
 total: data.meta.total,
 totalPages: data.meta.total_pages,
 onPageChange: setPage
 } : undefined}
 filters={
 <div className="flex flex-wrap items-center gap-6 w-full py-6 px-8 border-b border-surface-variant/10">
 <div className="flex flex-col gap-2 min-w-[200px]">
 <label className="text-label-xxs font-semibold uppercase text-muted-foreground/60 ps-1">{tc('status_filtering')}</label>
 <Select
 value={status || 'ALL'} onValueChange={(val) => { setStatus(val === 'ALL' ? '' : (val ?? '')); setPage(1); }}
 >
 <SelectTrigger className="w-full bg-surface-variant/10 border-none h-11 px-5 text-label-xs font-bold rounded-sm shadow-inner shadow-black/5">
 <div className="flex items-center gap-2">
 <ListFilter className="w-3.5 h-3.5 text-muted-foreground/60" />
 <SelectValue placeholder={tc('status.all')} />
 </div>
 </SelectTrigger>
                <SelectContent className="bg-surface-container-highest border border-surface-variant/10 shadow-2xl rounded-sm">
                  <SelectItem value="ALL" className="text-label-xs font-bold">{tc('status.all')}</SelectItem>
                  <SelectItem value={PR_STATUS.DRAFT} className="text-label-xs font-bold">{tc('status.draft')}</SelectItem>
                  <SelectItem value={PR_STATUS.SUBMITTED} className="text-label-xs font-bold">{tc('status.submitted')}</SelectItem>
                  <SelectItem value={PR_STATUS.APPROVED} className="text-label-xs font-bold">{tc('status.approved')}</SelectItem>
                  <SelectItem value={PR_STATUS.REJECTED} className="text-label-xs font-bold">{tc('status.rejected')}</SelectItem>
                </SelectContent>
 </Select>
 </div>

 <div className="flex flex-col gap-2 flex-1 min-w-[300px]">
 <label className="text-label-xxs font-semibold uppercase text-muted-foreground/60 ps-1">{tc('search')}</label>
 <div className="relative group">
 <Input
 placeholder={t('search_placeholder')}
 className="w-full bg-surface-variant/10 border-none h-11 px-11 text-label-xs font-bold rounded-sm shadow-inner shadow-black/5 transition-all focus:bg-surface-container-high"
 />
 <Search className="absolute start-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/60 group-focus-within:text-cyan-500 transition-colors" />
 </div>
 </div>

 <Button variant="ghost" className="h-11 px-6 text-muted-foreground/60 hover:text-cyan-500 text-label-xxs font-semibold uppercase border border-dashed border-surface-variant/10 rounded-sm hover:bg-cyan-500/5 hover:border-cyan-500/20 transition-all mt-6">
 <Filter className="w-3.5 h-3.5 me-2" />
 {tc('filters_button')}
 </Button>
 </div>
 }
 />
 </div>
 </div>
 );
}

'use client';

import { useTranslations } from 'next-intl';
import { usePR } from '@/features/purchasing/hooks/usePR';
import { Package } from 'lucide-react';
import { PurchaseRequestForm } from '@/features/purchasing/components/purchase-request-form';
import { useConflictHandler } from '@/core/concurrency/useConflictHandler';
import { ConflictDialog } from '@/core/concurrency/ConflictDialog';
import { PageSkeleton } from '@/components/shared/PageSkeleton';

export function PRDetailClient({ id }: { id: string | null }) {
  const t = useTranslations('procurement.pr');
  const { data: pr, isLoading } = usePR(id);
  const { open, handleReload, handleClose, triggerConflict } = useConflictHandler('purchase-request', id || '');

  if (isLoading) return <PageSkeleton variant="detail" />;

  if (!pr) return null;

  return (
    <>
      <PurchaseRequestForm initialData={pr} onConflict={triggerConflict} />
      <ConflictDialog 
        open={open}
        onReload={handleReload}
        onClose={handleClose}
      />
    </>
  );
}

'use client';

import * as React from 'react';
import { useForm, useFieldArray } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Trash2, Plus, Calendar, Package, Calculator, ArrowLeft, Send, Save, Building2 } from 'lucide-react';
import { useTranslations, useLocale } from 'next-intl';
import { useRouter, Link } from '@/i18n/navigation';
import { toast } from 'sonner';

import {
 Form,
 FormControl,
 FormField,
 FormItem,
 FormLabel,
 FormMessage,
} from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { PostConfirmDialog } from '@/components/shared/PostConfirmDialog';
import { useCreatePR } from '@/features/purchasing/hooks/useCreatePR';
import { useUpdatePR } from '@/features/purchasing/hooks/useUpdatePR';
import { useSubmitPR } from '@/features/purchasing/hooks/useSubmitPR';
import { PRDetail } from '@/features/purchasing/hooks/usePR';
import { useMasterDataList } from '@/features/master-data/hooks/useMasterDataCRUD';
import { ScanInput } from '@/components/shared/ScanInput/ScanInput';
import { Item, Warehouse, ItemSchema, WarehouseSchema } from '@/types/master-data';

const lineItemSchema = z.object({
 id: z.string().optional(), // For existing lines
 item_id: z.string().min(1),
 item_name: z.string().optional(),
 item_code: z.string().optional(),
 req_qty: z.number().min(0.01),
 uom_id: z.string().min(1),
});

const formSchema = z.object({
 department_id: z.string().min(1),
 expected_date: z.string().min(1),
 notes: z.string().optional(),
 lines: z.array(lineItemSchema).min(1),
});

type PurchaseRequestFormValues = z.infer<typeof formSchema>;

interface PurchaseRequestFormProps {
  initialData?: PRDetail;
  onConflict?: () => void;
}

export function PurchaseRequestForm({ initialData, onConflict }: PurchaseRequestFormProps) {
  const locale = useLocale();
 const t = useTranslations('procurement.pr');
 const tc = useTranslations('common');
 const router = useRouter();
 const [isSubmitting, setIsSubmitting] = React.useState(false);
 const [submitConfirmOpen, setSubmitConfirmOpen] = React.useState(false);
 const [pendingValues, setPendingValues] = React.useState<PurchaseRequestFormValues | null>(null);

 // Mocks/Hooks for data selection
 const { data: warehouses } = useMasterDataList('warehouses', WarehouseSchema);
 const { data: itemsData } = useMasterDataList('items', ItemSchema);

  const createPR = useCreatePR();
  const updatePR = useUpdatePR({ onConflict });
  const submitPR = useSubmitPR({ onConflict });

 const form = useForm<PurchaseRequestFormValues>({
 resolver: zodResolver(formSchema),
 defaultValues: initialData ? {
 department_id: initialData.department_id,
 expected_date: initialData.expected_date.split('T')[0],
 notes: initialData.notes || '',
 lines: initialData.lines.map(l => ({
 id: l.id,
 item_id: l.item.id,
 item_name: locale === 'ar' ? l.item.name_ar : l.item.name_en,
 item_code: l.item.code,
 req_qty: l.req_qty,
 uom_id: l.uom_id,
 })),
 } : {
 department_id: '',
 expected_date: '',
 notes: '',
 lines: [],
 },
 });

 const { fields, append, remove } = useFieldArray({
 control: form.control,
 name: 'lines',
 });

 const handleScan = (barcode: string) => {
 const item = itemsData?.data?.find((i: Item) => i.barcode === barcode || i.code === barcode);
 if (item) {
 append({
 item_id: item.id,
 item_name: locale === 'ar' ? item.name_ar : item.name_en,
 item_code: item.code,
 req_qty: 1,
 uom_id: item.primary_uom?.id || 'EA',
 });
 toast.success(tc('items') + ': ' + (locale === 'ar' ? item.name_ar : item.name_en));
 } else {
 toast.error(tc('not_found'));
 }
 };

 const onSave = async (values: PurchaseRequestFormValues, submitAfterSave = false) => {
 setIsSubmitting(true);
 try {
 let prId = initialData?.id;
 
  if (prId) {
  await updatePR.mutateAsync({ 
  id: prId, 
  payload: { ...values, version: initialData?.version ?? 0 } 
  });
  } else {
  const res = await createPR.mutateAsync(values);
  prId = res.id;
  }

  if (submitAfterSave && prId) {
  const currentVersion = initialData ? ((initialData.version ?? 0) + 1) : 1;
  await submitPR.mutateAsync({ id: prId, version: currentVersion });
  toast.success(t('submit_success'));
  } else {
  toast.success(tc('save') + ' ' + tc('completed'));
  }

 router.push('/purchase-requests');
 } catch (error) {
 console.error(error);
 toast.error(tc('error'));
 } finally {
 setIsSubmitting(false);
 setSubmitConfirmOpen(false);
 }
 };

 const handleSubmitClick = (values: PurchaseRequestFormValues) => {
 setPendingValues(values);
 setSubmitConfirmOpen(true);
 };

 return (
 <Form {...form}>
 <form onSubmit={form.handleSubmit((v) => onSave(v, false))} className="space-y-10 w-full bg-surface-container-lowest p-8 rounded-[2rem] relative pb-20">
 <div className="flex items-center justify-between">
 <h3 className="text-title-lg font-semibold text-operational-cyan uppercase">{t('detail_title')}</h3>
 {initialData?.document_number && (
 <span className="font-mono text-label-sm font-semibold text-muted-foreground/40">
 {initialData.document_number}
 </span>
 )}
 </div>
 
 {/* Step 1: Request Header */}
 <div className="bg-surface-container-low p-8 rounded-[2rem] relative">
 <div className="flex items-center gap-4 mb-8 pb-6 border-none">
 <div className="p-3 rounded-2xl bg-operational-cyan/10 text-operational-cyan">
 <Building2 className="w-5 h-5" />
 </div>
 <div>
 <h3 className="text-body-md font-semibold uppercase text-foreground">{t('new_intent')}</h3>
 <p className="text-label-xs font-bold text-muted-foreground/60 uppercase mt-0.5">{t('specification')}</p>
 </div>
 </div>
 
 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
 <FormField<PurchaseRequestFormValues, 'department_id'>
 control={form.control}
 name="department_id"
 render={({ field }) => (
 <FormItem>
 <FormLabel className="text-label-xs font-semibold uppercase text-muted-foreground/40 mb-3 flex items-center gap-2 ps-1">
 <Package className="w-3 h-3" />
 {t('department')}
 </FormLabel>
 <Select onValueChange={field.onChange} defaultValue={field.value}>
 <FormControl>
 <SelectTrigger className="bg-surface-container-lowest border-none h-11 rounded-xl text-label-xs font-semibold uppercase focus:ring-1 focus:ring-operational-cyan/30">
 <SelectValue placeholder={tc('select_warehouse')} />
 </SelectTrigger>
 </FormControl>
 <SelectContent className="bg-surface-container-low border-none rounded-2xl">
 {warehouses?.data?.map((w: Warehouse) => (
 <SelectItem key={w.id} value={w.id} className="text-label-xs font-bold">
 {locale === 'ar' ? w.name_ar : w.name_en}
 </SelectItem>
 ))}
 </SelectContent>
 </Select>
 <FormMessage className="text-label-xxs font-semibold uppercase" />
 </FormItem>
 )}
 />

 <FormField<PurchaseRequestFormValues, 'expected_date'>
 control={form.control}
 name="expected_date"
 render={({ field }) => (
 <FormItem>
 <FormLabel className="text-label-xs font-semibold uppercase text-muted-foreground/40 mb-3 flex items-center gap-2 ps-1">
 <Calendar className="w-3 h-3" />
 {t('expected_date')}
 </FormLabel>
 <FormControl>
 <Input type="date" className="bg-surface-container-lowest border-none h-11 rounded-xl font-semibold text-label-xs uppercase focus-visible:ring-operational-cyan/30" {...field} />
 </FormControl>
 <FormMessage className="text-label-xxs font-semibold uppercase" />
 </FormItem>
 )}
 />

 <FormField<PurchaseRequestFormValues, 'notes'>
 control={form.control}
 name="notes"
 render={({ field }) => (
 <FormItem className="lg:col-span-3">
 <FormLabel className="text-label-xs font-semibold uppercase text-muted-foreground/40 mb-3 ps-1">{tc('notes')}</FormLabel>
 <FormControl>
 <Input placeholder={tc('notes')} className="bg-surface-container-lowest border-none h-11 rounded-xl font-semibold text-label-xs uppercase focus-visible:ring-operational-cyan/30" {...field} />
 </FormControl>
 <FormMessage className="text-label-xxs font-semibold uppercase" />
 </FormItem>
 )}
 />
 </div>
 </div>

 {/* Step 2: Line Items */}
 <div className="space-y-6">
 <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 px-2">
 <div className="flex items-center gap-4">
 <div className="p-2.5 rounded-xl bg-status-warning/10 text-status-warning">
 <Calculator className="w-4 h-4" />
 </div>
 <div>
 <h3 className="text-label-xs font-semibold uppercase text-muted-foreground/70">{tc('items')}</h3>
 <p className="text-label-xxs font-semibold text-muted-foreground/30 uppercase mt-0.5">{t('specification')}</p>
 </div>
 </div>
 
 <div className="flex-1 max-w-md">
 <ScanInput 
 onScan={handleScan}
 placeholder={tc('select_item')}
 className="h-12"
 />
 </div>

 <Button 
 type="button" 
 variant="outline" 
 size="sm" 
 className="h-12 px-6 border-none text-operational-cyan bg-operational-cyan/10 hover:bg-operational-cyan hover:text-white rounded-xl text-label-xs font-semibold uppercase transition-all"
 onClick={() => append({ item_id: '', item_name: '', item_code: '', req_qty: 1, uom_id: 'EA' })}
 >
 <Plus className="h-3.5 w-3.5 me-2" />
 {tc('create')}
 </Button>
 </div>

 <div className="grid grid-cols-1 gap-4">
 {fields.map((field, index) => (
 <div key={field.id} className="grid grid-cols-1 lg:grid-cols-[2fr_1fr_1fr_auto] gap-6 items-end bg-surface-container-low/50 p-6 rounded-2xl group hover:bg-surface-container transition-all">
 <FormField<PurchaseRequestFormValues, `lines.${number}.item_id`>
 control={form.control}
 name={`lines.${index}.item_id`}
 render={({ field: inputField }) => (
 <FormItem>
 <FormLabel className="text-label-xxs font-semibold uppercase text-muted-foreground/40 mb-2">{tc('item')}</FormLabel>
 <Select 
 onValueChange={(val) => {
 const item = itemsData?.data?.find((i: Item) => i.id === val);
 form.setValue(`lines.${index}.item_id`, val as string);
 form.setValue(`lines.${index}.item_name`, locale === 'ar' ? item?.name_ar : item?.name_en);
 form.setValue(`lines.${index}.item_code`, item?.code);
 form.setValue(`lines.${index}.uom_id`, item?.primary_uom?.id || 'EA');
 }} 
 value={inputField.value}
 >
 <FormControl>
 <SelectTrigger className="bg-surface-container-low border-none h-11 rounded-xl text-label-xs font-semibold uppercase focus:ring-1 focus:ring-operational-cyan/30">
 <SelectValue placeholder={tc('select_item')} />
 </SelectTrigger>
 </FormControl>
 <SelectContent className="bg-surface-container-low border-none rounded-2xl max-h-[300px]">
 {itemsData?.data?.map((i: Item) => (
 <SelectItem key={i.id} value={i.id} className="text-label-xs font-bold">
 {i.code} - {locale === 'ar' ? i.name_ar : i.name_en}
 </SelectItem>
 ))}
 </SelectContent>
 </Select>
 <FormMessage className="text-label-xxs font-semibold" />
 </FormItem>
 )}
 />

 <FormField<PurchaseRequestFormValues, `lines.${number}.req_qty`>
 control={form.control}
 name={`lines.${index}.req_qty`}
 render={({ field: inputField }) => (
 <FormItem>
 <FormLabel className="text-label-xxs font-semibold uppercase text-muted-foreground/40 mb-2">{t('requested_qty')}</FormLabel>
 <FormControl>
 <Input 
 type="number" 
 step="0.01"
 className="bg-surface-container-low border-none h-11 rounded-xl font-mono font-semibold text-label-xs focus-visible:ring-operational-cyan/30" 
 dir="ltr"
 {...inputField} 
 onChange={(e) => inputField.onChange(e.target.valueAsNumber || 0)}
 />
 </FormControl>
 <FormMessage />
 </FormItem>
 )}
 />

 <FormField<PurchaseRequestFormValues, `lines.${number}.uom_id`>
 control={form.control}
 name={`lines.${index}.uom_id`}
 render={({ field: inputField }) => (
 <FormItem>
 <FormLabel className="text-label-xxs font-semibold uppercase text-muted-foreground/40 mb-2">{tc('uom')}</FormLabel>
 <FormControl>
 <Input disabled className="bg-surface-container-high/10 border-none h-11 rounded-xl font-semibold text-label-xs uppercase opacity-50" {...inputField} />
 </FormControl>
 <FormMessage />
 </FormItem>
 )}
 />

 <Button 
 type="button" 
 variant="ghost" 
 size="icon" 
 className="w-10 h-10 rounded-xl text-muted-foreground/20 hover:text-status-error hover:bg-status-error/10 transition-all border-none"
 onClick={() => remove(index)}
 >
 <Trash2 className="h-4 w-4" />
 </Button>
 </div>
 ))}
 {fields.length === 0 && (
 <div className="py-12 border-2 border-dashed border-surface-variant/10 rounded-3xl flex flex-col items-center justify-center text-muted-foreground/20 italic text-label-xs font-semibold uppercase">
 {tc('no_items')}
 </div>
 )}
 </div>
 
 {/* Summary */}
 <div className="flex flex-col md:flex-row items-center justify-between gap-6 p-8 bg-surface-container-low rounded-[2rem]">
 <div className="flex items-center gap-4">
 <div className="w-12 h-12 rounded-2xl bg-operational-cyan/10 flex items-center justify-center">
