 Warehouse, 
 CheckCircle2, 
 ChevronRight, 
 LayoutDashboard,
 Globe,
 Settings2
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useState } from 'react';

export function ContextSelectorClient({ locale }: { locale: string }) {
 const t = useTranslations('context_selector');
 const router = useRouter();
 const { user, activeScope, setActiveScope } = useAuth();
 
 const { data: branchesData } = useBranches();
 const { data: warehousesData } = useWarehouses();

 const branches = branchesData?.data || [];
 const warehouses = warehousesData?.data || [];

 const [selectedBranchId, setSelectedBranchId] = useState<string | null>(activeScope.branchId);
 const [selectedWarehouseId, setSelectedWarehouseId] = useState<string | null>(activeScope.warehouseId);

 const handleConfirm = () => {
 setActiveScope({
 branchId: selectedBranchId,
 warehouseId: selectedWarehouseId,
 departmentId: activeScope.departmentId // Preserve department if any
 });
 router.push('/dashboard');
 };

 const filteredWarehouses = warehouses?.filter(wh => wh.branch_id === selectedBranchId) || [];

 return (
 <div className="min-h-[80vh] flex flex-col items-center justify-center py-12 px-6">
 <div className="w-full max-w-5xl space-y-12">
 {/* Header Section */}
 <div className="text-center space-y-4">
 <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-operational-cyan/10 rounded-full border border-operational-cyan/20">
 <Globe className="w-3.5 h-3.5 text-operational-cyan" />
 <span className="text-label-xs font-semibold uppercase text-operational-cyan">{t('environment')}</span>
 </div>
 <h1 className="text-headline-lg font-semibold uppercase italic bg-gradient-to-e from-foreground to-foreground/40 bg-clip-text text-transparent">
 {t('title')}
 </h1>
 <p className="text-muted-foreground/60 text-body-md font-medium uppercase max-w-md mx-auto leading-relaxed">
 {t('description')}
 </p>
 </div>

 <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
 {/* Branch Selection */}
 <div className="space-y-6">
 <div className="flex items-center gap-3 ps-4">
 <Building2 className="w-5 h-5 text-operational-cyan/40" />
 <h3 className="text-label-xs font-semibold uppercase text-muted-foreground">{t('select_branch')}</h3>
 </div>
 
 <div className="grid gap-4">
 {branches?.map((branch) => (
 <button
 key={branch.id}
 onClick={() => {
 setSelectedBranchId(branch.id);
 setSelectedWarehouseId(null); // Reset warehouse when branch changes
 }}
 className={cn(
 "relative p-6 rounded-[2rem] text-start transition-all duration-500 group overflow-hidden border border-white/5",
 selectedBranchId === branch.id 
 ? "bg-operational-cyan shadow-[0_20px_40px_rgba(var(--operational-cyan-rgb),0.2)]" 
 : "bg-surface-container-low hover:bg-surface-container-high"
 )}
 >
 <div className="relative z-10 flex items-center justify-between">
 <div className="space-y-1">
 <p className={cn(
 "text-label-xs font-semibold uppercase",
 selectedBranchId === branch.id ? "text-primary-foreground/60" : "text-muted-foreground/40"
 )}>
 {branch.code}
 </p>
 <p className={cn(
 "text-title-sm font-bold",
 selectedBranchId === branch.id ? "text-primary-foreground" : "text-foreground"
 )}>
 {locale === 'ar' ? branch.name_ar : branch.name_en}
 </p>
 </div>
 {selectedBranchId === branch.id && (
 <div className="w-10 h-10 rounded-full bg-white/20 flex items-center justify-center animate-in zoom-in-50 duration-500">
 <CheckCircle2 className="w-6 h-6 text-white" />
 </div>
 )}
 </div>
 {/* Decorative element */}
 <div className={cn(
 "absolute -bottom-6 -right-6 w-24 h-24 rounded-full blur-3xl opacity-0 transition-opacity duration-500 group-hover:opacity-20",
 selectedBranchId === branch.id ? "bg-white" : "bg-operational-cyan"
 )} />
 </button>
 ))}
 </div>
 </div>

 {/* Warehouse Selection */}
 <div className="space-y-6">
 <div className="flex items-center gap-3 ps-4">
 <Warehouse className="w-5 h-5 text-operational-cyan/40" />
 <h3 className="text-label-xs font-semibold uppercase text-muted-foreground">{t('select_warehouse')}</h3>
 </div>
 
 <div className="grid gap-4">
 {!selectedBranchId ? (
 <div className="h-[300px] flex flex-col items-center justify-center rounded-[2rem] bg-surface-container-low/30 border border-dashed border-white/5 space-y-4">
 <div className="w-12 h-12 rounded-full bg-white/5 flex items-center justify-center">
 <Settings2 className="w-6 h-6 text-muted-foreground/20" />
 </div>
 <p className="text-label-xs font-semibold uppercase text-muted-foreground/30 text-center px-12">
 {t('branch_hint')}
 </p>
 </div>
 ) : filteredWarehouses.length > 0 ? (
 filteredWarehouses.map((wh) => (
 <button
 key={wh.id}
 onClick={() => setSelectedWarehouseId(wh.id)}
 className={cn(
 "relative p-6 rounded-[2rem] text-start transition-all duration-500 group overflow-hidden border border-white/5",
 selectedWarehouseId === wh.id 
 ? "bg-operational-cyan shadow-[0_20px_40px_rgba(var(--operational-cyan-rgb),0.2)]" 
 : "bg-surface-container-low hover:bg-surface-container-high"
 )}
 >
 <div className="relative z-10 flex items-center justify-between">
 <div className="space-y-1">
 <p className={cn(
 "text-label-xs font-semibold uppercase",
 selectedWarehouseId === wh.id ? "text-primary-foreground/60" : "text-muted-foreground/40"
 )}>
 {wh.code}
 </p>
 <p className={cn(
 "text-title-sm font-bold",
 selectedWarehouseId === wh.id ? "text-primary-foreground" : "text-foreground"
 )}>
 {locale === 'ar' ? wh.name_ar : wh.name_en}
 </p>
 </div>
 {selectedWarehouseId === wh.id && (
 <div className="w-10 h-10 rounded-full bg-white/20 flex items-center justify-center animate-in zoom-in-50 duration-500">
 <CheckCircle2 className="w-6 h-6 text-white" />
 </div>
 )}
 </div>
 </button>
 ))
 ) : (
 <div className="h-[200px] flex flex-col items-center justify-center rounded-[2rem] bg-surface-container-low/30 border border-dashed border-white/5 space-y-4">
 <p className="text-label-xs font-semibold uppercase text-muted-foreground/30">{t('no_warehouses')}</p>
 </div>
 )}
 </div>
 </div>
 </div>

 {/* Action Button */}
 <div className="center-content pt-8">
 <Button
 size="lg"
 disabled={!selectedBranchId || !selectedWarehouseId}
 onClick={handleConfirm}
 className="h-20 px-16 bg-foreground text-background hover:scale-105 transition-all duration-500 rounded-[2.5rem] font-semibold uppercase text-label-sm group shadow-2xl"
 >
 {t('switch_cta')}
 <ChevronRight className="w-5 h-5 ms-4 group-hover:translate-x-2 transition-transform duration-500" />
 </Button>
 </div>
 </div>
 </div>
 );
}

import { setRequestLocale, getTranslations } from 'next-intl/server';
import { ContextSelectorClient } from './ContextSelectorClient';
import ProtectedRoute from '@/components/shared/ProtectedRoute';

export async function generateMetadata({ params }: { params: Promise<{ locale: string }> }) {
 const { locale } = await params;
 const t = await getTranslations({ locale, namespace: 'common' });
 return {
 title: `Context Selector | LogiRest`,
 };
}

export default async function ContextSelectorPage(props: { params: Promise<{ locale: string }> }) {
 const params = await props.params;
 setRequestLocale(params.locale);
 
 return (
 <ProtectedRoute>
 <ContextSelectorClient locale={params.locale} />
 </ProtectedRoute>
 );
}

'use client';

import { useTranslations } from 'next-intl';
import { Package, FileText, ClipboardCheck, AlertTriangle, Activity, Database, Users, ShieldCheck } from 'lucide-react';
import { PageHeader } from '@/components/shared/PageHeader';
import { KPICard } from '@/features/dashboard/components/KPICard';
import { formatCurrency, formatNumber, formatTime } from '@/utils/currency';
import { ClientOnlyTime } from '@/components/shared/ClientOnlyTime';
import { useLocale } from '@/hooks/useLocale';
import { useAuth } from '@/providers/AuthProvider';
import { Badge } from '@/components/ui/badge';
import { AdminDashboard } from '@/features/dashboard/components/AdminDashboard';
import { KitchenDashboard } from '@/features/dashboard/components/KitchenDashboard';
import { StoreManagerDashboard } from '@/features/dashboard/components/StoreManagerDashboard';
import { NearExpiryWidget } from '@/features/dashboard/components/NearExpiryWidget';
import { PendingDocumentsWidget } from '@/features/dashboard/components/PendingDocumentsWidget';

export default function DashboardClient() {
 const t = useTranslations('dashboard');
 const tc = useTranslations('common');
 const { locale } = useLocale();
 const { user } = useAuth();
 const isRtl = locale === 'ar';

 // Mock static data as per Phase 8 planning
 const stats = {
 totalStockValue: 1245300.50,
 baseCurrency: 'SAR',
 pendingPRs: 7,
 activeStocktakes: 2,
 lowStockItems: 14,
 systemHealth: 98.4,
 activeUsers: 24,
 lastBackup: '2h ago',
 };
 
 // Visibility logic based on roles
 const canSeeApprovals = user?.role === 'ADMIN' || user?.role === 'INV_MGR' || user?.role === 'APPROVER';
 const canSeeNearExpiry = true;

 // Role-based Dashboard Switching
 const renderDashboard = () => {
 switch (user?.role) {
 case 'ADMIN':
 case 'GM':
 return <AdminDashboard />;
 case 'KITCHEN_CHIEF':
 return <KitchenDashboard />;
 case 'STORE_MGR':
 case 'INV_MGR':
 return <StoreManagerDashboard />;
 default:
 // Generic fallback dashboard (previous content)
 return (
 <div className="space-y-10">
 {/* KPI Section */}
 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
 <KPICard
 title={t('kpi.total_stock')}
 value={formatCurrency(stats.totalStockValue, stats.baseCurrency, locale as 'ar' | 'en')}
 icon={Package}
 accent="cyan"
 trend={{ value: '12%', isPositive: true }}
 description={t('kpi.vs_last_month')}
 />
 <KPICard
 title={t('kpi.pending_prs')}
 value={formatNumber(stats.pendingPRs, locale as 'ar' | 'en')}
 icon={FileText}
 accent="amber"
 description={t('kpi.immediate_review')}
 />
 <KPICard
 title={t('kpi.active_stocktakes')}
 value={formatNumber(stats.activeStocktakes, locale as 'ar' | 'en')}
 icon={ClipboardCheck}
 accent="amber"
 description={t('kpi.jeddah_riyadh_active')}
 />
 <KPICard
 title={t('kpi.low_stock_items')}
 value={formatNumber(stats.lowStockItems, locale as 'ar' | 'en')}
 icon={AlertTriangle}
 accent="red"
 trend={{ value: '4', isPositive: false }}
 description={t('kpi.critical_items')}
 />
 </div>

 {/* Main Widgets Section */}
 <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
 <div className="space-y-4">
 <div className="flex items-center justify-between px-1">
 <h4 className="text-label-xs font-semibold uppercase text-muted-foreground/40">
 {t('expiry_control')}
 </h4>
 <div className="h-px flex-1 mx-6 bg-surface-container-high/30" />
 </div>
 {canSeeNearExpiry && <NearExpiryWidget locale={locale} />}
 </div>
 
 <div className="space-y-4">
 <div className="flex items-center justify-between px-1">
 <h4 className="text-label-xs font-semibold uppercase text-muted-foreground/40">
 {t('approval_workflow')}
 </h4>
 <div className="h-px flex-1 mx-6 bg-surface-container-high/30" />
 </div>
 {canSeeApprovals && <PendingDocumentsWidget locale={locale} />}
 </div>
 </div>
 </div>
 );
 }
 };

 return (
 <div className="p-8 max-w-[1600px] mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-1000 pb-20">
 <PageHeader 
 title={t('title')} 
 description={`${t('description')} - ${user?.role || 'User'}`}
 className="pb-10"
 actions={
 <div className="flex items-center gap-4 bg-surface-container-low p-4 rounded-xl border border-surface-container-high/20 shadow-sm">
 <div className="flex flex-col gap-1 pe-4 border-e border-surface-container-high/50">
 <span className="text-label-xs font-semibold uppercase text-muted-foreground/60 flex items-center gap-2">
 <Activity className="w-3 h-3 text-operational-cyan" />
 {tc('system_stats.live_updates')}
 </span>
 <div className="flex items-center gap-2">
 <div className="h-1.5 w-32 bg-surface-container-high rounded-full overflow-hidden">
 <div className="h-full bg-operational-cyan w-[98%] shadow-[0_0_8px_rgba(var(--primary-rgb),0.5)]" />
 </div>
 <span className="text-label-xs font-bold text-foreground">{stats.systemHealth}%</span>
 </div>
 </div>
 
 <div className="flex flex-col gap-0.5">
 <div className="flex items-center gap-2">
 <Badge variant="outline" className="bg-status-success/10 text-status-success border-status-success/20 text-label-xxs font-semibold h-5 px-1.5 uppercase">
 <ShieldCheck className="w-2.5 h-2.5 me-1" />
 {t('secure')}
 </Badge>
 <span className="text-label-xxs font-bold text-muted-foreground/40 uppercase">
 {tc('system_stats.last_sync')}: <ClientOnlyTime className="inline" locale={locale as 'ar' | 'en'} />
 </span>
 </div>
 <div className="flex items-center gap-3 mt-1">
 <div className="flex items-center gap-1.5">
 <Database className="w-3 h-3 text-muted-foreground/60" />
 <span className="text-label-xs font-bold text-muted-foreground/60">Backup: {stats.lastBackup}</span>
 </div>
 <div className="flex items-center gap-1.5">
 <Users className="w-3 h-3 text-muted-foreground/60" />
 <span className="text-label-xs font-bold text-muted-foreground/60">{t('users_online', { count: stats.activeUsers })}</span>
 </div>
 </div>
 </div>
 </div>
 }
 />

 {renderDashboard()}

 {/* Intelligence & Analytics Section - Global */}
 <div className="space-y-4 pt-6">
 <div className="flex items-center justify-between px-1">
 <h4 className="text-label-xs font-semibold uppercase text-muted-foreground/60">
 {t('business_intelligence')}
 </h4>
 <div className="h-px flex-1 mx-6 bg-surface-container-high/10" />
 </div>
 <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 opacity-30 grayscale pointer-events-none filter blur-[0.5px] transition-all hover:opacity-100 hover:grayscale-0 hover:blur-0">
 <div className="lg:col-span-2 h-56 rounded-2xl bg-surface-container-low border border-dashed border-surface-container-high flex flex-col items-center justify-center gap-4">
 <Activity className="w-8 h-8 text-muted-foreground/40" />
 <span className="text-muted-foreground/60 italic text-label-xs font-semibold uppercase">{t('movement_analytics_placeholder')}</span>
 </div>
 <div className="h-56 rounded-2xl bg-surface-container-low border border-dashed border-surface-container-high flex flex-col items-center justify-center gap-4">
 <Activity className="w-8 h-8 text-muted-foreground/40" />
 <span className="text-muted-foreground/60 italic text-label-xs font-semibold uppercase">{t('audit_logs_placeholder')}</span>
 </div>
 </div>
 </div>
 </div>
 );
}

'use client';

import { useState, useMemo } from 'react';
import { useTranslations, useLocale } from 'next-intl';
import type { ColumnDef } from '@tanstack/react-table';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { useInventoryBalance } from '@/features/inventory/hooks/useInventoryBalance';
import { useMasterDataList } from '@/features/master-data/hooks/useMasterDataCRUD';
import { WarehouseSchema } from '@/types/master-data';
import { generateExcel } from '@/utils/export';
import type { StockBalanceItem } from '@/types/inventory';
import { cn } from '@/lib/utils';
import { formatNumber, formatCurrency } from '@/utils/currency';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { 
 Package, 
 AlertTriangle, 
 Clock, 
 Wallet, 
 Search, 
 Plus, 
 Download, 
 Scan, 
 Printer, 
 Scale, 
 Edit2, 
 Trash2,
 ChevronLeft,
 ChevronRight
} from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Link, useRouter } from '@/i18n/navigation';
import { MetricCard } from '@/components/ui/metric-card';
import { EmptyState } from '@/components/shared/EmptyState';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { ReportHeader } from '@/components/shared/ReportHeader';

interface StockBalanceClientProps {
 title: string;
}

export default function StockBalanceClient({ title }: StockBalanceClientProps) {
 const t = useTranslations('operational.inventory');
 const tc = useTranslations('common');
 const currentLocale = useLocale();
 const router = useRouter();
 const isRtl = currentLocale === 'ar';

 const [warehouseFilter, setWarehouseFilter] = useState('');
 const [searchFilter, setSearchFilter] = useState('');
 const [page, setPage] = useState(1);

 const { data: warehouses } = useMasterDataList('warehouses', WarehouseSchema);
 const { data, isLoading } = useInventoryBalance({
 warehouse_id: warehouseFilter && warehouseFilter !== 'all' ? warehouseFilter : undefined,
 search: searchFilter || undefined,
 page,
 });

 const columns = useMemo<ColumnDef<StockBalanceItem, unknown>[]>(() => [
 {
 accessorKey: 'item_code',
 header: tc('table_headers.code'),
 cell: ({ row }) => (
 <span dir="ltr" className="font-mono text-label-xs font-semibold text-muted-foreground/60 uppercase">
 {row.original.item_code}#
 </span>
 ),
 },
 {
 id: 'item_name',
 header: tc('table_headers.name'),
 cell: ({ row }) => (
 <div className="flex items-center gap-3">
 <div className="w-8 h-8 rounded-lg bg-surface-container-highest/50 flex items-center justify-center border border-surface-variant/10 group-hover:bg-operational-cyan/10 transition-colors">
 <Package className="w-4 h-4 text-muted-foreground/60/40 group-hover:text-operational-cyan transition-colors" />
 </div>
 <span className="font-semibold text-label-sm text-foreground group-hover:text-operational-cyan transition-colors">
 {isRtl ? row.original.item_name_ar : row.original.item_name_en}
 </span>
 </div>
 ),
 },
 {
 id: 'warehouse',
 header: tc('warehouse'),
 cell: ({ row }) => (
 <span className="text-label-xs font-bold text-foreground/80">
 {isRtl ? row.original.warehouse_name_ar : row.original.warehouse_name_en}
 </span>
 ),
 },
 {
 accessorKey: 'qty_available',
 header: tc('table_headers.available'),
 cell: ({ row }) => (
 <span dir="ltr" className="font-mono text-label-sm font-semibold text-foreground">
 {formatNumber(row.original.qty_available, currentLocale as 'ar' | 'en', 2)}
 </span>
 ),
 },
 {
 id: 'unit',
 header: tc('table_headers.uom'),
 cell: ({ row }) => (
 <span className="text-label-xs font-semibold text-muted-foreground/60 uppercase">
 {tc('uoms.kg')}
 </span>
 ),
 },
 {
 id: 'status',
 header: tc('status_label'),
 cell: ({ row }) => {
 const qty = row.original.qty_available;
 const reorderPoint = row.original.reorder_point;
 const isLow = qty < reorderPoint;
 const isCritical = qty <= 5; // Placeholder logic
 
 if (isCritical) {
 return <StatusBadge status="CRITICAL" className="h-6" />;
 }
 if (isLow) {
 return <StatusBadge status="LOW" className="h-6" />;
 }
 return <StatusBadge status="HEALTHY" className="h-6" />;
 }
 },
 {
 id: 'actions',
 header: '',
 cell: () => (
 <div className="flex items-center justify-end gap-2">
 <PermissionGate action="update" resource="inventory">
 <Button variant="ghost" size="icon" className="w-8 h-8 rounded-lg hover:bg-operational-cyan/10 hover:text-operational-cyan text-muted-foreground/60/40 transition-all">
 <Edit2 className="w-3.5 h-3.5" />
 </Button>
 </PermissionGate>
 <PermissionGate action="delete" resource="inventory">
 <Button variant="ghost" size="icon" className="w-8 h-8 rounded-lg hover:bg-status-error/10 hover:text-status-error text-muted-foreground/60/40 transition-all">
 <Trash2 className="w-3.5 h-3.5" />
 </Button>
 </PermissionGate>
 </div>
 ),
 },
 ], [t, tc, isRtl, currentLocale]);

 const handleExport = () => {
 if (!data?.data) return;
 const exportColumns = [
 { header: tc('table_headers.code'), key: 'item_code', width: 15 },
 { header: tc('table_headers.name'), key: 'item_name', width: 30 },
 { header: tc('warehouse'), key: 'warehouse_name', width: 25 },
 { header: tc('table_headers.qty'), key: 'qty_on_hand', width: 12 },
 { header: tc('table_headers.available'), key: 'qty_available', width: 12 },
 ];

 const rows = data.data.map(item => ({
 ...item,
 item_name: isRtl ? item.item_name_ar : item.item_name_en,
 warehouse_name: isRtl ? item.warehouse_name_ar : item.warehouse_name_en,
 }));

 generateExcel(exportColumns, rows, 'Stock_Balances');
 };

 const totalItems = data?.meta?.total ?? 1284; 
 const lowStockItems = 12; 
 const nearExpiry = 8; 
 const totalValue = 452300; 

 return (
 <div className="min-h-screen bg-surface-container-lowest text-foreground selection:bg-operational-cyan/30 selection:text-operational-cyan">
 <div className="p-8 max-w-[1600px] mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-1000">
 
 <ReportHeader />

 {/* Header Section */}
 <div className="flex flex-col md:flex-row items-center justify-between gap-6">
 <div className="flex flex-col gap-1 w-full md:w-auto text-start">
 <h1 className="text-headline-lg font-semibold text-foreground">
 {t('title')}
 </h1>
 <p className="text-label-xs font-semibold text-muted-foreground/60/40 uppercase">
 {t('subtitle')}
 </p>
 </div>

 <div className="flex items-center gap-4 w-full md:w-auto">
 <div className="relative group flex-1 md:w-80">
 <Search className="absolute start-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/60/40 group-focus-within:text-operational-cyan transition-colors z-10" />
 <Input 
 type="text"
 placeholder={t('search_placeholder')}
 value={searchFilter}
 onChange={(e) => setSearchFilter(e.target.value)}
 className="w-full h-12 ps-12 pe-4 bg-surface-container-low/50 border-none rounded-2xl text-label-xs font-bold transition-all"
 />
 </div>
 <PermissionGate action="create" resource="inventory">
 <Link href="/master-data/items/new">
 <Button className="h-12 px-6 bg-primary hover:bg-primary/90 text-white rounded-2xl gap-3 shadow-lg shadow-primary/20">
 <Plus className="w-4 h-4" />
 <span className="text-label-xs font-semibold uppercase">{t('add_item')}</span>
 </Button>
 </Link>
 </PermissionGate>
 <Button 
 variant="outline" 
 onClick={handleExport}
 className="h-12 px-6 bg-surface-container-low border-surface-variant/10 hover:bg-surface-container-medium rounded-2xl gap-3 transition-all"
 >
 <Download className="w-4 h-4 text-operational-cyan" />
 <span className="text-label-xs font-semibold uppercase">{t('export')}</span>
 </Button>
 </div>
 </div>

 {/* KPI Cards */}
 <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
 <MetricCard
 label={t('total_value')}
 value={formatCurrency(totalValue, 'SAR', currentLocale as 'ar' | 'en')}
 icon={Wallet}
 color="emerald"
 trend={tc('currencies.sar_full')}
 />
 <MetricCard
 label={t('near_expiry')}
 value={nearExpiry}
 icon={Clock}
 color="amber"
 />
