'use client';

import { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { Scan, Camera, X, CheckCircle2, AlertCircle, RefreshCw } from 'lucide-react';
import { Button } from '@/components/ui/button';

export default function ScannerClient() {
 const t = useTranslations('operational.inventory');
 const [isScanning, setIsScanning] = useState(true);
 const [result, setResult] = useState<string | null>(null);
 const [status, setStatus] = useState<'idle' | 'scanning' | 'success' | 'error'>('scanning');

 useEffect(() => {
 if (status === 'scanning') {
 const timer = setTimeout(() => {
 // Mock scan logic
 setResult('LOT-2024-9942');
 setStatus('success');
 }, 3000);
 return () => clearTimeout(timer);
 }
 }, [status]);

 const resetScanner = () => {
 setResult(null);
 setStatus('scanning');
 };

 return (
 <div className="min-h-screen bg-surface-container-lowest text-foreground flex flex-col items-center justify-center p-6 selection:bg-operational-cyan/30">
 <div className="w-full max-w-md space-y-8 animate-in fade-in zoom-in duration-700">
 
 {/* Top Header */}
 <div className="text-center space-y-2">
 <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-operational-cyan/10 border border-operational-cyan/20 mb-2">
 <Scan className="w-4 h-4 text-operational-cyan" />
 <span className="text-label-xs font-semibold uppercase text-operational-cyan">{t('scanner.active')}</span>
 </div>
 <h1 className="text-headline-lg font-semibold" dir="auto" style={{ unicodeBidi: 'isolate' }}>{t('barcode_scanner')}</h1>
 <p className="text-label-xs font-semibold text-muted-foreground/60/40 uppercase" dir="auto" style={{ unicodeBidi: 'isolate' }}>{t('scanner.description')}</p>
 </div>

 {/* Scanner Viewport */}
 <div className="relative aspect-square w-full bg-surface-ledger rounded-[3rem] border border-surface-variant/10 shadow-2xl overflow-hidden flex flex-col items-center justify-center group">
 
 {/* Decorative Grid Overlay */}
 <div className="absolute inset-0 bg-[linear-gradient(rgba(var(--primary-rgb),0.05)_1px,transparent_1px),linear-gradient(90deg,rgba(var(--primary-rgb),0.05)_1px,transparent_1px)] bg-[size:20px_20px]" />
 
 {status === 'scanning' && (
 <>
 {/* Scanning Animation */}
 <div className="absolute inset-x-8 top-1/2 -translate-y-1/2 h-[2px] bg-operational-cyan shadow-[0_0_15px_rgba(var(--primary-rgb),0.8)] animate-[scan_2s_ease-in-out_infinite]" />
 
 {/* Viewfinder Corners */}
 <div className="absolute top-12 start-12 w-12 h-12 border-t-4 border-s-4 border-operational-cyan rounded-ss-2xl opacity-40" />
 <div className="absolute top-12 end-12 w-12 h-12 border-t-4 border-e-4 border-operational-cyan rounded-se-2xl opacity-40" />
 <div className="absolute bottom-12 start-12 w-12 h-12 border-b-4 border-s-4 border-operational-cyan rounded-bs-2xl opacity-40" />
 <div className="absolute bottom-12 end-12 w-12 h-12 border-b-4 border-e-4 border-operational-cyan rounded-be-2xl opacity-40" />

 <div className="relative z-10 flex flex-col items-center gap-4 text-operational-cyan/40">
 <Camera className="w-16 h-16 animate-pulse" />
 <p className="text-label-xs font-semibold uppercase">{t('scanner.align_tip')}</p>
 </div>
 </>
 )}

 {status === 'success' && (
 <div className="relative z-10 flex flex-col items-center gap-6 animate-in zoom-in duration-500">
 <div className="w-24 h-24 rounded-full bg-status-success/10 flex items-center justify-center border border-status-success/20">
 <CheckCircle2 className="w-12 h-12 text-status-success" />
 </div>
 <div className="text-center space-y-1">
 <p className="text-label-xs font-semibold text-muted-foreground/60/40 uppercase" dir="auto" style={{ unicodeBidi: 'isolate' }}>{t('scanner.identified_record')}</p>
 <p className="text-headline-lg font-semibold text-status-success uppercase" dir="auto" style={{ unicodeBidi: 'isolate' }}><span dir="ltr" className="font-mono">{result}</span></p>
 </div>
 <div className="flex flex-col gap-3 w-64">
 <Button 
 onClick={() => window.location.href = `/${t('lots.route') || 'inventory/lots'}`}
 className="w-full h-12 bg-status-success hover:bg-status-success/90 text-white rounded-2xl font-semibold uppercase text-label-xs"
 >
 {t('scanner.load_operational_data')}
 </Button>
 <Button 
 variant="ghost" 
 onClick={resetScanner}
 className="w-full h-10 text-muted-foreground/60/40 hover:text-foreground font-semibold uppercase text-label-xs gap-2"
 >
 <RefreshCw className="w-3 h-3" />
 {t('scanner.rescan_matrix')}
 </Button>
 </div>
 </div>
 )}
 </div>

 {/* System Logs / Helper */}
 <div className="bg-surface-container-low/30 p-6 rounded-[2rem] border border-surface-variant/10 space-y-4">
 <div className="flex items-center gap-3">
 <div className="w-1.5 h-6 bg-operational-cyan rounded-full" />
 <h3 className="text-label-sm font-semibold uppercase">{t('scanner.protocol_version')}</h3>
 </div>
 <div className="grid grid-cols-2 gap-4">
 <div className="p-3 bg-surface-container-low/50 rounded-xl border border-surface-variant/10">
 <p className="text-label-xxs font-semibold text-muted-foreground/60/40 uppercase mb-1">{t('scanner.battery_level')}</p>
 <p className="text-body-md font-semibold">94%</p>
 </div>
 <div className="p-3 bg-surface-container-low/50 rounded-xl border border-surface-variant/10">
 <p className="text-label-xxs font-semibold text-muted-foreground/60/40 uppercase mb-1">{t('scanner.ai_confidence')}</p>
 <p className="text-body-md font-semibold text-operational-cyan">99.8%</p>
 </div>
 </div>
 </div>

 {/* Exit Button */}
 <div className="flex justify-center">
 <Button 
 variant="ghost" 
 onClick={() => window.history.back()}
 className="rounded-full w-14 h-14 bg-surface-container-low border border-surface-variant/10 hover:bg-status-error/10 hover:text-status-error transition-all shadow-xl"
 >
 <X className="w-6 h-6" />
 </Button>
 </div>

 </div>

 <style jsx global>{`
 @keyframes scan {
 0%, 100% { top: 30%; }
 50% { top: 70%; }
 }
 `}</style>
 </div>
 );
}

'use client';

import { useEffect } from 'react';
import { useRouter } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';
import { useForm, Controller, useWatch } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
 Select,
 SelectContent,
 SelectItem,
 SelectTrigger,
 SelectValue,
} from '@/components/ui/select';
import { Switch } from '@/components/ui/switch';
import { ScanInput } from '@/components/shared/ScanInput/ScanInput';
import { MasterDataFormLayout } from '@/features/master-data/components/MasterDataFormLayout';
import { useBarcode, useCreateBarcode, useUpdateBarcode } from '@/features/barcodes/hooks/useBarcodes';
import { useItems } from '@/features/items/hooks/useItems';
import { useUoMs } from '@/features/uoms/hooks/useUoMs';
import { BarcodeFormSchema, type BarcodeFormValues } from '@/types/master-data';
import { Card, CardContent } from '@/components/ui/card';
import { Cpu, Link as LinkIcon, Hash, Barcode as BarcodeIcon, Settings2 } from 'lucide-react';
import { useConflictHandler } from '@/core/concurrency/useConflictHandler';
import { ConflictDialog } from '@/core/concurrency/ConflictDialog';

interface Props { 
  id: string | null; 
  createTitle: string; 
  editTitle: string; 
  viewTitle: string;
  locale: string; 
  isReadOnly?: boolean;
}

export function BarcodeFormClient({ id, createTitle, editTitle, viewTitle, locale, isReadOnly = false }: Props) {
  const tc = useTranslations('common');
  const tb = useTranslations('master_data.barcodes');
  
  const { data: barcode } = useBarcode(id);
  const { data: items } = useItems();
  const { data: uoms } = useUoMs();
  
  const create = useCreateBarcode();
  const conflict = useConflictHandler('barcode', id ?? '');
  const update = useUpdateBarcode({ onConflict: conflict.triggerConflict });

  const { register, handleSubmit, reset, setValue, control, formState: { errors, isDirty, isValid } } =
    useForm<BarcodeFormValues>({
      resolver: zodResolver(BarcodeFormSchema),
      defaultValues: { 
        item_id: '', 
        uom_id: '', 
        code: '', 
        default_qty: 1,
        is_active: true,
        version: undefined
      },
      disabled: isReadOnly,
    });
    
  const { router: guardedRouter } = useUnsavedChangesGuard(isDirty);

  const currentCode = useWatch({ control, name: 'code' });

 useEffect(() => {
 if (barcode) {
 reset({ 
 item_id: barcode.item_id, 
 uom_id: barcode.uom_id,
 code: barcode.code, 
 default_qty: barcode.default_qty,
 is_active: barcode.is_active,
 version: barcode.version
 });
 }
 }, [barcode, reset]);

  const onSubmit = handleSubmit(async (values) => {
    if (isReadOnly) return;
    
    try {
      if (id) {
        await update.mutateAsync({ id, values });
      } else {
        await create.mutateAsync(values);
      }
      reset(values);
      guardedRouter.push('/master-data/barcodes', { skipGuard: true });
    } catch {
      // Error handled by mutation hooks or conflict handler
    }
  });

  return (
    <>
    <MasterDataFormLayout
      title={isReadOnly ? viewTitle : (id ? editTitle : createTitle)} 
      backHref='/master-data/barcodes'
      isSaving={create.isPending || update.isPending} 
      onSubmit={onSubmit}
      onCancel={() => guardedRouter.push('/master-data/barcodes')}
      hideSave={isReadOnly}
      isDirty={isDirty}
      isValid={isValid}
    >
 <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
 <div className="lg:col-span-2 space-y-8">
 <Card className="bg-surface-container-low border-none rounded-md overflow-hidden">
 <CardContent className="p-8 space-y-8">
 <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
 <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
 <LinkIcon className="w-5 h-5 text-tertiary" />
 </div>
 <div>
 <h3 className="text-body-md font-semibold text-foreground uppercase">{tb('title')}</h3>
 <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{tb('description')}</p>
 </div>
 </div>

 <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
 <div className="space-y-2">
 <Label htmlFor="bc-item" className="text-label-xs font-semibold uppercase text-muted-foreground/70">
 {tb('fields.item')}
 </Label>
 <Controller
 name="item_id"
 control={control}
 render={({ field }) => (
  <Select disabled={isReadOnly} value={field.value} onValueChange={field.onChange}>
 <SelectTrigger id="bc-item" className="h-11 border-none bg-surface-container-high/40 hover:bg-surface-container-high transition-colors uppercase text-label-xs font-bold">
 <SelectValue placeholder="—" />
 </SelectTrigger>
 <SelectContent className="bg-surface-container-highest border-none">
 {items?.data?.map((i) => (
 <SelectItem key={i.id} value={i.id} className="font-semibold text-label-xs uppercase">
 {i.code} — {locale === 'ar' ? i.name_ar : i.name_en}
 </SelectItem>
 ))}
 </SelectContent>
 </Select>
 )}
 />
 {errors.item_id && <p className="text-label-xs font-semibold text-rose-400 uppercase">{errors.item_id.message}</p>}
 </div>

 <div className="space-y-2">
 <Label htmlFor="bc-uom" className="text-label-xs font-semibold uppercase text-muted-foreground/70">
 {tb('fields.uom')}
 </Label>
 <Controller
 name="uom_id"
 control={control}
 render={({ field }) => (
  <Select disabled={isReadOnly} value={field.value} onValueChange={field.onChange}>
 <SelectTrigger id="bc-uom" className="h-11 border-none bg-surface-container-high/40 hover:bg-surface-container-high transition-colors uppercase text-label-xs font-bold">
 <SelectValue placeholder="—" />
 </SelectTrigger>
 <SelectContent className="bg-surface-container-highest border-none">
 {uoms?.data?.map((u) => (
 <SelectItem key={u.id} value={u.id} className="font-semibold text-label-xs uppercase">
 {u.code} — {locale === 'ar' ? u.name_ar : u.name_en}
 </SelectItem>
 ))}
 </SelectContent>
 </Select>
 )}
 />
 {errors.uom_id && <p className="text-label-xs font-semibold text-rose-400 uppercase">{errors.uom_id.message}</p>}
 </div>

 <div className="space-y-2">
 <Label htmlFor="bc-qty" className="text-label-xs font-semibold uppercase text-muted-foreground/70">
 {tb('fields.default_qty')}
 </Label>
 <div className="relative group">
 <Hash className="absolute start-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40 group-focus-within:text-status-active transition-colors" />
                <Input 
                  id="bc-qty" 
                  type="number" 
                  dir="ltr" 
                  min={1}
                  disabled={isReadOnly}
                  {...register('default_qty', { valueAsNumber: true })} 
                  className="h-11 ps-10 border-none bg-surface-container-high/40 focus:bg-surface-container-high transition-colors font-mono font-bold text-label-sm text-status-active"
                />
 </div>
 {errors.default_qty && <p className="text-label-xs font-semibold text-rose-400 uppercase">{errors.default_qty.message}</p>}
 </div>
 </div>
 </CardContent>
 </Card>

 <Card className="bg-surface-container-low border-none rounded-md overflow-hidden">
 <CardContent className="p-8 space-y-8">
 <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
 <div className="w-10 h-10 rounded-md bg-status-secondary/10 flex items-center justify-center">
 <BarcodeIcon className="w-5 h-5 text-status-secondary" />
 </div>
 <div>
 <h3 className="text-body-md font-semibold text-foreground uppercase">{tb('fields.code')}</h3>
 <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{tb('physical_mapping')}</p>
 </div>
 </div>

 <div className="space-y-6">
 <div className="space-y-2">
 <Label htmlFor="bc-val" className="text-label-xs font-semibold uppercase text-muted-foreground/70">
 {tb('fields.code')}
 </Label>
                <ScanInput
                  onScan={(val) => setValue('code', val, { shouldValidate: true })}
                  placeholder={isReadOnly ? "" : tb('scan_or_type')}
                  disabled={isReadOnly}
                  className="h-11 font-mono font-bold text-label-sm text-status-secondary"
                />
 <input type="hidden" {...register('code')} />
 {errors.code && <p className="text-label-xs font-semibold text-rose-400 uppercase">{errors.code.message}</p>}
 </div>

 {currentCode && (
