  id: string | null;
  createTitle: string;
  editTitle: string;
  viewTitle?: string;
  isReadOnly?: boolean;
  locale: string;
}

export function CurrencyFormClient({ 
  id, 
  createTitle, 
  editTitle, 
  viewTitle = '',
  isReadOnly = false,
  locale 
}: Props) {
  const t = useTranslations('master_data.currencies');
  const abortController = useAbortController();
  const { data: currency, isLoading, isError, isFetched, refetch } = useCurrency(id);
  const create = useCreateCurrency();
  const conflict = useConflictHandler('currency', id ?? '');
  const update = useUpdateCurrency({ onConflict: conflict.triggerConflict });

  const { register, handleSubmit, reset, control, formState: { errors, isDirty, isValid } } =
    useForm<CurrencyFormValues>({
      resolver: zodResolver(CurrencyFormSchema),
      disabled: isReadOnly,
      defaultValues: { 
        code: '', 
        name_ar: '', 
        name_en: '', 
        symbol: '',
        is_base_currency: false,
        is_active: true,
        version: undefined
      },
    });

  const { router: guardedRouter } = useUnsavedChangesGuard(isDirty);

  useWatch({ control, name: 'code' });

  useEffect(() => {
    if (currency) {
      reset({ 
        code: currency.code, 
        name_ar: currency.name_ar,
        name_en: currency.name_en, 
        symbol: currency.symbol || '',
        is_base_currency: currency.is_base_currency,
        is_active: currency.is_active,
        version: currency.version
      });
    }
  }, [currency, reset]);

  // 1. Loading State
  if (id && isLoading) {
    return <PageSkeleton variant="detail" />;
  }

  // 2. Error State (Server/Network Error)
  if (id && isError) {
    return (
      <ErrorState 
        type="server_error"
        onRetry={() => refetch()}
      />
    );
  }

  // 3. Not Found State (Smart 404)
  if (id && isFetched && !currency) {
    return (
      <ErrorState 
        type="not_found"
        onBack={() => guardedRouter.push('/master-data/currencies', { skipGuard: true })}
      />
    );
  }

  const onSubmit = handleSubmit(async (values) => {
    if (isReadOnly) return;
    
    try {
      if (id) {
        await update.mutateAsync({ id, values, signal: abortController.signal });
      } else {
        await create.mutateAsync({ ...values, signal: abortController.signal });
      }
      reset(values);
      guardedRouter.push('/master-data/currencies', { skipGuard: true });
    } catch {
      // Error handled by mutation hooks or conflict handler
    }
  });

  const displayTitle = isReadOnly ? viewTitle : (id ? editTitle : createTitle);

  return (
    <>
    <MasterDataFormLayout 
      title={displayTitle} 
      backHref='/master-data/currencies'
      isSaving={create.isPending || update.isPending} 
      onSubmit={onSubmit}
      onCancel={() => guardedRouter.push('/master-data/currencies')}
      hideSave={isReadOnly}
      isDirty={isDirty}
      isValid={isValid}
    >
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          {/* Identity Card */}
          <Card className="bg-surface-container-low border-none rounded-md overflow-hidden transition-all duration-500 hover:shadow-2xl hover:shadow-cyan-900/10">
            <CardContent className="p-8 space-y-8">
              <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                <div className="w-10 h-10 rounded-md bg-cyan-500/10 flex items-center justify-center">
                  <Landmark className="w-5 h-5 text-cyan-500" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold text-foreground uppercase">{t('title')}</h3>
                  <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{t('description')}</p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Code Field */}
                <div className="space-y-2">
                  <Label htmlFor="curr-code" className="text-label-xs font-semibold uppercase text-muted-foreground/70">
                    {t('fields.code')}
                  </Label>
                  <div className="relative group">
                    <Coins className="absolute start-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40 group-focus-within:text-cyan-500 transition-colors" />
                    <Input 
                      id="curr-code" 
                      placeholder={t('placeholders.code')}
                      dir="ltr" 
                      maxLength={3}
                      {...register('code')} 
                      disabled={isReadOnly}
                      className="h-11 ps-10 border-none bg-surface-container-high/40 focus:bg-surface-container-high transition-colors font-mono font-bold text-label-sm uppercase text-cyan-500 disabled:opacity-70"
                    />
                  </div>
                  {errors.code?.message && (
                    <p className="text-label-xs font-semibold text-rose-400 uppercase">
                      {t(errors.code.message as Parameters<typeof t>[0])}
                    </p>
                  )}
                </div>

                {/* Symbol Field */}
                <div className="space-y-2">
                  <Label htmlFor="curr-symbol" className="text-label-xs font-semibold uppercase text-muted-foreground/70">
                    {t('fields.symbol')}
                  </Label>
                  <div className="relative group">
                    <Type className="absolute start-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40 group-focus-within:text-amber-500 transition-colors" />
                    <Input 
                      id="curr-symbol" 
                      placeholder={t('placeholders.symbol')}
                      {...register('symbol')} 
                      disabled={isReadOnly}
                      className="h-11 ps-10 border-none bg-surface-container-high/40 focus:bg-surface-container-high transition-colors font-mono font-bold text-label-sm text-amber-500 disabled:opacity-70"
                    />
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Name EN */}
                <div className="space-y-2">
                  <Label htmlFor="curr-name-en" className="text-label-xs font-semibold uppercase text-muted-foreground/70">
                    {t('fields.name_en')}
                  </Label>
                  <Input 
                    id="curr-name-en" 
                    {...register('name_en')} 
                    disabled={isReadOnly}
                    className="h-11 border-none bg-surface-container-high/40 focus:bg-surface-container-high transition-colors text-label-sm font-bold disabled:opacity-70"
                  />
                  {errors.name_en?.message && (
                    <p className="text-label-xs font-semibold text-rose-400 uppercase">
                      {t(errors.name_en.message as Parameters<typeof t>[0])}
                    </p>
                  )}
                </div>

                {/* Name AR */}
                <div className="space-y-2">
                  <Label htmlFor="curr-name-ar" className="text-label-xs font-semibold uppercase text-muted-foreground/70">
                    {t('fields.name_ar')}
                  </Label>
                  <Input 
                    id="curr-name-ar" 
                    dir="rtl"
                    {...register('name_ar')} 
                    disabled={isReadOnly}
                    className="h-11 border-none bg-surface-container-high/40 focus:bg-surface-container-high transition-colors text-label-sm font-bold disabled:opacity-70"
                  />
                  {errors.name_ar?.message && (
                    <p className="text-label-xs font-semibold text-rose-400 uppercase">
                      {t(errors.name_ar.message as Parameters<typeof t>[0])}
                    </p>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Sidebar Configuration */}
        <div className="space-y-8">
          <Card className="bg-surface-container-low border-none rounded-md overflow-hidden">
            <CardContent className="p-8 space-y-6">
              <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                <div className="w-10 h-10 rounded-md bg-status-active/10 flex items-center justify-center">
                  <Activity className="w-5 h-5 text-status-active" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold text-foreground uppercase">{t('config_title')}</h3>
                  <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{t('config_subtitle')}</p>
                </div>
              </div>
              
              {/* Base Currency Switch */}
              <div className="flex items-center justify-between p-4 bg-amber-500/5 rounded-md border border-amber-500/10">
                <div className="space-y-0.5">
                  <Label className="text-label-xs font-bold uppercase text-foreground/80">{t('fields.is_base')}</Label>
                  <p className="text-label-xxs text-muted-foreground uppercase font-medium">{t('placeholders.base_desc')}</p>
                </div>
                <Controller
                  name="is_base_currency"
                  control={control}
                  render={({ field }) => (
                    <Switch
                      checked={field.value}
                      onCheckedChange={field.onChange}
                      disabled={isReadOnly}
                      className="data-[state=checked]:bg-amber-500"
                    />
                  )}
                />
              </div>

              {/* Status Switch */}
              <div className="flex items-center justify-between p-4 bg-surface-container-highest/10 rounded-md border border-surface-variant/5">
                <div className="space-y-0.5">
                  <Label className="text-label-xs font-bold uppercase text-foreground/80">{t('fields.is_active')}</Label>
                  <p className="text-label-xxs text-muted-foreground uppercase font-medium">{t('placeholders.active_desc')}</p>
                </div>
                <Controller
                  name="is_active"
                  control={control}
                  render={({ field }) => (
                    <Switch
                      checked={field.value}
                      onCheckedChange={field.onChange}
                      disabled={isReadOnly}
                      className="data-[state=checked]:bg-status-active"
                    />
                  )}
                />
              </div>
            </CardContent>
          </Card>

          {/* Guidelines */}
          <Card className="bg-surface-container-low border-none rounded-md overflow-hidden">
            <CardContent className="p-8 space-y-6">
              <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                  <ShieldCheck className="w-5 h-5 text-tertiary" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold text-foreground uppercase">{t('standards_title')}</h3>
                  <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{t('standards_subtitle')}</p>
                </div>
              </div>
              
              <ul className="space-y-4">
                <li className="text-label-xs text-muted-foreground/80 leading-relaxed font-medium flex gap-3">
                  <span className="text-cyan-500/60 font-semibold">/</span>
                  <span>{t('tips.base_currency_desc')}</span>
                </li>
                <li className="text-label-xs text-muted-foreground/80 leading-relaxed font-medium flex gap-3">
                  <span className="text-cyan-500/60 font-semibold">/</span>
                  <span>{t('tips.iso_standard_desc')}</span>
                </li>
              </ul>
            </CardContent>
          </Card>
        </div>
      </div>
    </MasterDataFormLayout>
      <ConflictDialog open={conflict.open} onReload={conflict.handleReload} onClose={conflict.handleClose} />
    </>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { useTranslations } from 'next-intl';
import { Link, useRouter } from '@/i18n/navigation';
import { Plus, CheckCircle2, Search, Coins, Landmark, ShieldCheck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { ColumnDef } from '@tanstack/react-table';
import { useCurrencies } from '@/features/currencies/hooks/useCurrencies';
import { type Currency } from '@/types/master-data';
import { PageHeader } from '@/components/shared/PageHeader';
import { Input } from '@/components/ui/input';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { MetricCard } from '@/components/ui/metric-card';
import { Badge } from '@/components/ui/badge';
import { EmptyState } from '@/components/shared/EmptyState';
import { ErrorState } from '@/components/shared/ErrorState';

export function CurrencyListClient({ locale }: { locale: string }) {
 const tc = useTranslations('common');
 const t = useTranslations('master_data.currencies');
 const router = useRouter();
 const [search, setSearch] = useState('');

 const { data: currencies = [], isLoading, isError, refetch } = useCurrencies();

 const filteredCurrencies = useMemo(() => {
 if (!search) return currencies;
 const s = search.toLowerCase();
 return currencies.filter((c: Currency) => 
 c.code.toLowerCase().includes(s) || 
 c.name_en.toLowerCase().includes(s) || 
 c.name_ar.includes(s)
 );
 }, [currencies, search]);

 const stats = useMemo(() => {
 const base = currencies.find((c: Currency) => c.is_base_currency);
 return {
 total: currencies.length,
 active: currencies.filter((c: Currency) => c.is_active).length,
 baseCurrency: base ? (locale === 'ar' ? base.name_ar : base.name_en) : '---'
 };
 }, [currencies, locale]);

 const columns = useMemo<ColumnDef<Currency, unknown>[]>(() => [
 { 
 accessorKey: 'code', 
 header: t('fields.code'), 
 cell: ({ row }) => (
 <div className="flex items-center gap-2">
 <Coins className="w-3.5 h-3.5 text-cyan-500/50" />
 <span dir="ltr" className="font-mono text-cyan-500/90 font-bold uppercase bg-cyan-500/5 px-2 py-0.5 rounded-sm">
 {row.original.code}
 </span>
 </div>
 )
 },
 { 
 accessorKey: 'name', 
 header: tc('name'), 
 cell: ({ row }) => (
 <div className="flex flex-col gap-0.5">
 <span className="font-bold text-label-sm">{row.original.name_en}</span>
 <span className="text-label-xs opacity-40" dir="rtl">{row.original.name_ar}</span>
 </div>
 )
 },
 { 
 accessorKey: 'symbol', 
 header: t('fields.symbol'), 
 cell: ({ row }) => (
 <span className="font-mono text-label-sm font-bold text-muted-foreground/60">
 {row.original.symbol || '---'}
 </span>
 )
 },
 {
 accessorKey: 'is_base_currency',
 header: t('fields.is_base'),
 cell: ({ row }) => row.original.is_base_currency ? (
 <Badge className="bg-amber-500/10 text-amber-500 border-none rounded-sm text-label-xxs font-semibold uppercase px-2 h-5">
 {t('fields.is_base')}
 </Badge>
 ) : null
 },
 {
 accessorKey: 'is_active', 
 header: t('fields.is_active'),
 cell: ({ row }) => (
 <StatusBadge 
 status={row.original.is_active ? 'ACTIVE' : 'INACTIVE'} className="rounded-sm h-5"
 />
 )
 },
 {
 id: 'actions',
 header: '',
 cell: ({ row }) => (
 <div className="flex justify-end gap-2">

 <PermissionGate action="view" resource="master_data">
 <Button 
 variant="ghost" 
 size="sm" 
 className="text-label-xs font-semibold uppercase text-cyan-500 hover:text-cyan-400 hover:bg-cyan-500/10 h-7"
 onClick={(e) => {
 e.stopPropagation();
 router.push(`/master-data/currencies/${row.original.id}`);
 }}
 >
 {tc('view')}
 </Button>
 </PermissionGate>
 
        <PermissionGate action="edit" resource="master_data">
          <Button
            variant="ghost"
            size="sm"
            className="text-label-xs font-semibold uppercase text-emerald-500 hover:text-emerald-400 hover:bg-emerald-500/10 h-7"
            onClick={(e) => {
              e.stopPropagation();
              router.push(`/master-data/currencies/${row.original.id}/edit`);
            }}
          >
            {t('edit')}
          </Button>
        </PermissionGate>
      </div>
 ),
 },
 ], [tc, t, locale, router]);

 if (isError) {
  return (
   <div className="p-8">
    <ErrorState 
     type="server_error"
     onRetry={() => refetch()}
    />
   </div>
  );
 }

 return (
 <div className="p-8 max-w-[1600px] mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-1000">
 <div className="space-y-4">
 <Breadcrumb 
        items={[
          { label: tc('home'), href: `/dashboard` },
          { label: tc('master_data'), href: `/master-data` },
          { label: t('title') }
        ]} 
 />
 <PageHeader 
 title={t('title')} 
 description={t('description')}
 actions={
 <PermissionGate action="create" resource="master_data">
        <Link href={`/master-data/currencies/new`}>
          <Button className="h-11 px-8 bg-primary hover:bg-primary/90 text-primary-foreground text-label-xs font-semibold uppercase rounded-sm transition-all shadow-lg shadow-primary/20">
 <Plus className="w-3.5 h-3.5 me-2" />
 {tc('create')}
 </Button>
 </Link>
 </PermissionGate>
 }
 />
 </div>

 <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
 <MetricCard
 label={tc('total_records')}
 value={stats.total}
 icon={Coins}
 color="cyan"
 dir="ltr"
 />

 <MetricCard
 label={t('fields.is_base')}
 value={stats.baseCurrency}
 icon={Landmark}
 color="amber"
 dir={locale === 'ar' ? 'rtl' : 'ltr'} />

 <MetricCard
 label={tc('status.active')}
 value={stats.active}
 icon={CheckCircle2}
 color="emerald"
 dir="ltr"
 />
 </div>

 <DataTable 
 columns={columns} 
 data={filteredCurrencies} 
 isLoading={isLoading}
 collectionName="master_data_currencies"
  onRowClick={(r: Currency) => router.push(`/master-data/currencies/${r.id}`)}
  emptyState={
    <EmptyState 
      title={t('empty.title')}
      description={t('empty.description')}
      action={
        <PermissionGate action="create" resource="master_data">
          <Link href={`/master-data/currencies/new`}>
            <Button className="h-10 px-6 bg-primary hover:bg-primary/90 text-primary-foreground text-label-xs font-semibold uppercase rounded-sm transition-all shadow-lg">
              <Plus className="w-3.5 h-3.5 me-2" />
              {tc('create')}
            </Button>
          </Link>
        </PermissionGate>
      }
    />
  }
 filters={
 <div className="flex flex-wrap items-end gap-6 w-full py-6 px-8 bg-surface-container-medium/30 rounded-sm">
 <div className="flex flex-col gap-2 min-w-[300px] flex-1">
 <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ps-1">{tc('search')}</label>
 <div className="relative">
 <Input
 placeholder={tc('search')}
 value={search}
 onChange={(e) => { setSearch(e.target.value); }}
 className="w-full bg-surface-container-highest/30 border-none h-12 px-12 text-label-sm font-bold rounded-sm shadow-inner shadow-black/20 focus-visible:ring-1 focus-visible:ring-cyan-500/30"
 />
 <Search className="absolute start-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40" />
 </div>
 </div>
 </div>
 }
 />

 {/* Quick Tips */}
 <div className="grid grid-cols-1 md:grid-cols-2 gap-6 opacity-60 hover:opacity-100 transition-opacity duration-500 pb-10 pt-4 border-t border-surface-variant/5">
 <div className="p-6 bg-surface-container-low/50 rounded-sm border border-white/5 flex items-start gap-4">
 <div className="w-10 h-10 rounded-sm bg-amber-500/10 flex items-center justify-center flex-shrink-0">
 <Landmark className="w-5 h-5 text-amber-500" />
 </div>
 <div className="space-y-1">
 <h4 className="text-label-xs font-semibold uppercase text-amber-500">{t('tips.base_currency_title')}</h4>
 <p className="text-label-xs text-muted-foreground font-semibold leading-relaxed uppercase">
 {t('tips.base_currency_desc')}
 </p>
 </div>
 </div>
 <div className="p-6 bg-surface-container-low/50 rounded-sm border border-white/5 flex items-start gap-4">
 <div className="w-10 h-10 rounded-sm bg-cyan-500/10 flex items-center justify-center flex-shrink-0">
 <ShieldCheck className="w-5 h-5 text-cyan-500" />
 </div>
 <div className="space-y-1">
 <h4 className="text-label-xs font-semibold uppercase text-cyan-500">{t('tips.iso_standard_title')}</h4>
 <p className="text-label-xs text-muted-foreground font-semibold leading-relaxed uppercase">
 {t('tips.iso_standard_desc')}
 </p>
 </div>
 </div>
 </div>
 </div>
 );
}

'use client';

import { useEffect } from 'react';
import { useRouter } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';
import { useForm, useWatch, Controller } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Briefcase, ShieldCheck, Landmark, Activity, Warehouse } from 'lucide-react';
import { useConflictHandler } from '@/core/concurrency/useConflictHandler';
import { ConflictDialog } from '@/core/concurrency/ConflictDialog';
import { useAbortController } from '@/hooks/useAbortController';
import { useState } from 'react';
import { PostConfirmDialog } from '@/components/shared/PostConfirmDialog';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { Button } from '@/components/ui/button';
import { Trash2 } from 'lucide-react';

import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import {
 Select,
 SelectContent,
 SelectItem,
 SelectTrigger,
 SelectValue,
} from '@/components/ui/select';
import { Card, CardContent } from '@/components/ui/card';
import { MasterDataFormLayout } from '@/features/master-data/components/MasterDataFormLayout';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';
import {
 useDepartment,
 useCreateDepartment,
 useUpdateDepartment,
 useDeleteDepartment,
} from '@/features/departments/hooks/useDepartments';
import { useBranches } from '@/features/branches/hooks/useBranches';
import { useWarehouses } from '@/features/warehouses/hooks/useWarehouses';
import { DepartmentFormSchema, type DepartmentFormValues } from '@/types/master-data';

interface Props {
  id: string | null;
  createTitle: string;
  editTitle: string;
  viewTitle?: string;
  locale: string;
  isReadOnly?: boolean;
}

export function DepartmentFormClient({ id, createTitle, editTitle, viewTitle, locale, isReadOnly = false }: Props) {
  const t = useTranslations('common');
  const td = useTranslations('master_data.departments');
  const abortController = useAbortController();
  
  const { register, handleSubmit, reset, setValue, control, formState: { errors, isDirty, isValid } } = useForm<DepartmentFormValues>({
    resolver: zodResolver(DepartmentFormSchema),
    defaultValues: {
      branch_id: '',
      warehouse_id: '',
      code: '',
      name_ar: '',
      name_en: '',
      is_active: true,
      manager: '',
      cost_center: '',
      version: undefined
    },
    disabled: isReadOnly,
  });
 
  const create = useCreateDepartment();
  const conflict = useConflictHandler('department', id ?? '');
  const update = useUpdateDepartment({ onConflict: conflict.triggerConflict });
  const deleteDept = useDeleteDepartment();

  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  const { router: guardedRouter } = useUnsavedChangesGuard(isDirty);

 const isActive = useWatch({ control, name: 'is_active' });
 const selectedBranchId = useWatch({ control, name: 'branch_id' });

 // Filter warehouses based on selected branch
 const filteredWarehouses = warehouses.filter(w => !selectedBranchId || w.branch_id === selectedBranchId);

  const onSubmit = handleSubmit(async (values) => {
    if (isReadOnly) return;
    
    try {
      if (id) {
        await update.mutateAsync({ id, values, signal: abortController.signal });
      } else {
        await create.mutateAsync({ ...values, signal: abortController.signal });
      }
      reset(values);
      guardedRouter.push('/master-data/departments', { skipGuard: true });
    } catch {
      // Error handled by mutation hooks or conflict handler
    }
  });

  const handleDelete = async () => {
    if (!id) return;
    try {
      await deleteDept.mutateAsync({ id, signal: abortController.signal });
      guardedRouter.push('/master-data/departments', { skipGuard: true });
    } catch {
      setShowDeleteConfirm(false);
    }
  };

  const isSaving = create.isPending || update.isPending || deleteDept.isPending;

  if ((id && isLoading && !data) || branchesLoading || warehousesLoading) {
    return <PageSkeleton variant="detail" />;
  }

  if (isError || branchesError || warehousesError) {
    return (
      <ErrorState 
        error={500} 
        onRetry={() => {
          refetch();
          refetchBranches();
          refetchWarehouses();
        }}
      />
    );
  }

  if (id && !data && !isLoading) {
    return <ErrorState error={404} />;
  }

  // Determine the display title
  const displayTitle = id 
    ? (isReadOnly ? (viewTitle || td('view_title')) : editTitle)
    : createTitle;

 return (
    <>
    <MasterDataFormLayout
      title={displayTitle}
      backHref='/master-data/departments'
      isSaving={isSaving} saveDisabled={conflict.saveDisabled}
      onSubmit={onSubmit}
      onCancel={() => guardedRouter.push('/master-data/departments')}
      hideSave={isReadOnly}
      isDirty={isDirty}
      isValid={isValid}
      headerActions={
        id && !isReadOnly && (
          <PermissionGate action="delete" resource="master_data_departments">
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="text-status-error hover:text-status-error hover:bg-status-error/10 rounded-full w-10 h-10 transition-all duration-200"
              onClick={() => setShowDeleteConfirm(true)}
              disabled={isSaving}
            >
              <Trash2 className="w-5 h-5" />
            </Button>
          </PermissionGate>
        )
      }
    >
 <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
 {/* Main Content */}
 <div className="lg:col-span-2 space-y-8">
 {/* Section: Basic Info */}
 <Card className="bg-surface-container-low border-none overflow-hidden">
 <CardContent className="p-8 space-y-8">
 <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
 <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
 <Briefcase className="w-5 h-5 text-tertiary" />
 </div>
