        variant="destructive"
      />
    </>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { useRouter, Link } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { EmptyState } from '@/components/shared/EmptyState';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';
import { Plus, Briefcase, CheckCircle2, Search, Layers, ShieldCheck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { useDepartments } from '@/features/departments/hooks/useDepartments';
import { type Department } from '@/types/master-data';
import { MetricCard } from '@/components/ui/metric-card';
import { ColumnDef } from '@tanstack/react-table';
import { PageHeader } from '@/components/shared/PageHeader';
import { Input } from '@/components/ui/input';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { StatusBadge } from '@/components/shared/StatusBadge';

export function DepartmentListClient({ locale }: { locale: string }) {
  const tc = useTranslations('common');
  const t = useTranslations('master_data.departments');
  const router = useRouter();
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState('');

  const { data: queryData, isLoading, isError, refetch } = useDepartments({ search });
  const departments = queryData?.data || [];

  const stats = useMemo(() => {
    return {
      total: departments.length,
      active: departments.filter(d => d.is_active).length,
    };
  }, [departments]);

  const columns = useMemo<ColumnDef<Department, unknown>[]>(() => [
    {
      accessorKey: 'code',
      header: t('fields.code'),
      cell: ({ row }) => (
        <span dir="ltr" className="font-mono text-label-xs font-semibold text-cyan-500 uppercase px-2 py-0.5 bg-cyan-500/5 rounded-sm">
          {row.original.code}
        </span>
      ),
    },
    {
      accessorKey: 'name',
      header: tc('name'),
      cell: ({ row }) => (
        <div className="flex flex-col gap-0.5">
          <span className="font-bold text-label-sm">{row.original.name_en}</span>
          <span className="text-label-xs text-muted-foreground/60" dir="rtl">{row.original.name_ar}</span>
        </div>
      ),
    },
    {
      accessorKey: 'is_active',
      header: t('fields.is_active'),
      cell: ({ row }) => (
        <StatusBadge 
          status={row.original.is_active ? 'ACTIVE' : 'INACTIVE'} className="rounded-sm h-5"
        />
      ),
    },
    {
      id: 'actions',
      header: '',
      cell: ({ row }) => (
        <div className="flex justify-end gap-2">
          <PermissionGate action="view" resource="master_data">
            <Button 
              variant="ghost" 
              size="sm" 
              className="text-label-xs font-semibold uppercase text-cyan-500 hover:text-cyan-400 hover:bg-cyan-500/10 h-7"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/departments/${row.original.id}`);
              }}
            >
              {tc('view')}
            </Button>
          </PermissionGate>
          <PermissionGate action="edit" resource="master_data">
            <Button 
              variant="ghost" 
              size="sm" 
              className="text-label-xs font-semibold uppercase text-amber-500 hover:text-amber-400 hover:bg-amber-500/10 h-7"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/departments/${row.original.id}/edit`);
              }}
            >
              {tc('edit')}
            </Button>
          </PermissionGate>
        </div>
      ),
    },
  ], [tc, t, locale, router]);

  if (isLoading && !queryData) return <PageSkeleton variant="list" />;
  if (isError) return <ErrorState error={500} onRetry={() => refetch()} />;

  return (
    <div className="p-8 max-w-[1600px] mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <div className="space-y-4">
        <Breadcrumb items={[
          { label: tc('home'), href: `/dashboard` },
          { label: tc('master_data'), href: `/master-data` },
          { label: t('title') }
        ]} />
        <PageHeader 
          title={t('title')} 
          description={t('description')}
          actions={
            <PermissionGate action="create" resource="master_data">
              <Link href={`/master-data/departments/new`}>
                <Button className="h-11 px-8 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-semibold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                  <Plus className="w-3.5 h-3.5 me-2" />
                  {tc('create')}
                </Button>
              </Link>
            </PermissionGate>
          }
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard
          label={tc('total_locations')}
          value={stats.total}
          icon={Briefcase}
          color="cyan"
          dir="ltr"
        />

        <MetricCard
          label={tc('status.active')}
          value={stats.active}
          icon={Layers}
          color="amber"
          dir="ltr"
        />

        <MetricCard
          label={t('description')}
          value={tc('verified')}
          icon={ShieldCheck}
          color="emerald"
          dir="ltr"
        />
      </div>

      <DataTable 
        columns={columns} 
        data={departments} 
        isLoading={isLoading}
        collectionName="master_data_departments"
        onRowClick={(r: Department) => router.push(`/master-data/departments/${r.id}`)}
        emptyState={
          <EmptyState 
            title={t('empty.title')}
            description={t('empty.description')}
            action={
              <PermissionGate action="create" resource="master_data">
                <Link href={`/master-data/departments/new`}>
                  <Button className="h-10 px-6 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-semibold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                    <Plus className="w-3.5 h-3.5 me-2" />
                    {tc('create')}
                  </Button>
                </Link>
              </PermissionGate>
            }
          />
        }
        filters={
          <div className="flex flex-wrap items-end gap-6 w-full py-6 px-8 bg-surface-container-medium/30 rounded-sm">
            <div className="flex flex-col gap-2 min-w-[300px] flex-1">
              <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ps-1">{tc('search')}</label>
              <div className="relative">
                <Input
                  placeholder={tc('search')}
                  value={search}
                  onChange={(e) => { setSearch(e.target.value); setPage(1); }}
                  className="w-full bg-surface-container-highest/30 border-none h-12 px-12 text-label-sm font-bold rounded-sm shadow-inner shadow-black/20"
                />
                <Search className="absolute start-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40" />
              </div>
            </div>
          </div>
        }
      />
    </div>
  );
}

'use client';

import { useEffect } from 'react';
import { useRouter } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';
import { useForm, Controller } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { MasterDataFormLayout } from '@/features/master-data/components/MasterDataFormLayout';
import { useFXRate, useCreateFXRate, useUpdateFXRate } from '@/features/fx-rates/hooks/useFXRates';
import { useCurrencies } from '@/features/currencies/hooks/useCurrencies';
import { FXRateFormSchema, type FXRateFormValues, type Currency } from '@/types/master-data';
import { Card, CardContent } from '@/components/ui/card';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@/components/ui/select';
import { ArrowRightLeft, Calendar, TrendingUp, History, Info, ShieldCheck, Activity } from 'lucide-react';
import { cn } from '@/lib/utils';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';
import { useConflictHandler } from '@/core/concurrency/useConflictHandler';
import { ConflictDialog } from '@/core/concurrency/ConflictDialog';
import { useAbortController } from '@/hooks/useAbortController';

interface Props { 
  id: string | null; 
  createTitle: string; 
  editTitle: string; 
  viewTitle?: string;
  isReadOnly?: boolean;
  locale: string;
}

export function FXRateFormClient({ 
  id, 
  createTitle, 
  editTitle, 
  viewTitle = '',
  isReadOnly: isReadOnlyProp = false,
  locale 
}: Props) {
  const tc = useTranslations('common');
  const t = useTranslations('master_data.fx_rates');
  const abortController = useAbortController();
  
  const { data: fxRate, isLoading: loadingRate, isError: rateError, refetch: refetchRate } = useFXRate(id);
  const { data: currencies, isLoading: loadingCurrencies, isError: currenciesError, refetch: refetchCurrencies } = useCurrencies();
  
  const create = useCreateFXRate();
  const conflict = useConflictHandler('fx-rate', id ?? '');
  const update = useUpdateFXRate({ onConflict: conflict.triggerConflict });

  const { register, handleSubmit, reset, control, formState: { errors, isDirty, isValid } } =
    useForm<FXRateFormValues>({
      resolver: zodResolver(FXRateFormSchema),
      disabled: isReadOnlyProp,
      defaultValues: { 
        from_currency_id: '',
        to_currency_id: '',
        rate: 1,
        effective_date: new Date().toISOString().split('T')[0],
        is_active: true,
        version: undefined
      },
    });
    
  const { router: guardedRouter } = useUnsavedChangesGuard(isDirty);

  useEffect(() => {
    if (fxRate) {
      reset({ 
        from_currency_id: fxRate.from_currency_id,
        to_currency_id: fxRate.to_currency_id,
        rate: fxRate.rate,
        effective_date: fxRate.effective_date.split('T')[0],
        is_active: fxRate.is_active,
        version: fxRate.version
      });
    }
  }, [fxRate, reset]);
  
  if ((id && loadingRate && !fxRate) || loadingCurrencies) {
    return <PageSkeleton variant="detail" />;
  }

  if (rateError || currenciesError) {
    return (
      <ErrorState 
        error={500} 
        onRetry={() => {
          refetchRate();
          refetchCurrencies();
        }}
      />
    );
  }

  if (id && !fxRate && !loadingRate) {
    return (
      <ErrorState 
        error={404} 
        onBack={() => guardedRouter.push('/master-data/fx-rates', { skipGuard: true })}
      />
    );
  }

  const onSubmit = handleSubmit(async (values) => {
    if (isReadOnlyProp) return;
    
    try {
      if (id) {
        await update.mutateAsync({ id, values, signal: abortController.signal });
      } else {
        await create.mutateAsync({ values, signal: abortController.signal });
      }
      reset(values);
      guardedRouter.push('/master-data/fx-rates', { skipGuard: true });
    } catch {
      // Error handled by mutation hooks or conflict handler
    }
  });

  const isReadOnly = isReadOnlyProp || id === 'FX-001'; // Simulated guard for posted documents
  const displayTitle = isReadOnlyProp ? viewTitle : (id ? editTitle : createTitle);

  return (
    <>
    <MasterDataFormLayout 
      title={displayTitle} 
      backHref='/master-data/fx-rates'
      isSaving={create.isPending || update.isPending} 
      onSubmit={onSubmit}
      onCancel={() => guardedRouter.push('/master-data/fx-rates')}
      hideSave={isReadOnlyProp}
      isDirty={isDirty}
      isValid={isValid}
    >
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          {/* Main Financial Card */}
          <Card className="bg-surface-container-low border-none rounded-md overflow-hidden transition-all duration-500 hover:shadow-2xl hover:shadow-cyan-900/10">
            <CardContent className="p-8 space-y-8">
              <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                <div className="w-10 h-10 rounded-md bg-cyan-500/10 flex items-center justify-center">
                  <ArrowRightLeft className="w-5 h-5 text-cyan-500" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold text-foreground uppercase">{t('title')}</h3>
                  <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{t('description')}</p>
                </div>
              </div>

              {isReadOnly && !isReadOnlyProp && (
                <div className="flex items-center gap-3 p-4 bg-amber-500/5 rounded-sm border border-amber-500/10 mb-4">
                  <Info className="w-4 h-4 text-amber-500" />
                  <p className="text-label-xs font-bold text-amber-500 uppercase leading-relaxed">
                    {t('financial_integrity_note')}
                  </p>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* From Currency */}
                <div className="space-y-2">
                  <Label className="text-label-xs font-semibold uppercase text-muted-foreground/70">
                    {t('fields.from_currency_id')}
                  </Label>
                  <Controller
                    name="from_currency_id"
                    control={control}
                    render={({ field }) => (
                      <Select 
                        value={field.value} 
                        onValueChange={field.onChange}
                        disabled={isReadOnly}
                      >
                        <SelectTrigger className="disabled:opacity-70">
                          <SelectValue placeholder={t('fields.from_currency_id')} />
                        </SelectTrigger>
                        <SelectContent>
                          {(currencies || []).filter((c: Currency) => c.is_active).map((c: Currency) => (
                            <SelectItem key={c.id} value={c.id}>
                              <span dir="ltr" className="font-mono font-bold text-cyan-500">{c.code}</span>
                              <span className="text-label-xs opacity-60">
                                {locale === 'ar' ? c.name_ar : c.name_en}
                              </span>
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    )}
                  />
                  {errors.from_currency_id && <p className="text-label-xs font-semibold text-rose-400 uppercase">{t(errors.from_currency_id.message as Parameters<typeof t>[0])}</p>}
                </div>

                {/* To Currency */}
                <div className="space-y-2">
                  <Label className="text-label-xs font-semibold uppercase text-muted-foreground/70">
                    {t('fields.to_currency_id')}
                  </Label>
                  <Controller
                    name="to_currency_id"
                    control={control}
                    render={({ field }) => (
                      <Select 
                        value={field.value} 
                        onValueChange={field.onChange}
                        disabled={isReadOnly}
                      >
                        <SelectTrigger className="disabled:opacity-70">
                          <SelectValue placeholder={t('fields.to_currency_id')} />
                        </SelectTrigger>
                        <SelectContent>
                          {(currencies || []).filter((c: Currency) => c.is_active).map((c: Currency) => (
                            <SelectItem key={c.id} value={c.id}>
                              <span dir="ltr" className="font-mono font-bold text-amber-500">{c.code}</span>
                              <span className="text-label-xs opacity-60">
                                {locale === 'ar' ? c.name_ar : c.name_en}
                              </span>
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    )}
                  />
                  {errors.to_currency_id && <p className="text-label-xs font-semibold text-rose-400 uppercase">{t(errors.to_currency_id.message as Parameters<typeof t>[0])}</p>}
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Rate Field */}
                <div className="space-y-2">
                  <Label htmlFor="fx-rate" className="text-label-xs font-semibold uppercase text-muted-foreground/70">
                    {t('fields.rate')}
                  </Label>
                  <div className="relative group">
                    <TrendingUp className="absolute start-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40 group-focus-within:text-cyan-500 transition-colors" />
                    <Input 
                      id="fx-rate" 
                      type="number"
                      step="0.000001"
                      placeholder={t('placeholders.rate')}
                      dir="ltr" 
                      disabled={isReadOnly}
                      {...register('rate', { valueAsNumber: true })} 
                      className="h-11 ps-10 border-none bg-surface-container-high/40 focus:bg-surface-container-high transition-colors font-mono font-bold text-label-sm disabled:opacity-70"
                    />
                  </div>
                  {errors.rate && <p className="text-label-xs font-semibold text-rose-400 uppercase">{t(errors.rate.message as Parameters<typeof t>[0])}</p>}
                </div>

                {/* Effective Date Field */}
                <div className="space-y-2">
                  <Label htmlFor="fx-date" className="text-label-xs font-semibold uppercase text-muted-foreground/70">
                    {t('fields.effective_date')}
                  </Label>
                  <div className="relative group">
                    <Calendar className="absolute start-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40 group-focus-within:text-cyan-500 transition-colors" />
                    <Input 
                      id="fx-date" 
                      type="date"
                      dir="ltr" 
                      disabled={isReadOnly}
                      {...register('effective_date')} 
                      className="h-11 ps-10 border-none bg-surface-container-high/40 focus:bg-surface-container-high transition-colors font-mono font-bold text-label-sm disabled:opacity-70"
                    />
                  </div>
                  {errors.effective_date && <p className="text-label-xs font-semibold text-rose-400 uppercase">{t(errors.effective_date.message as Parameters<typeof t>[0])}</p>}
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Sidebar Configuration */}
        <div className="space-y-8">
          <Card className="bg-surface-container-low border-none rounded-md overflow-hidden">
            <CardContent className="p-8 space-y-6">
              <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                <div className="w-10 h-10 rounded-md bg-status-active/10 flex items-center justify-center">
                  <Activity className="w-5 h-5 text-status-active" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold text-foreground uppercase">{t('config_title')}</h3>
                  <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{t('config_subtitle')}</p>
                </div>
              </div>
              
              {/* Status Switch */}
              <div className="flex items-center justify-between p-4 bg-surface-container-highest/10 rounded-md border border-surface-variant/5">
                <div className="space-y-0.5">
                  <Label className="text-label-xs font-bold uppercase text-foreground/80">{t('fields.is_active')}</Label>
                  <p className="text-label-xxs text-muted-foreground uppercase font-medium">{t('active_desc')}</p>
                </div>
                <Controller
                  name="is_active"
                  control={control}
                  render={({ field }) => (
                    <Switch
                      checked={field.value}
                      onCheckedChange={field.onChange}
                      disabled={isReadOnly}
                      className="data-[state=checked]:bg-status-active"
                    />
                  )}
                />
              </div>
            </CardContent>
          </Card>

          {/* Guidelines */}
          <Card className="bg-surface-container-low border-none rounded-md overflow-hidden">
            <CardContent className="p-8 space-y-6">
              <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                  <ShieldCheck className="w-5 h-5 text-tertiary" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold text-foreground uppercase">{t('rules_title')}</h3>
                  <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{t('rules_subtitle')}</p>
                </div>
              </div>
              
              <ul className="space-y-4">
                <li className="text-label-xs text-muted-foreground/80 leading-relaxed font-medium flex gap-3">
                  <span className="text-cyan-500/60 font-semibold">/</span>
                  <span>{t('tips.precision_desc')}</span>
                </li>
                <li className="text-label-xs text-muted-foreground/80 leading-relaxed font-medium flex gap-3">
                  <span className="text-cyan-500/60 font-semibold">/</span>
                  <span>{t('tips.temporal_integrity_desc')}</span>
                </li>
              </ul>
            </CardContent>
          </Card>
        </div>
      </div>
    </MasterDataFormLayout>
      <ConflictDialog open={conflict.open} onReload={conflict.handleReload} onClose={conflict.handleClose} />
    </>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { useRouter, Link } from '@/i18n/navigation';
import { useParams } from 'next/navigation';
import { useTranslations } from 'next-intl';
import { Plus, CheckCircle2, Search, ArrowRightLeft, Calendar, TrendingUp, ShieldCheck, History } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { ColumnDef } from '@tanstack/react-table';
import { useFXRates } from '@/features/fx-rates/hooks/useFXRates';
import { useCurrencies } from '@/features/currencies/hooks/useCurrencies';
import { type FXRate, type Currency } from '@/types/master-data';
import { formatRate, formatQuantity } from '@/utils/currency';
import { PageHeader } from '@/components/shared/PageHeader';
import { Input } from '@/components/ui/input';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { MetricCard } from '@/components/ui/metric-card';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { EmptyState } from '@/components/shared/EmptyState';
import { format } from 'date-fns';
import { HydrationSafe } from '@/components/ui/HydrationSafe';

export function FXRateListClient({ locale }: { locale: string }) {
  const t = useTranslations('common');
  const tfx = useTranslations('master_data.fx_rates');
  const router = useRouter();
  const [search, setSearch] = useState('');

  const { data, isLoading } = useFXRates();
  const { data: currencies } = useCurrencies();

  const rates = data || [];

  const stats = useMemo(() => {
    return {
      total: rates.length,
      active: rates.filter(r => r.is_active).length,
      lastUpdate: rates.length > 0 
        ? format(new Date(Math.max(...rates.map(r => new Date(r.effective_date).getTime()))), 'dd/MM/yyyy')
        : '—'
    };
  }, [rates]);

  const getCurrencyCode = (id: string) => (currencies || []).find((c: any) => c.id === id)?.code || id;

  const columns = useMemo<ColumnDef<FXRate, unknown>[]>(() => [
    {
      accessorKey: 'from_currency',
      header: tfx('fields.from_currency'),
      cell: ({ row }) => (
        <div className="flex items-center gap-3">
          <span className="font-bold text-operational-cyan font-mono uppercase px-2 py-0.5 bg-operational-cyan/10 rounded-lg border border-operational-cyan/5">{getCurrencyCode(row.original.from_currency_id)}</span>
          <ArrowRightLeft className="w-3.5 h-3.5 text-muted-foreground/40" />
          <span className="font-bold text-label-sm uppercase px-2 py-0.5 bg-surface-container rounded-lg border border-surface-variant/10">{getCurrencyCode(row.original.to_currency_id)}</span>
        </div>
      )
    },
    {
      accessorKey: 'rate',
      header: tfx('fields.rate'),
      cell: ({ row }) => (
        <div className="flex flex-col">
          <span className="font-mono text-label-sm font-bold text-status-active tabular-nums">
            {formatRate(row.original.rate, locale as 'ar' | 'en', 4)}
          </span>
          <span className="text-label-xxs text-muted-foreground/60 font-medium">
            1 {getCurrencyCode(row.original.from_currency_id)} = {formatRate(row.original.rate, locale as 'ar' | 'en', 4)} {getCurrencyCode(row.original.to_currency_id)}
          </span>
        </div>
      )
    },
    {
      accessorKey: 'effective_date',
      header: tfx('fields.effective_date'),
      cell: ({ row }) => (
        <div className="flex items-center gap-2 text-label-xs font-bold text-muted-foreground bg-surface-container/50 px-2.5 py-1 rounded-lg w-fit">
          <Calendar className="w-3.5 h-3.5 opacity-40 text-operational-cyan" />
          <HydrationSafe>
            {format(new Date(row.original.effective_date), 'dd/MM/yyyy')}
          </HydrationSafe>
        </div>
      )
    },
    {
      accessorKey: 'is_active',
      header: t('status'),
      cell: ({ row }) => (
        <StatusBadge status={row.original.is_active ? 'ACTIVE' : 'INACTIVE'} className="rounded-lg px-2.5" />
      )
    },
    {
      id: 'actions',
      header: '',
      cell: ({ row }) => (
        <div className="flex justify-end">
          <PermissionGate action="edit" resource="master_data">
          <Button
            variant="ghost"
            size="sm"
            className="text-label-xs font-bold uppercase text-operational-cyan hover:bg-operational-cyan/10 h-9 px-4 rounded-xl transition-all"
            onClick={(e) => {
              e.stopPropagation();
              router.push(`/master-data/fx-rates/${row.original.id}/edit`);
            }}
          >
            {t('edit')}
          </Button>
        </PermissionGate>
      </div>
      )
    }
  ], [t, tfx, router, currencies, locale]);

  const breadcrumbs = [
    { label: t('home'), href: `/dashboard` },
    { label: t('master_data'), href: `/master-data` },
    { label: tfx('title'), href: `/master-data/fx-rates` }
  ];

  return (
    <div className="p-8 max-w-[1600px] mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <div className="space-y-4">
        <Breadcrumb items={breadcrumbs} />
        <PageHeader 
          title={tfx('title')} 
          description={tfx('description')}
          actions={
            <PermissionGate action="create" resource="master_data">
              <Link href={`/master-data/fx-rates/new`}>
                <Button className="h-11 px-8 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-bold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                  <Plus className="w-3.5 h-3.5 me-2" />
                  {t('create_new')}
                </Button>
              </Link>
            </PermissionGate>
          }
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard
          label={tfx('metrics.total_rates')}
          value={stats.total}
          icon={ArrowRightLeft}
          color="cyan"
          dir="ltr"
        />

        <MetricCard
          label={t('active')}
          value={stats.active}
          icon={ShieldCheck}
          color="emerald"
          dir="ltr"
        />

        <MetricCard
          label={tfx('metrics.last_update')}
          value={<HydrationSafe>{stats.lastUpdate}</HydrationSafe>}
          icon={History}
          color="amber"
          dir="ltr"
        />
      </div>

      <DataTable 
        columns={columns} 
        data={rates} 
        isLoading={isLoading}
        collectionName="master_data_fx_rates"
        emptyState={
          <EmptyState 
            title={tfx('empty.title')}
            description={tfx('empty.description')}
            action={
              <PermissionGate action="create" resource="master_data">
                <Link href={`/master-data/fx-rates/new`}>
                  <Button className="h-11 px-8 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-bold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                    <Plus className="w-3.5 h-3.5 me-2" />
                    {t('create_new')}
                  </Button>
                </Link>
              </PermissionGate>
            }
          />
        }
        filters={
          <div className="flex flex-wrap items-end gap-6 w-full py-4 px-6 bg-surface-container-low/50 border border-surface-variant/10 rounded-sm">
            <div className="flex flex-col gap-2 min-w-[300px] flex-1">
              <label className="text-label-xs font-semibold uppercase text-muted-foreground/60">{t('search')}</label>
              <div className="relative">
                <Input
                  placeholder={tfx('search_placeholder')}
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="w-full bg-surface-container-highest/30 border-none h-11 ps-10 text-label-sm font-bold"
                />
                <Search className="absolute start-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40" />
              </div>
            </div>
          </div>
        }
      />
    </div>
  );
}

'use client';

import { useTranslations } from 'next-intl';
import { Upload, Download } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { cn } from '@/lib/utils';
import * as XLSX from 'xlsx';

import { ImportWizardState } from '../types';

interface Step1UploadProps {
 wizard: ImportWizardState;
 locale: string;
}

export function Step1Upload({ wizard, locale }: Step1UploadProps) {
 const t = useTranslations('master_data.import');
 const tc = useTranslations('common');
 
 const handleFile = (file: File) => {
  if (file && (file.name.endsWith('.xlsx') || file.name.endsWith('.xls'))) {
  const reader = new FileReader();
  reader.onload = (e) => {
  const data = new Uint8Array(e.target?.result as ArrayBuffer);
  const workbook = XLSX.read(data, { type: 'array' });
  const sheetName = workbook.SheetNames[0];
  const worksheet = workbook.Sheets[sheetName];
  const json = XLSX.utils.sheet_to_json(worksheet);
  
  wizard.setFileData(file.name, file.size, json as Record<string, unknown>[]);
  };
  reader.readAsArrayBuffer(file);
  }
 };


 const downloadTemplate = () => {
 let headers: string[] = [];
 let fileName = '';

 if (wizard.importType === 'items') {
 headers = ['sku', 'name_en', 'name_ar', 'category', 'base_unit', 'min_stock', 'reorder_point'];
 fileName = 'items_template.xlsx';
 } else if (wizard.importType === 'uoms') {
 headers = ['code', 'name_en', 'name_ar'];
 fileName = 'uoms_template.xlsx';
 } else if (wizard.importType === 'barcodes') {
 headers = ['barcode', 'item_sku', 'uom_code', 'default_qty'];
 fileName = 'barcodes_template.xlsx';
 }

 const ws = XLSX.utils.aoa_to_sheet([headers]);
 const wb = XLSX.utils.book_new();
 XLSX.utils.book_append_sheet(wb, ws, 'Template');
 XLSX.writeFile(wb, fileName);
 };

 return (
 <div className="max-w-2xl mx-auto flex flex-col gap-8 py-12">
 <Card className="group relative border-dashed border-2 border-muted-foreground/20 bg-muted/5 p-12 flex flex-col items-center gap-6 hover:border-cyan-500/50 hover:bg-cyan-500/5 transition-all duration-500 cursor-pointer overflow-hidden rounded-[2.5rem]">
 <div className="absolute inset-0 bg-gradient-to-br from-cyan-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
 
 <div className="w-20 h-20 rounded-full bg-cyan-500/10 flex items-center justify-center group-hover:scale-110 transition-transform duration-500">
 <Upload className="w-10 h-10 text-cyan-500" />
 </div>

 <div className="text-center relative z-10">
 <h3 className="text-title-sm font-semibold mb-2">{t('drop_file')}</h3>
 <p className="text-label-xs text-muted-foreground font-semibold uppercase opacity-60">
 {t('max_size')}
 </p>
 </div>

 <input 
 type="file" 
 className="absolute inset-0 opacity-0 cursor-pointer" 
 accept=".xlsx,.xls"
 onChange={(e) => {
 const file = e.target.files?.[0];
 if (file) handleFile(file);
 }}
 />
 </Card>

 <div className="flex flex-col gap-4">
 <div className="flex items-center gap-4">
 <div className="h-px flex-1 bg-muted-foreground/10" />
 <span className="text-label-xs font-semibold uppercase text-muted-foreground/30">{tc('or')}</span>
 <div className="h-px flex-1 bg-muted-foreground/10" />
 </div>

 <Button 
 variant="outline" 
 className="h-16 rounded-2xl border-muted-foreground/10 hover:border-cyan-500/40 hover:bg-cyan-500/5 transition-all group overflow-hidden relative"
 onClick={downloadTemplate}
 >
 <div className="absolute inset-0 bg-gradient-to-r from-cyan-500/0 via-cyan-500/5 to-cyan-500/0 -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />
 <Download className="w-4 h-4 mr-2 text-cyan-500 group-hover:-translate-y-1 transition-transform" />
 <span className="font-bold">{t('download_template')}</span>
 </Button>
 </div>
 </div>
 );
}

'use client';

import { useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { Database, Loader2, CheckCircle2, AlertCircle, ArrowLeft, ArrowRight } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { cn } from '@/lib/utils';

import { validateImportData } from '@/lib/import/validation';
import { ImportWizardState, ValidationError } from '../types';

interface Step2ValidateProps {
 wizard: ImportWizardState;
 locale: string;
}

export function Step2Validate({ wizard, locale }: Step2ValidateProps) {
 const t = useTranslations('master_data.import');
 const tc = useTranslations('common');

 useEffect(() => {
  // Trigger validation once
  if (wizard.data.length > 0 && !wizard.isValidating && wizard.errors.length === 0) {
   const results = validateImportData(wizard.importType, wizard.data);
   // Wait a bit to show the animation (for UX)
   setTimeout(() => {
    wizard.setValidationResults(results.errors);
   }, 1500);
  }
 }, []);


 if (wizard.isValidating) {
 return (
 <div className="flex flex-col items-center justify-center py-24 gap-8">
 <div className="relative">
 <div className="absolute inset-0 bg-cyan-500/20 blur-3xl rounded-full animate-pulse" />
 <div className="relative">
 <Loader2 className="w-24 h-24 text-cyan-500 animate-spin opacity-20" />
 <Database className="w-10 h-10 text-cyan-500 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-bounce" />
 </div>
 </div>
 <div className="text-center">
 <h3 className="text-headline-lg font-semibold mb-2 bg-gradient-to-br from-foreground to-foreground/60 bg-clip-text text-transparent">
 {t('validating')}
 </h3>
 <p className="text-label-xs text-muted-foreground font-semibold uppercase opacity-60">
 {t('processing_entries', { count: wizard.data.length })}
 </p>
 </div>
 </div>
 );
 }

 const errorCount = wizard.errors.filter((e: ValidationError) => e.severity === 'error').length;
 const warningCount = wizard.errors.filter((e: ValidationError) => e.severity === 'warning').length;

 return (
 <div className="max-w-2xl mx-auto flex flex-col gap-6 py-12">
 <Card className={cn(
 "p-10 rounded-[2.5rem] flex flex-col items-center gap-8 border-none shadow-2xl relative overflow-hidden transition-all duration-700",
 errorCount > 0 ? "bg-red-500/5 shadow-red-500/5" : "bg-emerald-500/5 shadow-emerald-500/5"
 )}>
 {/* Status Icon */}
 <div className={cn(
 "w-24 h-24 rounded-full flex items-center justify-center relative",
 errorCount > 0 ? "bg-red-500/10 text-red-500" : "bg-emerald-500/10 text-emerald-500"
 )}>
 <div className="absolute inset-0 bg-current opacity-10 animate-ping rounded-full" />
 {errorCount > 0 ? <AlertCircle className="w-12 h-12 relative z-10" /> : <CheckCircle2 className="w-12 h-12 relative z-10" />}
 </div>

 <div className="text-center">
 <h3 className="text-headline-lg font-semibold mb-2">
 {t('validation_complete')}
 </h3>
 {errorCount > 0 ? (
 <p className="text-muted-foreground font-medium">{t('errors_found', { count: errorCount })}</p>
 ) : (
 <p className="text-muted-foreground font-medium">{t('no_errors')}</p>
 )}
 </div>

 <div className="grid grid-cols-3 gap-4 w-full">
 <div className="bg-background/40 backdrop-blur-sm p-5 rounded-[1.5rem] flex flex-col items-center border border-foreground/5">
 <span className="text-label-xxs font-semibold uppercase text-muted-foreground/40 mb-1">{t('total_records')}</span>
 <span className="text-headline-lg font-display font-bold">{wizard.data.length}</span>
 </div>
 <div className="bg-background/40 backdrop-blur-sm p-5 rounded-[1.5rem] flex flex-col items-center border border-foreground/5">
 <span className="text-label-xxs font-semibold uppercase text-muted-foreground/40 mb-1">{t('errors')}</span>
 <span className={cn("text-headline-lg font-display font-bold", errorCount > 0 ? "text-red-500" : "text-emerald-500/40")}>
 {errorCount}
 </span>
 </div>
 <div className="bg-background/40 backdrop-blur-sm p-5 rounded-[1.5rem] flex flex-col items-center border border-foreground/5">
 <span className="text-label-xxs font-semibold uppercase text-muted-foreground/40 mb-1">{t('warnings')}</span>
 <span className={cn("text-headline-lg font-display font-bold", warningCount > 0 ? "text-amber-500" : "text-muted-foreground/20")}>
 {warningCount}
 </span>
 </div>
 </div>

 <div className="flex gap-4 w-full mt-4">
 <Button 
 variant="outline" 
 className="flex-1 h-14 rounded-2xl border-muted-foreground/10 hover:bg-muted-foreground/5"
 onClick={wizard.reset}
 >
 <ArrowLeft className={cn("w-4 h-4", locale === 'ar' ? "ml-2" : "mr-2")} />
 {tc('cancel')}
 </Button>
 <Button 
 className={cn(
 "flex-1 h-14 rounded-2xl font-semibold uppercase text-label-xs shadow-lg transition-all active:scale-95",
 errorCount > 0 
 ? "bg-red-500 hover:bg-red-600 shadow-red-500/20" 
 : "bg-cyan-500 hover:bg-cyan-600 shadow-cyan-500/20 text-white"
 )}
 onClick={wizard.nextStep}
 >
 {errorCount > 0 ? t('error_step') : t('commit_step')}
 <ArrowRight className={cn("w-4 h-4", locale === 'ar' ? "mr-2 rotate-180" : "ml-2")} />
 </Button>
 </div>
 </Card>
 </div>
 );
}

'use client';

import { useEffect, useState } from 'react';
import { useTranslations } from 'next-intl';
import { useForm, useFieldArray, Controller, useWatch } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Package, Plus, Trash2, ShieldCheck, Scale, Boxes, Settings2, Edit3 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Card, CardContent } from '@/components/ui/card';
import { useItem, useCreateItem, useUpdateItem, useDeleteItem } from '@/features/items/hooks/useItems';
import { useCategories } from '@/features/categories/hooks/useCategories';
import { useMasterDataList } from '@/features/master-data/hooks/useMasterDataCRUD';
import { ItemFormSchema, type ItemFormValues, UoMSchema, type Category } from '@/types/master-data';
import { useConflictHandler } from '@/core/concurrency/useConflictHandler';
import { ConflictDialog } from '@/core/concurrency/ConflictDialog';
import { ScanInput } from '@/components/shared/ScanInput/ScanInput';
import { MasterDataFormLayout } from '@/features/master-data/components/MasterDataFormLayout';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { PostConfirmDialog } from '@/components/shared/PostConfirmDialog';
import { useAbortController } from '@/hooks/useAbortController';

interface Props { 
  id: string | null; 
  createTitle: string; 
  editTitle: string; 
  viewTitle: string;
  locale: string; 
  isReadOnly?: boolean;
}

export function ItemFormClient({ id, createTitle, editTitle, viewTitle, locale, isReadOnly = false }: Props) {
  const t = useTranslations('common');
  const tm = useTranslations('master_data.common');
  const ti = useTranslations('master_data.items');
  const tv = useTranslations('master_data.validation');
  const abortController = useAbortController();

  const { data, isLoading, isError, isFetched, refetch } = useItem(id);
  const { data: categories, isLoading: isLoadingCats, isError: isErrorCats } = useCategories();
  const { data: uoms, isLoading: isLoadingUoms, isError: isErrorUoms } = useMasterDataList('units-of-measure', UoMSchema);
  
  const create = useCreateItem();
  const conflict = useConflictHandler('item', id ?? '');
  const update = useUpdateItem({ onConflict: conflict.triggerConflict });
  const deleteMutation = useDeleteItem();

  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);

  const { register, handleSubmit, reset, setValue, control, formState: { errors, isDirty, isValid } } =
    useForm<ItemFormValues>({
      resolver: zodResolver(ItemFormSchema),
      disabled: isReadOnly,
      defaultValues: {
        code: '', barcode: '', name_ar: '', name_en: '', category_id: '', primary_uom_id: '',
        track_lots: false, min_stock_level: 0, reorder_point: 0, uom_conversions: [], is_active: true,
        version: undefined,
      },
    });
  
  const { router: guardedRouter } = useUnsavedChangesGuard(isDirty);

  const { fields, append, remove } = useFieldArray({ control, name: 'uom_conversions' });

  useEffect(() => {
    if (data) {
      reset({
        code: data.code, barcode: data.barcode, name_ar: data.name_ar, name_en: data.name_en,
        category_id: data.category_id, primary_uom_id: data.primary_uom.id,
        track_lots: data.track_lots, min_stock_level: data.min_stock_level,
        reorder_point: data.reorder_point,
        uom_conversions: data.uom_conversions.map((c) => ({
          from_uom_id: c.from_uom_id, to_uom_id: c.to_uom_id, factor: c.factor,
        })),
        is_active: data.is_active,
        version: data.version,
      });
    }
  }, [data, reset]);

  const onSubmit = handleSubmit(async (values) => {
    if (isReadOnly) return;
    
    try {
      if (id) {
        await update.mutateAsync({ id, values, signal: abortController.signal });
      } else {
        await create.mutateAsync({ ...values, signal: abortController.signal });
      }
      reset(values);
      guardedRouter.push('/master-data/items', { skipGuard: true });
    } catch (error) {
      // Handled by mutation callbacks
    }
  });

  const handleDelete = async () => {
    if (!id) return;
    try {
      await deleteMutation.mutateAsync({ id, signal: abortController.signal });
      guardedRouter.push('/master-data/items', { skipGuard: true });
    } catch {
      // Handled by mutation callbacks
    }
  };

  const isSaving = create.isPending || update.isPending;
  const trackLots = useWatch({ control, name: 'track_lots' });
  const isActive = useWatch({ control, name: 'is_active' });

  // 1. Loading State
  if ((id && isLoading) || isLoadingCats || isLoadingUoms) {
    return <PageSkeleton variant="detail" />;
  }

  // 2. Not Found State (Smart 404)
  if (id && isFetched && !data) {
    return (
      <ErrorState 
        type="not_found" 
        onRetry={() => guardedRouter.push('/master-data/items', { skipGuard: true })} 
      />
    );
  }

  // 3. Server Error State
  if (isError || isErrorCats || isErrorUoms) {
    return (
      <ErrorState 
        type="server_error" 
        onRetry={() => refetch()} 
      />
    );
  }

  return (
    <>
      <MasterDataFormLayout 
        title={isReadOnly ? viewTitle : (id ? editTitle : createTitle)} 
        backHref='/master-data/items' 
        onCancel={() => guardedRouter.push('/master-data/items', { skipGuard: true })}
        isSaving={isSaving} saveDisabled={conflict.saveDisabled} 
        onSubmit={onSubmit}
        hideSave={isReadOnly}
        resource="master_data"
        saveAction={id ? 'edit' : 'create'}
        isDirty={isDirty}
        isValid={isValid}
        headerActions={
          id && (
            <div className="flex gap-4">
              <PermissionGate action="delete" resource="master_data">
                <Button 
                  variant="ghost"
                  onClick={() => setDeleteConfirmOpen(true)}
                  className="h-12 w-12 rounded-xl bg-status-error/5 hover:bg-status-error/10 text-status-error border-none transition-all"
                  title={t('actions.delete')}
                >
                  <Trash2 className="w-5 h-5" />
                </Button>
              </PermissionGate>
  
              {isReadOnly && (
                <PermissionGate action="edit" resource="master_data">
                  <Button 
                    onClick={() => guardedRouter.push(`/master-data/items/${id}/edit`)}
                    className="h-12 px-6 bg-operational-cyan text-white hover:bg-operational-cyan/90 font-bold rounded-xl flex items-center gap-2 transition-all shadow-lg shadow-operational-cyan/20"
                  >
                    <Edit3 className="w-4 h-4" />
                    {t('actions.edit')}
                  </Button>
                </PermissionGate>
              )}
            </div>
          )
        }
      >
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-8">
            {/* Main Identity Section */}
            <Card className="bg-surface-container-low border-none overflow-hidden">
              <CardContent className="p-8 space-y-8">
                <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                  <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                    <Package className="w-5 h-5 text-tertiary" />
                  </div>
                  <div>
                    <h3 className="text-body-md font-semibold text-foreground uppercase">{ti('sections.identity')}</h3>
                    <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{ti('sections.identity_desc')}</p>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-2">
                    <Label htmlFor="item-code" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{tm('code')}</Label>
                    <Input 
                      id="item-code" 
                      dir="ltr" 
                      {...register('code')} 
                      disabled={isReadOnly}
                      className="font-mono font-semibold uppercase text-status-active" 
                      placeholder={ti('fields.sku_placeholder')} 
                    />
                    {errors.code && <p className="text-label-xs font-semibold text-status-error uppercase">{tv(errors.code.message as Parameters<typeof tv>[0])}</p>}
                  </div>

                  <div className="space-y-2">
                    <Label className="text-label-xs font-semibold uppercase text-muted-foreground/70">{ti('fields.barcode')}</Label>
                    <Controller
                      name="barcode"
                      control={control}
                      render={({ field }) => (
                        <ScanInput
                          value={field.value}
                          onChange={field.onChange}
                          onScan={(barcode) => { if (!isReadOnly) setValue('barcode', barcode, { shouldValidate: true }); }}
                          placeholder={ti('fields.barcode')}
                          clearOnScan={false}
                          disabled={isReadOnly}
                          className="font-mono font-semibold text-status-active"
                        />
                      )}
                    />
                    {errors.barcode && <p className="text-label-xs font-semibold text-status-error uppercase">{tv(errors.barcode.message as Parameters<typeof tv>[0])}</p>}
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-2">
                    <Label htmlFor="item-name-en" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{ti('fields.name_en')}</Label>
                    <Input id="item-name-en" dir="ltr" {...register('name_en')} disabled={isReadOnly} className="font-semibold" />
                    {errors.name_en && <p className="text-label-xs font-semibold text-status-error uppercase">{tv(errors.name_en.message as Parameters<typeof tv>[0])}</p>}
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="item-name-ar" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{ti('fields.name_ar')}</Label>
                    <Input id="item-name-ar" dir="rtl" {...register('name_ar')} disabled={isReadOnly} className="font-semibold text-end" />
                    {errors.name_ar && <p className="text-label-xs font-semibold text-status-error uppercase">{tv(errors.name_ar.message as Parameters<typeof tv>[0])}</p>}
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Logistics Configuration Section */}
            <Card className="bg-surface-container-low border-none overflow-hidden">
              <CardContent className="p-8 space-y-8">
                <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                  <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                    <Boxes className="w-5 h-5 text-tertiary" />
                  </div>
                  <div>
                    <h3 className="text-body-md font-semibold text-foreground uppercase">{ti('sections.categorization')}</h3>
                    <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{ti('sections.categorization_desc')}</p>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-2">
                    <Label htmlFor="item-category" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{ti('fields.category')}</Label>
                    <Controller
                      name="category_id"
                      control={control}
                      render={({ field }) => (
                        <Select value={field.value} onValueChange={field.onChange} disabled={isReadOnly}>
                          <SelectTrigger id="item-category">
                            <SelectValue placeholder={tm('select_none')} />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="">{tm('select_none')}</SelectItem>
                            {categories?.data?.map((c: Category) => (
                              <SelectItem key={c.id} value={c.id} className="uppercase font-semibold text-label-sm">
                                {locale === 'ar' ? c.name_ar : c.name_en}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      )}
                    />
                    {errors.category_id && <p className="text-label-xs font-semibold text-status-error uppercase">{tv(errors.category_id.message as Parameters<typeof tv>[0])}</p>}
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="primary-uom" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{ti('fields.base_unit')}</Label>
                    <Controller
                      name="primary_uom_id"
                      control={control}
                      render={({ field }) => (
                        <Select value={field.value} onValueChange={field.onChange} disabled={isReadOnly}>
                          <SelectTrigger id="primary-uom">
                            <SelectValue placeholder={tm('select_none')} />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="">{tm('select_none')}</SelectItem>
                            {uoms?.data?.map((u) => (
                              <SelectItem key={u.id} value={u.id} className="uppercase font-semibold text-label-sm">
                                {u.code} — {u.name_en}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      )}
                    />
                    {errors.primary_uom_id && <p className="text-label-xs font-semibold text-status-error uppercase">{tv(errors.primary_uom_id.message as Parameters<typeof tv>[0])}</p>}
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Unit Conversion Protocol */}
            <Card className="bg-surface-container-low border-none overflow-hidden">
              <CardContent className="p-8 space-y-8">
                <div className="flex items-center justify-between border-b border-surface-variant/10 pb-4">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                      <Scale className="w-5 h-5 text-tertiary" />
                    </div>
                    <div>
                      <h3 className="text-body-md font-semibold text-foreground uppercase">{ti('uom_conversions')}</h3>
                      <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{tm('relational_unit_transformation')}</p>
                    </div>
                  </div>
                  {!isReadOnly && (
                    <Button type="button" variant="outline" size="sm"
                      className="h-10 px-4 text-label-xs font-semibold uppercase border-status-secondary/20 hover:bg-status-secondary/5 text-status-secondary transition-all"
                      onClick={() => append({ from_uom_id: '', to_uom_id: '', factor: 1 })}>
                      <Plus className="w-3.5 h-3.5 me-2" />{ti('add_conversion')}
                    </Button>
                  )}
                </div>

                <div className="space-y-4">
                  {fields.length === 0 ? (
                    <div className="py-12 text-center border-2 border-dashed border-surface-variant/10 rounded-lg bg-surface-container-highest/5 flex flex-col items-center gap-4 opacity-30">
                      <Scale className="w-8 h-8 text-muted-foreground/60" />
                      <p className="text-label-xs font-semibold uppercase text-muted-foreground/60">{ti('no_conversions_defined')}</p>
                    </div>
                  ) : (
                    <div className="space-y-4">
                      {fields.map((field, idx) => (
                        <div key={field.id} className="grid grid-cols-1 md:grid-cols-[1fr_1fr_0.5fr_auto] gap-4 items-end p-4 bg-surface-container-highest/20 rounded-md border border-surface-variant/10 transition-all hover:bg-surface-container-highest/30">
                          <div className="space-y-2">
                            <Label htmlFor={`uom-from-${idx}`} className="text-label-xs font-semibold uppercase text-muted-foreground/60 ps-1">{ti('from_uom')}</Label>
                            <Controller
                              name={`uom_conversions.${idx}.from_uom_id`}
                              control={control}
                              render={({ field }) => (
                                <Select value={field.value} onValueChange={field.onChange} disabled={isReadOnly}>
                                  <SelectTrigger id={`uom-from-${idx}`}>
                                    <SelectValue placeholder={tm('select_none')} />
                                  </SelectTrigger>
                                  <SelectContent>
                                    <SelectItem value="">{tm('select_none')}</SelectItem>
                                    {uoms?.data?.map((u) => (
                                      <SelectItem key={u.id} value={u.id} className="font-semibold uppercase text-label-sm">
                                        {u.code}
                                      </SelectItem>
                                    ))}
                                  </SelectContent>
                                </Select>
                              )}
                            />
                          </div>
                          <div className="space-y-2">
                            <Label htmlFor={`uom-to-${idx}`} className="text-label-xs font-semibold uppercase text-muted-foreground/60 ps-1">{ti('to_uom')}</Label>
                            <Controller
                              name={`uom_conversions.${idx}.to_uom_id`}
                              control={control}
                              render={({ field }) => (
                                <Select value={field.value} onValueChange={field.onChange} disabled={isReadOnly}>
                                  <SelectTrigger id={`uom-to-${idx}`}>
                                    <SelectValue placeholder={tm('select_none')} />
                                  </SelectTrigger>
                                  <SelectContent>
                                    <SelectItem value="">{tm('select_none')}</SelectItem>
                                    {uoms?.data?.map((u) => (
                                      <SelectItem key={u.id} value={u.id} className="font-semibold uppercase text-label-sm">
                                        {u.code}
                                      </SelectItem>
                                    ))}
                                  </SelectContent>
                                </Select>
                              )}
                            />
                          </div>
                          <div className="space-y-2">
                            <Label htmlFor={`uom-factor-${idx}`} className="text-label-xs font-semibold uppercase text-muted-foreground/60 ps-1">{ti('factor')}</Label>
                            <Input id={`uom-factor-${idx}`} type="number" dir="ltr" min={0} step="any" 
                              disabled={isReadOnly}
                              className="font-mono font-semibold text-status-secondary"
                              {...register(`uom_conversions.${idx}.factor`, { valueAsNumber: true })} />
                          </div>
                          {!isReadOnly && (
                            <Button type="button" variant="ghost" size="icon" className="h-12 w-12 text-rose-500/40 hover:text-rose-500 hover:bg-rose-500/10 transition-all"
                              onClick={() => remove(idx)}>
                              <Trash2 className="w-4 h-4" />
                            </Button>
                          )}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>
          </div>

          <div className="space-y-8">
            <Card className="bg-surface-container-low border-none overflow-hidden">
              <CardContent className="p-8 space-y-8">
                <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                  <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                    <ShieldCheck className="w-5 h-5 text-tertiary" />
                  </div>
                  <div>
                    <h3 className="text-body-md font-semibold text-foreground uppercase">{ti('fields.is_active')}</h3>
                    <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{tm('operational_availability')}</p>
                  </div>
                </div>

                <div className="space-y-4">
                  <div className="flex items-center justify-between p-4 bg-surface-container-highest/20 rounded-md border border-surface-variant/10 group transition-all hover:bg-surface-container-highest/30">
                    <div className="space-y-1">
                      <Label className="text-label-xs font-semibold uppercase cursor-pointer text-muted-foreground/60">{tm('is_active')}</Label>
                      <p className={`text-label-sm font-semibold uppercase ${isActive ? 'text-status-active' : 'text-status-error'}`}>{isActive ? tm('active') : tm('inactive')}</p>
                    </div>
                    <Switch 
                      checked={isActive} 
                      onCheckedChange={(v) => !isReadOnly && setValue('is_active', v)} 
                      disabled={isReadOnly}
                      className="data-[state=checked]:bg-status-active" 
                    />
                  </div>

                  <div className="flex items-center justify-between p-4 bg-surface-container-highest/20 rounded-md border border-surface-variant/10 group transition-all hover:bg-surface-container-highest/30">
                    <div className="space-y-1">
                      <Label className="text-label-xs font-semibold uppercase cursor-pointer text-muted-foreground/60">{ti('track_lots')}</Label>
                      <p className={`text-label-sm font-semibold uppercase ${trackLots ? 'text-status-active' : 'text-muted-foreground/40'}`}>{trackLots ? tm('yes') : tm('no')}</p>
                    </div>
                    <Switch 
                      checked={trackLots} 
                      onCheckedChange={(v) => !isReadOnly && setValue('track_lots', v)} 
                      disabled={isReadOnly}
                      className="data-[state=checked]:bg-status-active" 
                    />
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card className="bg-surface-container-low border-none overflow-hidden">
              <CardContent className="p-8 space-y-8">
                <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                  <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                    <Settings2 className="w-5 h-5 text-tertiary" />
                  </div>
                  <div>
                    <h3 className="text-body-md font-semibold text-foreground uppercase">{ti('sections.inventory_rules')}</h3>
                    <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{ti('sections.inventory_rules_desc')}</p>
                  </div>
                </div>

                <div className="space-y-6">
                  <div className="space-y-2">
                    <Label htmlFor="min-stock" className="text-label-xs font-semibold uppercase text-muted-foreground/60 ps-1">{ti('fields.min_stock')}</Label>
                    <Input id="min-stock" type="number" dir="ltr" min={0} 
                      disabled={isReadOnly}
                      className="font-mono font-semibold text-status-secondary"
                      {...register('min_stock_level', { valueAsNumber: true })} />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="reorder-point" className="text-label-xs font-semibold uppercase text-muted-foreground/60 ps-1">{ti('fields.reorder_point')}</Label>
                    <Input id="reorder-point" type="number" dir="ltr" min={0} 
                      disabled={isReadOnly}
                      className="font-mono font-semibold text-status-secondary"
                      {...register('reorder_point', { valueAsNumber: true })} />
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        </div>
      </MasterDataFormLayout>

      <ConflictDialog
        open={conflict.open}
        error={conflict.error}
        onReload={conflict.handleReload}
        onClose={conflict.handleClose}
      />

      <PostConfirmDialog
        open={deleteConfirmOpen}
        onOpenChange={setDeleteConfirmOpen}
        onConfirm={handleDelete}
        isLoading={deleteMutation.isPending}
        title={ti('delete_confirm_title')}
        description={ti('delete_confirm_desc')}
        confirmText={t('actions.delete')}
        variant="destructive"
        icon="delete"
      />
    </>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { useRouter, Link } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { Plus, Package, CheckCircle2, Search, Barcode, ShieldAlert } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { ColumnDef } from '@tanstack/react-table';
import { useItems } from '@/features/items/hooks/useItems';
import { type Item } from '@/types/master-data';
import { PageHeader } from '@/components/shared/PageHeader';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { MetricCard } from '@/components/ui/metric-card';
import { EmptyState } from '@/components/shared/EmptyState';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { Input } from '@/components/ui/input';
import { ErrorState } from '@/components/shared/ErrorState';
import { PageSkeleton } from '@/components/shared/PageSkeleton';

export function ItemListClient({ locale }: { locale: string }) {
  const t = useTranslations('common');
  const ti = useTranslations('master_data.items');
  const router = useRouter();
  const [search, setSearch] = useState('');

  const { data, isLoading, isError, refetch } = useItems({ search });

  const stats = useMemo(() => {
    const items = data?.data ?? [];
    return {
      total: items.length,
      active: items.filter(i => i.is_active).length,
      trackingLots: items.filter(i => i.track_lots).length,
    };
  }, [data]);

  const columns = useMemo<ColumnDef<Item, unknown>[]>(() => [
    { 
      accessorKey: 'code', 
      header: t('code'), 
      cell: ({ row }) => (
        <div className="flex flex-col gap-1">
          <span className="font-mono text-operational-cyan font-bold uppercase text-label-xs bg-operational-cyan/10 px-2 py-0.5 rounded-lg border border-operational-cyan/5 w-fit" dir="ltr">{row.original.code}</span>
          <span className="text-label-xxs text-muted-foreground/60 font-medium font-mono flex items-center gap-1.5 ps-1" dir="ltr">
            <Barcode className="w-3 h-3 opacity-40" />
            {row.original.barcode || '—'}
          </span>
        </div>
      )
    },
    { 
      accessorKey: 'name', 
      header: t('name'), 
      cell: ({ row }) => (
        <div className="flex flex-col gap-0.5">
          <span className="font-bold text-label-sm">{row.original.name_en}</span>
          <span className="text-label-xs text-muted-foreground/60 font-medium" dir="rtl">{row.original.name_ar}</span>
        </div>
      )
    },
    { 
      accessorKey: 'base_unit', 
      header: ti('fields.base_unit'), 
      cell: ({ row }) => (
        <span className="text-label-xs font-bold uppercase text-muted-foreground/80 px-2 py-0.5 bg-surface-container rounded-lg">
          {row.original.primary_uom.code}
        </span>
      )
    },
    {
      accessorKey: 'track_lots', 
      header: ti('fields.track_lots'),
      cell: ({ row }) => row.original.track_lots
        ? <div className="flex items-center gap-1.5 text-operational-cyan font-bold text-label-xxs uppercase bg-operational-cyan/10 px-2.5 py-1 rounded-lg border border-operational-cyan/5 w-fit">
            <div className="w-1.5 h-1.5 rounded-full bg-operational-cyan shadow-[0_0_8px_currentColor]" />
            {t('yes')}
          </div>
        : <div className="flex items-center gap-1.5 text-muted-foreground/40 font-bold text-label-xxs uppercase bg-surface-container px-2.5 py-1 rounded-lg w-fit">
            <div className="w-1.5 h-1.5 rounded-full bg-muted-foreground/20" />
            {t('no')}
          </div>,
    },
    {
      accessorKey: 'is_active', 
      header: t('status'),
      cell: ({ row }) => (
        <StatusBadge status={row.original.is_active ? 'ACTIVE' : 'INACTIVE'} className="rounded-lg px-2.5" />
      ),
    },
    {
      id: 'actions',
      header: '',
      cell: ({ row }) => (
        <div className="flex justify-end gap-3">
          <PermissionGate action="view" resource="master_data">
            <Button 
              variant="ghost" 
              size="sm" 
              className="text-label-xs font-bold uppercase text-operational-cyan hover:bg-operational-cyan/10 h-9 px-4 rounded-xl transition-all"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/items/${row.original.id}`);
              }}
            >
              {t('view')}
            </Button>
          </PermissionGate>
          <PermissionGate action="edit" resource="master_data">
            <Button 
              variant="ghost" 
              size="sm" 
              className="text-label-xs font-bold uppercase text-status-warning hover:bg-status-warning/10 h-9 px-4 rounded-xl transition-all"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/items/${row.original.id}/edit`);
              }}
            >
              {t('edit')}
            </Button>
          </PermissionGate>
        </div>
      ),
    },
  ], [t, ti, locale, router]);

  if (isLoading && !data) {
    return <PageSkeleton variant="list" />;
  }

  if (isError) {
    return (
      <div className="p-8">
        <ErrorState 
          type="server_error"
          onRetry={() => refetch()}
        />
      </div>
    );
  }

  const breadcrumbs = [
    { label: t('home'), href: `/dashboard` },
    { label: t('master_data'), href: `/master-data` },
    { label: ti('title'), href: `/master-data/items` }
  ];

  return (
    <div className="p-8 max-w-[1600px] mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <div className="space-y-4">
        <Breadcrumb items={breadcrumbs} />
        <PageHeader 
          title={ti('title')} 
          description={ti('description')}
          actions={
            <PermissionGate action="create" resource="master_data">
              <Link href={`/master-data/items/new`}>
                <Button className="h-11 px-8 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-semibold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                  <Plus className="w-3.5 h-3.5 me-2" />
                  {t('create_new')}
                </Button>
              </Link>
            </PermissionGate>
          }
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard
          label={ti('metrics.total_items')}
          value={stats.total}
          icon={Package}
          color="cyan"
        />

        <MetricCard
          label={t('active')}
          value={stats.active}
          icon={CheckCircle2}
          color="emerald"
        />

        <MetricCard
          label={ti('metrics.tracking_lots')}
          value={stats.trackingLots}
          icon={ShieldAlert}
          color="amber"
        />
      </div>

      <DataTable 
        columns={columns} 
        data={data?.data ?? []} 
        isLoading={isLoading}
        collectionName="master_data_items"
        emptyState={
          <EmptyState 
            title={ti('empty.title')}
            description={ti('empty.description')}
            action={
              <PermissionGate action="create" resource="master_data">
                <Link href={`/master-data/items/new`}>
                  <Button className="h-10 px-6 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-semibold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                    <Plus className="w-3.5 h-3.5 me-2" />
                    {t('create_new')}
                  </Button>
                </Link>
              </PermissionGate>
            }
          />
        }
        onRowClick={(r: Item) => router.push(`/master-data/items/${r.id}`)}
        filters={
          <div className="flex flex-wrap items-end gap-6 w-full py-4 px-6 bg-surface-container-low/50 border border-surface-variant/10 rounded-sm">
            <div className="flex flex-col gap-2 min-w-[300px] flex-1">
              <label className="text-label-xs font-semibold uppercase text-muted-foreground/60">{t('search')}</label>
              <div className="relative">
                <Input
                  placeholder={ti('search_placeholder')}
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="w-full bg-surface-container-highest/30 border-none h-11 ps-10 text-label-sm font-bold"
                />
                <Search className="absolute start-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40" />
              </div>
            </div>
          </div>
        }
      />
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useTranslations } from 'next-intl';
import { useForm, useWatch, Controller } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Truck, CreditCard, ShieldCheck, Edit3, Trash2 } from 'lucide-react';
import { useConflictHandler } from '@/core/concurrency/useConflictHandler';
import { ConflictDialog } from '@/core/concurrency/ConflictDialog';

import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Textarea } from '@/components/ui/textarea';
import { Card, CardContent } from '@/components/ui/card';
import { useAbortController } from '@/hooks/useAbortController';
import { MasterDataFormLayout } from '@/features/master-data/components/MasterDataFormLayout';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { useSupplier, useCreateSupplier, useUpdateSupplier, useDeleteSupplier } from '@/features/suppliers/hooks/useSuppliers';
import { useCurrencies } from '@/features/purchasing/hooks/useCurrencies';
import { SupplierFormSchema, type SupplierFormValues, type Currency } from '@/types/master-data';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';
import { Button } from '@/components/ui/button';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { PostConfirmDialog } from '@/components/shared/PostConfirmDialog';

interface Props {
  id: string | null;
  createTitle: string;
  editTitle: string;
  viewTitle: string;
  locale: string;
  isReadOnly?: boolean;
}

export function SupplierFormClient({ id, createTitle, editTitle, viewTitle, locale, isReadOnly = false }: Props) {
  const t = useTranslations('common');
  const tm = useTranslations('master_data.common');
  const ts = useTranslations('master_data.suppliers');
  const tv = useTranslations('master_data.validation');
  const abortController = useAbortController();

  const { data, isLoading, isError, refetch } = useSupplier(id);
  const { data: currencies, isLoading: isCurrenciesLoading } = useCurrencies();
  const create = useCreateSupplier();
  const conflict = useConflictHandler('supplier', id ?? '');
  const update = useUpdateSupplier({ onConflict: conflict.triggerConflict });
  const deleteMutation = useDeleteSupplier();

  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);

  const { register, handleSubmit, reset, setValue, control, formState: { errors, isDirty, isValid } } =
    useForm<SupplierFormValues>({
      resolver: zodResolver(SupplierFormSchema),
      disabled: isReadOnly,
      defaultValues: { code: '', name_ar: '', name_en: '', currency_id: '', payment_terms: '', is_active: true, version: undefined },
    });

  const { router: guardedRouter } = useUnsavedChangesGuard(isDirty);

  const isActive = useWatch({ control, name: 'is_active' });

  useEffect(() => {
    if (data) {
      reset({
        code: data.code,
        name_ar: data.name_ar,
        name_en: data.name_en,
        currency_id: data.currency_id,
        payment_terms: data.payment_terms || '',
        is_active: data.is_active,
        version: data.version,
      });
    }
  }, [data, reset]);

  const onSubmit = handleSubmit(async (values) => {
    if (isReadOnly) return;
    
    try {
      if (id) {
        await update.mutateAsync({ id, values, signal: abortController.signal });
      } else {
        await create.mutateAsync({ ...values, signal: abortController.signal });
      }
      reset(values);
      guardedRouter.push('/master-data/suppliers', { skipGuard: true });
    } catch {
      // Error handled by mutation hooks or conflict handler
    }
  });

  const handleDelete = async () => {
    if (!id) return;
    try {
      await deleteMutation.mutateAsync({ id, signal: abortController.signal });
      guardedRouter.push('/master-data/suppliers', { skipGuard: true });
    } catch {
      // Error handled by mutation hook
    }
  };

  const isSaving = create.isPending || update.isPending;

  if (id && isLoading) return <PageSkeleton variant="detail" />;
  if (id && isError) return <ErrorState onRetry={refetch} />;
  if (id && !data && !isLoading) return <ErrorState type="not_found" onRetry={() => guardedRouter.push('/master-data/suppliers')} />;
  
  if (isCurrenciesLoading && !id) return <PageSkeleton variant="detail" />;

  return (
    <>
    <MasterDataFormLayout
      title={isReadOnly ? viewTitle : (id ? editTitle : createTitle)}
      backHref='/master-data/suppliers'
      isSaving={isSaving}
      saveDisabled={conflict.saveDisabled}
      onSubmit={onSubmit}
      onCancel={() => guardedRouter.push('/master-data/suppliers', { skipGuard: true })}
      hideSave={isReadOnly}
      resource="master_data"
      saveAction={id ? 'edit' : 'create'}
      isDirty={isDirty}
      isValid={isValid}
      headerActions={
        id && (
          <div className="flex gap-4">
            <PermissionGate action="delete" resource="master_data">
              <Button 
                variant="ghost"
                onClick={() => setDeleteConfirmOpen(true)}
                className="h-12 w-12 rounded-xl bg-status-error/5 hover:bg-status-error/10 text-status-error border-none transition-all"
                title={t('actions.delete')}
              >
                <Trash2 className="w-5 h-5" />
              </Button>
            </PermissionGate>

            {isReadOnly && (
              <PermissionGate action="edit" resource="master_data">
                <Button 
                  onClick={() => guardedRouter.push(`/master-data/suppliers/${id}/edit`)}
                  className="h-12 px-6 bg-operational-cyan text-white hover:bg-operational-cyan/90 font-bold rounded-xl flex items-center gap-2 transition-all shadow-lg shadow-operational-cyan/20"
                >
                  <Edit3 className="w-4 h-4" />
                  {t('actions.edit')}
                </Button>
              </PermissionGate>
            )}
          </div>
        )
      }
    >
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          <Card className="bg-surface-container-low border-none overflow-hidden">
            <CardContent className="p-8 space-y-8">
              <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                  <Truck className="w-5 h-5 text-tertiary" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold text-foreground uppercase">{ts('partner_identity')}</h3>
                  <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{ts('partner_identity_desc')}</p>
                </div>
              </div>

              <div className="space-y-6">
                <div className="space-y-2 max-w-sm">
                  <Label htmlFor="sup-code" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{tm('code')}</Label>
                  <Input 
                    id="sup-code" 
                    dir="ltr" 
                    {...register('code')} 
                    disabled={isReadOnly}
                    className="font-mono font-semibold uppercase text-status-active" 
                    placeholder={ts('code_placeholder')} 
                  />
                  {errors.code && <p className="text-label-xs font-semibold text-status-error uppercase">{tv(errors.code.message as Parameters<typeof tv>[0])}</p>}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-2">
                    <Label htmlFor="sup-name-en" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{tm('name_en')}</Label>
                    <Input 
                      id="sup-name-en" 
                      dir="ltr" 
                      {...register('name_en')} 
                      disabled={isReadOnly}
                      className="font-semibold" 
                      placeholder={ts('name_en_placeholder')} 
                    />
                    {errors.name_en && <p className="text-label-xs font-semibold text-status-error uppercase">{tv(errors.name_en.message as Parameters<typeof tv>[0])}</p>}
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="sup-name-ar" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{tm('name_ar')}</Label>
                    <Input 
                      id="sup-name-ar" 
                      dir="rtl" 
                      {...register('name_ar')} 
                      disabled={isReadOnly}
                      className="font-semibold text-end" 
                      placeholder={ts('name_ar_placeholder')} 
                    />
                    {errors.name_ar && <p className="text-label-xs font-semibold text-status-error uppercase">{tv(errors.name_ar.message as Parameters<typeof tv>[0])}</p>}
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card className="bg-surface-container-low border-none overflow-hidden">
            <CardContent className="p-8 space-y-8">
              <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                  <CreditCard className="w-5 h-5 text-tertiary" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold text-foreground uppercase">{ts('financial_terms')}</h3>
                  <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{ts('financial_terms_desc')}</p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-2">
                  <Label htmlFor="sup-currency" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{ts('fields.currency')}</Label>
                  <Controller
                    name="currency_id"
                    control={control}
                    render={({ field }) => (
                      <Select value={field.value} onValueChange={field.onChange} disabled={isReadOnly}>
                        <SelectTrigger id="sup-currency">
                          <SelectValue placeholder="—" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="">—</SelectItem>
                          {currencies?.map((c: Currency) => (
                            <SelectItem key={c.id} value={c.id} className="font-semibold text-label-sm uppercase">
                              {c.code} — {c.name_en}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    )}
                  />
                  {errors.currency_id && <p className="text-label-xs font-semibold text-status-error uppercase">{tv(errors.currency_id.message as Parameters<typeof tv>[0])}</p>}
                </div>

                <div className="space-y-2">
                  <Label htmlFor="sup-terms" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{ts('fields.payment_terms')}</Label>
                  <Textarea 
                    id="sup-terms" 
                    rows={4} 
                    {...register('payment_terms')} 
                    disabled={isReadOnly}
                    className="font-medium resize-none p-4" 
                    placeholder={ts('terms_placeholder')} 
                  />
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        <div className="space-y-8">
          <Card className="bg-surface-container-low border-none overflow-hidden">
            <CardContent className="p-8 space-y-6">
              <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                  <ShieldCheck className="w-5 h-5 text-tertiary" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold text-foreground uppercase">{tm('status_label')}</h3>
                  <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{tm('operational_availability')}</p>
                </div>
              </div>

              <div className="flex items-center justify-between p-4 bg-surface-container-highest/20 rounded-md border border-surface-variant/10 group transition-all hover:bg-surface-container-highest/30">
                <div className="space-y-1">
                  <Label htmlFor="sup-active" className="text-label-xs font-semibold uppercase cursor-pointer text-muted-foreground/60">{tm('is_active')}</Label>
                  <p className={`text-label-sm font-semibold uppercase ${isActive ? 'text-status-active' : 'text-status-error'}`}>{isActive ? tm('active') : tm('inactive')}</p>
                </div>
                <Switch
                  id="sup-active"
                  checked={isActive}
                  onCheckedChange={(v) => !isReadOnly && setValue('is_active', v)}
                  disabled={isReadOnly}
                  className="data-[state=checked]:bg-status-active"
                />
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </MasterDataFormLayout>

    <ConflictDialog
      open={conflict.open}
      onReload={conflict.handleReload}
      onClose={conflict.handleClose}
      error={conflict.error}
    />

    <PostConfirmDialog
      open={deleteConfirmOpen}
      onOpenChange={setDeleteConfirmOpen}
      onConfirm={handleDelete}
      isLoading={deleteMutation.isPending}
      title={ts('delete_confirm_title')}
      description={ts('delete_confirm_desc')}
      confirmText={t('actions.delete')}
      variant="destructive"
      icon="delete"
    />
    </>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { useRouter, Link } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { Plus, Users, CheckCircle2, ExternalLink, CreditCard, Search } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { useSuppliers } from '@/features/suppliers/hooks/useSuppliers';
import { type Supplier } from '@/types/master-data';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { ColumnDef } from '@tanstack/react-table';
import { PageHeader } from '@/components/shared/PageHeader';
import { Input } from '@/components/ui/input';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { MetricCard } from '@/components/ui/metric-card';
import { EmptyState } from '@/components/shared/EmptyState';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';

export function SupplierListClient({ locale }: { locale: string }) {
  const t = useTranslations('common');
  const tc = useTranslations('master_data.suppliers');
  const router = useRouter();
  const [search, setSearch] = useState('');

  const { data, isLoading, isError, refetch } = useSuppliers({ search });

  const stats = useMemo(() => {
    const suppliers = data?.data || [];
    return {
      total: data?.meta?.total || 0,
      active: suppliers.filter(s => s.is_active).length,
    };
  }, [data]);

  const columns = useMemo<ColumnDef<Supplier, unknown>[]>(() => [
    {
      accessorKey: 'code',
      header: t('code'),
      cell: ({ row }) => (
        <span className="font-mono text-label-xs font-bold text-operational-cyan uppercase px-2.5 py-1 bg-operational-cyan/10 rounded-lg border border-operational-cyan/5" dir="ltr">
          {row.original.code}
        </span>
      ),
    },
    {
      accessorKey: 'name',
      header: t('name_en'),
      cell: ({ row }) => (
        <div className="flex flex-col gap-0.5">
          <span className="font-bold text-label-sm">{row.original.name_en}</span>
          <span className="text-label-xs opacity-40 font-medium" dir="rtl">{row.original.name_ar}</span>
        </div>
      ),
    },
    {
      accessorKey: 'payment_terms',
      header: tc('fields.payment_terms'),
      cell: ({ row }) => row.original.payment_terms
        ? (
          <div className="flex items-center gap-1.5 text-status-warning font-bold text-label-xs uppercase">
            <CreditCard className="w-3 h-3 opacity-60" />
            {row.original.payment_terms}
          </div>
        )
        : <span className="opacity-20 italic text-label-xs">{t('not_available')}</span>,
    },
    {
      accessorKey: 'is_active',
      header: t('status'),
      cell: ({ row }) => (
        <StatusBadge status={row.original.is_active ? 'ACTIVE' : 'INACTIVE'} className="rounded-lg px-2.5" />
      ),
    },
    {
      id: 'actions',
      header: '',
      cell: ({ row }) => (
        <div className="flex justify-end gap-3">
          <PermissionGate action="view" resource="master_data">
            <Button
              variant="ghost"
              size="sm"
              className="text-label-xs font-bold uppercase text-operational-cyan hover:bg-operational-cyan/10 h-9 px-4 rounded-xl transition-all"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/suppliers/${row.original.id}`);
              }}
            >
              {t('view')}
            </Button>
          </PermissionGate>
          <PermissionGate action="edit" resource="master_data">
            <Button 
              variant="ghost" 
              size="sm" 
              className="text-label-xs font-bold uppercase text-status-warning hover:bg-status-warning/10 h-9 px-4 rounded-xl transition-all"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/suppliers/${row.original.id}/edit`);
              }}
            >
              {t('edit')}
            </Button>
          </PermissionGate>
        </div>
      ),
    },
  ], [t, tc, locale, router]);

  if (isLoading) return <PageSkeleton variant="list" />;
  if (isError) return <ErrorState onRetry={refetch} />;

  const breadcrumbs = [
    { label: t('home'), href: `/dashboard` },
    { label: t('master_data'), href: `/master-data` },
    { label: tc('title'), href: `/master-data/suppliers` },
  ];

  return (
    <div className="p-8 max-w-[1600px] mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <Breadcrumb items={breadcrumbs} />

      <PageHeader
        title={tc('title')}
        description={tc('description')}
        actions={
          <PermissionGate action="create" resource="master_data">
            <Link href={`/master-data/suppliers/new`}>
              <Button className="h-11 px-8 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-semibold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                <Plus className="w-3.5 h-3.5 me-2" />
                {t('create_new')}
              </Button>
            </Link>
          </PermissionGate>
        }
      />

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard
          label={t('total')}
          value={stats.total}
          icon={Users}
          color="cyan"
          dir="ltr"
        />

        <MetricCard
          label={t('active')}
          value={stats.active}
          icon={CheckCircle2}
          color="emerald"
          dir="ltr"
        />

        <MetricCard
          label={tc('metrics.compliance')}
          value="100%"
          icon={ExternalLink}
          color="rose"
          dir="ltr"
        />
      </div>

      <DataTable
        columns={columns}
        data={data?.data ?? []}
        isLoading={isLoading}
        collectionName="master_data_suppliers"
        onRowClick={(r: Supplier) => router.push(`/master-data/suppliers/${r.id}`)}
        emptyState={
          <EmptyState 
            title={tc('empty.title')}
            description={tc('empty.description')}
            action={
              <PermissionGate action="create" resource="master_data">
                  <Link href={`/master-data/suppliers/new`}>
                    <Button className="h-10 px-6 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-semibold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                      <Plus className="w-3.5 h-3.5 me-2" />
                      {t('create_new')}
                    </Button>
                  </Link>
              </PermissionGate>
            }
          />
        }
        filters={
          <div className="flex flex-wrap items-end gap-6 w-full py-4 px-6 bg-surface-container-low/50 border border-surface-variant/10 rounded-sm">
            <div className="flex flex-col gap-2 min-w-[300px] flex-1">
              <label className="text-label-xs font-semibold uppercase text-muted-foreground/60">{t('search')}</label>
              <div className="relative">
                <Input
                  placeholder={tc('search_placeholder')}
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="w-full bg-surface-container-highest/30 border-none h-11 ps-10 text-label-sm font-bold"
                />
                <Search className="absolute start-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40" />
              </div>
            </div>
          </div>
        }
      />
    </div>
  );
}

