'use client';

import { useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { useForm, Controller, useWatch } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { toast } from 'sonner';
import { Ruler, Activity, ShieldCheck } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Card, CardContent } from '@/components/ui/card';
import { useState } from 'react';
import { PostConfirmDialog } from '@/components/shared/PostConfirmDialog';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { Button } from '@/components/ui/button';
import { Trash2 } from 'lucide-react';
import { MasterDataFormLayout } from '@/features/master-data/components/MasterDataFormLayout';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';
import { useUoM, useCreateUoM, useUpdateUoM, useDeleteUoM } from '@/features/uoms/hooks/useUoMs';
import { UoMFormSchema, type UoMFormValues } from '@/types/master-data';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';
import { useConflictHandler } from '@/core/concurrency/useConflictHandler';
import { ConflictDialog } from '@/core/concurrency/ConflictDialog';

import { useAbortController } from '@/hooks/useAbortController';

interface Props {
  id: string | null;
  createTitle: string;
  editTitle: string;
  viewTitle?: string;
  locale: string;
  isReadOnly?: boolean;
}

export function UoMFormClient({ id, createTitle, editTitle, viewTitle, locale, isReadOnly = false }: Props) {
  const t = useTranslations('common');
  const tu = useTranslations('master_data.uom');
  const abortController = useAbortController();

  const { data, isLoading, isError, isFetched, refetch } = useUoM(id);
  const create = useCreateUoM();
  const conflict = useConflictHandler('uom', id ?? '');
  const update = useUpdateUoM({ onConflict: conflict.triggerConflict });
  const deleteUoM = useDeleteUoM();

  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  const { register, handleSubmit, reset, control, setValue, formState: { errors, isDirty, isValid } } = useForm<UoMFormValues>({
    resolver: zodResolver(UoMFormSchema),
    defaultValues: { code: '', name_ar: '', name_en: '', is_active: true, version: undefined },
    disabled: isReadOnly,
  });

  const { router: guardedRouter } = useUnsavedChangesGuard(isDirty);

  const isActive = useWatch({ control, name: 'is_active' });

  useEffect(() => {
    if (data) {
      reset({ 
        code: data.code, 
        name_ar: data.name_ar, 
        name_en: data.name_en,
        is_active: data.is_active,
        version: data.version
      });
    }
  }, [data, reset]);

  // 1. Loading State
  if (id && isLoading) {
    return <PageSkeleton variant="detail" />;
  }

  // 2. Error State (Server/Network Error)
  if (id && isError) {
    return (
      <ErrorState 
        type="server_error"
        onRetry={() => refetch()}
      />
    );
  }

  // 3. Not Found State (Smart 404)
  if (id && isFetched && !data) {
    return (
      <ErrorState 
        type="not_found"
        onBack={() => guardedRouter.push('/master-data/units-of-measure', { skipGuard: true })}
      />
    );
  }

  const onSubmit = handleSubmit(async (values) => {
    if (isReadOnly) return;
    
    try {
      if (id) {
        await update.mutateAsync({ id, values, signal: abortController.signal });
      } else {
        await create.mutateAsync({ ...values, signal: abortController.signal });
      }
      reset(values);
      guardedRouter.push('/master-data/units-of-measure', { skipGuard: true });
    } catch {
      // Error handled by mutation hooks or conflict handler
    }
  });

  const handleDelete = async () => {
    if (!id) return;
    try {
      await deleteUoM.mutateAsync({ id, signal: abortController.signal });
      guardedRouter.push('/master-data/units-of-measure', { skipGuard: true });
    } catch {
      setShowDeleteConfirm(false);
    }
  };

  const isSaving = create.isPending || update.isPending || deleteUoM.isPending;

  // Determine the display title
  const displayTitle = id 
    ? (isReadOnly ? (viewTitle || tu('view_title')) : editTitle)
    : createTitle;

  return (
    <>
      <MasterDataFormLayout
        title={displayTitle}
        backHref='/master-data/units-of-measure'
        isSaving={isSaving} saveDisabled={conflict.saveDisabled}
        onSubmit={onSubmit}
        onCancel={() => guardedRouter.push('/master-data/units-of-measure', { skipGuard: true })}
        hideSave={isReadOnly}
        isDirty={isDirty}
        isValid={isValid}
        headerActions={
          id && !isReadOnly && (
            <PermissionGate action="delete" resource="master_data_units_of_measure">
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="text-status-error hover:text-status-error hover:bg-status-error/10 rounded-full w-10 h-10 transition-all duration-200"
                onClick={() => setShowDeleteConfirm(true)}
                disabled={isSaving}
              >
                <Trash2 className="w-5 h-5" />
              </Button>
            </PermissionGate>
          )
        }
      >
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-8">
            <Card className="bg-surface-container-low border-none overflow-hidden">
              <CardContent className="p-8 space-y-8">
                <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                  <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                    <Ruler className="w-5 h-5 text-tertiary" />
                  </div>
                  <div>
                    <h3 className="text-body-md font-semibold text-foreground uppercase">{t('basic_info')}</h3>
                    <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{tu('description')}</p>
                  </div>
                </div>

                <div className="space-y-6">
                  <div className="space-y-2 max-w-sm">
                    <Label htmlFor="uom-code" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{t('code')}</Label>
                    <Controller
                      name="code"
                      control={control}
                      render={({ field }) => (
                          <Input 
                            {...field}
                            id="uom-code" 
                            dir="ltr" 
                            disabled={isReadOnly}
                            onChange={(e) => field.onChange(e.target.value.toUpperCase())}
                            className="font-mono font-semibold uppercase text-status-active" 
                            placeholder={tu('placeholders.code')} 
                          />
                      )}
                    />
                    {errors.code && <p className="text-label-xs font-semibold text-status-error uppercase">{tu(`validation.${errors.code.message}`)}</p>}
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div className="space-y-2">
                      <Label htmlFor="uom-name-en" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{t('name_en')}</Label>
                      <Input 
                        id="uom-name-en" 
                        dir="ltr" 
                        {...register('name_en')} 
                        disabled={isReadOnly}
                        className="font-semibold" 
                        placeholder={tu('placeholders.name_en')} 
                      />
                      {errors.name_en && <p className="text-label-xs font-semibold text-status-error uppercase">{tu(`validation.${errors.name_en.message}`)}</p>}
                    </div>

                    <div className="space-y-2">
                      <Label htmlFor="uom-name-ar" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{t('name_ar')}</Label>
                      <Input 
                        id="uom-name-ar" 
                        dir="rtl" 
                        {...register('name_ar')} 
                        disabled={isReadOnly}
                        className="font-semibold text-end" 
                        placeholder={tu('placeholders.name_ar')} 
                      />
                      {errors.name_ar && <p className="text-label-xs font-semibold text-status-error uppercase">{tu(`validation.${errors.name_ar.message}`)}</p>}
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>

          <div className="space-y-8">
            <Card className="bg-surface-container-low border-none overflow-hidden">
              <CardContent className="p-8 space-y-6">
                <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                  <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                    <ShieldCheck className="w-5 h-5 text-tertiary" />
                  </div>
                  <div>
                    <h3 className="text-body-md font-semibold text-foreground uppercase">{t('status')}</h3>
                    <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{t('status')}</p>
                  </div>
                </div>

                <div className="flex items-center justify-between p-4 bg-surface-container-highest/20 rounded-md border border-surface-variant/10 group transition-all hover:bg-surface-container-highest/30">
                  <div className="space-y-1">
                    <Label htmlFor="uom-active" className="text-label-xs font-semibold uppercase cursor-pointer text-muted-foreground/60">{t('is_active')}</Label>
                    <p className={`text-label-sm font-semibold uppercase ${isActive ? 'text-status-active' : 'text-status-error'}`}>{isActive ? t('active') : t('inactive')}</p>
                  </div>
                  <Switch
                    id="uom-active"
                    checked={isActive}
                    onCheckedChange={(v) => setValue('is_active', v)}
                    className="data-[state=checked]:bg-status-active"
                  />
                </div>

                <div className="p-4 bg-amber-500/5 rounded-md border border-amber-500/10 border-dashed">
                  <div className="flex items-center gap-2 mb-2 text-amber-500">
                    <Activity className="w-3.5 h-3.5" />
                    <span className="text-label-xs font-semibold uppercase">{tu('precision')}</span>
                  </div>
                  <p className="text-label-xs text-muted-foreground/50 uppercase font-medium leading-relaxed">
                    {tu('precision_description')}
                  </p>
                </div>
              </CardContent>
            </Card>
          </div>
        </div>
      </MasterDataFormLayout>

      <ConflictDialog
        open={conflict.open}
        onReload={conflict.handleReload}
        onClose={conflict.handleClose}
      />

      <PostConfirmDialog
        open={showDeleteConfirm}
        onOpenChange={setShowDeleteConfirm}
        onConfirm={handleDelete}
        title={tu('delete_confirm_title')}
        description={tu('delete_confirm_desc')}
        isLoading={deleteUoM.isPending}
        variant="destructive"
      />
    </>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { useRouter, Link } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { Plus, Ruler, Search, Scale, BoxSelect } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { ColumnDef } from '@tanstack/react-table';
import { useUoMs } from '@/features/uoms/hooks/useUoMs';
import { type UoM } from '@/types/master-data';
import { PageHeader } from '@/components/shared/PageHeader';
import { Input } from '@/components/ui/input';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { MetricCard } from '@/components/ui/metric-card';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { EmptyState } from '@/components/shared/EmptyState';
import { ErrorState } from '@/components/shared/ErrorState';
import { PageSkeleton } from '@/components/shared/PageSkeleton';

export function UoMListClient({ locale }: { locale: string }) {
 const t = useTranslations('common');
 const tu = useTranslations('master_data.uoms');
 const router = useRouter();
 const [search, setSearch] = useState('');

  const { data, isLoading, isError, refetch } = useUoMs({ search });

  const columns = useMemo<ColumnDef<UoM, unknown>[]>(() => [
    { 
      accessorKey: 'code', 
      header: t('code'), 
      cell: ({ row }) => (
        <span className="font-mono text-label-xs font-bold text-operational-cyan uppercase px-2.5 py-1 bg-operational-cyan/10 rounded-lg border border-operational-cyan/5" dir="ltr">
          {row.original.code}
        </span>
      )
    },
    { 
      accessorKey: 'name', 
      header: t('name'), 
      cell: ({ row }) => (
        <div className="flex flex-col gap-0.5">
          <span className="font-bold text-label-sm">{row.original.name_en}</span>
          <span className="text-label-xs text-muted-foreground/60 font-medium" dir="rtl">{row.original.name_ar}</span>
        </div>
      )
    },
    {
      accessorKey: 'is_active',
      header: t('status'),
      cell: ({ row }) => (
        <StatusBadge status={row.original.is_active ? 'ACTIVE' : 'INACTIVE'} className="rounded-lg px-2.5" />
      )
    },
    {
      id: 'actions',
      header: '',
      cell: ({ row }) => (
        <div className="flex justify-end gap-3">
          <PermissionGate action="view" resource="master_data">
            <Button 
              variant="ghost" 
              size="sm" 
              className="text-label-xs font-bold uppercase text-operational-cyan hover:bg-operational-cyan/10 h-9 px-4 rounded-xl transition-all"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/units-of-measure/${row.original.id}`);
              }}
            >
              {t('view')}
            </Button>
          </PermissionGate>
          <PermissionGate action="edit" resource="master_data">
            <Button 
              variant="ghost" 
              size="sm" 
              className="text-label-xs font-bold uppercase text-status-warning hover:bg-status-warning/10 h-9 px-4 rounded-xl transition-all"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/units-of-measure/${row.original.id}/edit`);
              }}
            >
              {t('edit')}
            </Button>
          </PermissionGate>
        </div>
      ),
    },
  ], [t, router, locale]);

  if (isLoading && !data) {
    return <PageSkeleton variant="list" />;
  }

  if (isError) {
    return (
      <div className="p-8">
        <ErrorState 
          type="server_error"
          onRetry={() => refetch()}
        />
      </div>
    );
  }

  const breadcrumbs = [
    { label: t('home'), href: `/dashboard` },
    { label: t('master_data'), href: `/master-data` },
    { label: tu('title'), href: `/master-data/units-of-measure` }
  ];

  return (
    <div className="p-8 max-w-[1600px] mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <div className="space-y-4">
        <Breadcrumb items={breadcrumbs} />
        <PageHeader 
          title={tu('title')} 
          description={tu('description')}
          actions={
            <PermissionGate action="create" resource="master_data">
              <Link href={`/master-data/units-of-measure/new`}>
                <Button className="h-11 px-8 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-semibold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                  <Plus className="w-3.5 h-3.5 me-2" />
                  {t('create_new')}
                </Button>
              </Link>
            </PermissionGate>
          }
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard
          label={tu('metrics.total_uoms')}
          value={data?.meta?.total || 0}
          icon={Ruler}
          color="cyan"
          dir="ltr"
        />

        <MetricCard
          label={tu('metrics.precision')}
          value={tu('metrics.high')}
          icon={Scale}
          color="amber"
          dir="ltr"
        />

        <MetricCard
          label={tu('metrics.sync_status')}
          value={tu('metrics.synced')}
          icon={BoxSelect}
          color="emerald"
          dir="ltr"
        />
      </div>

      <DataTable 
        columns={columns} 
        data={data?.data ?? []} 
        isLoading={isLoading}
        collectionName="master_data_units_of_measure"
        onRowClick={(r: UoM) => router.push(`/master-data/units-of-measure/${r.id}`)}
        emptyState={
          <EmptyState 
            title={tu('empty.title')}
            description={tu('empty.description')}
            action={
              <PermissionGate action="create" resource="master_data">
                <Link href={`/master-data/units-of-measure/new`}>
                  <Button className="h-10 px-6 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-semibold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                    <Plus className="w-3.5 h-3.5 me-2" />
                    {t('create_new')}
                  </Button>
                </Link>
              </PermissionGate>
            }
          />
        }
        filters={
          <div className="flex flex-wrap items-end gap-6 w-full py-4 px-6 bg-surface-container-low/50 border border-surface-variant/10 rounded-sm">
            <div className="flex flex-col gap-2 min-w-[300px] flex-1">
              <label className="text-label-xs font-semibold uppercase text-muted-foreground/60">{t('search')}</label>
              <div className="relative">
                <Input
                  placeholder={tu('search_placeholder')}
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="w-full bg-surface-container-highest/30 border-none h-11 ps-10 text-label-sm font-bold"
                />
                <Search className="absolute start-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40" />
              </div>
            </div>
          </div>
        }
      />
    </div>
  );
}

'use client';

import { useEffect } from 'react';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';
import { useTranslations } from 'next-intl';
import { useForm, Controller, useWatch } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { useConflictHandler } from '@/core/concurrency/useConflictHandler';
import { ConflictDialog } from '@/core/concurrency/ConflictDialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { useState } from 'react';
import { PostConfirmDialog } from '@/components/shared/PostConfirmDialog';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { Button } from '@/components/ui/button';
import {
 Select,
 SelectContent,
 SelectItem,
 SelectTrigger,
 SelectValue,
} from '@/components/ui/select';
import { MasterDataFormLayout } from '@/features/master-data/components/MasterDataFormLayout';
import {
 useWarehouse,
 useCreateWarehouse,
 useUpdateWarehouse,
 useDeleteWarehouse,
} from '@/features/warehouses/hooks/useWarehouses';
import { useBranches } from '@/features/branches/hooks/useBranches';
import {
 WarehouseFormSchema,
 type WarehouseFormValues,
} from '@/types/master-data';

import { Card, CardContent } from '@/components/ui/card';
import { Warehouse, MapPin, Activity, Trash2 } from 'lucide-react';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';

import { useAbortController } from '@/hooks/useAbortController';

interface Props {
  id: string | null;
  createTitle: string;
  editTitle: string;
  viewTitle?: string;
  locale: string;
  isReadOnly?: boolean;
}

export function WarehouseFormClient({ id, createTitle, editTitle, viewTitle, locale, isReadOnly = false }: Props) {
  const t = useTranslations('common');
  const tw = useTranslations('master_data.warehouses');
  const abortController = useAbortController();

  const { data, isLoading, isError, isFetched, refetch } = useWarehouse(id);
  const { data: branchesData, isLoading: isLoadingBranches, isError: isErrorBranches } = useBranches();
  const branches = branchesData?.data || [];
  const create = useCreateWarehouse();
  const conflict = useConflictHandler('warehouse', id ?? '');
  const update = useUpdateWarehouse({ onConflict: conflict.triggerConflict });
  const deleteWarehouse = useDeleteWarehouse();

  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  const { register, handleSubmit, reset, setValue, control, formState: { errors, isDirty, isValid } } =
    useForm<WarehouseFormValues>({
      resolver: zodResolver(WarehouseFormSchema),
      disabled: isReadOnly,
      defaultValues: { branch_id: '', code: '', name_ar: '', name_en: '', type: 'MAIN', is_active: true, version: undefined },
    });
  
  const { router: guardedRouter } = useUnsavedChangesGuard(isDirty);

  const isActive = useWatch({ control, name: 'is_active' });

  useEffect(() => {
    if (data) {
      reset({ branch_id: data.branch_id, code: data.code, name_ar: data.name_ar, name_en: data.name_en, type: data.type, is_active: data.is_active, version: data.version });
    }
  }, [data, reset]);

  // 1. Loading State
  if ((id && isLoading) || isLoadingBranches) {
    return <PageSkeleton variant="detail" />;
  }

  // 2. Not Found State (Smart 404)
  if (id && isFetched && !data) {
    return (
      <ErrorState 
        type="not_found" 
        onRetry={() => guardedRouter.push('/master-data/warehouses', { skipGuard: true })} 
      />
    );
  }

  // 3. Server Error State
  if (isError || isErrorBranches) {
    return (
      <ErrorState 
        type="server_error" 
        onRetry={() => refetch()} 
      />
    );
  }

  const onSubmit = handleSubmit(async (values) => {
    if (isReadOnly) return;
    
    try {
      if (id) {
        await update.mutateAsync({ id, values, signal: abortController.signal });
      } else {
        await create.mutateAsync({ ...values, signal: abortController.signal });
      }
      reset(values);
      guardedRouter.push('/master-data/warehouses', { skipGuard: true });
    } catch {
      // Error handled by mutation hooks or conflict handler
    }
  });

  const handleDelete = async () => {
    if (!id) return;
    try {
      await deleteWarehouse.mutateAsync({ id, signal: abortController.signal });
      guardedRouter.push('/master-data/warehouses', { skipGuard: true });
    } catch {
      setShowDeleteConfirm(false);
    }
  };

  const isSaving = create.isPending || update.isPending || deleteWarehouse.isPending;

  // Determine the display title
  const displayTitle = id 
    ? (isReadOnly ? (viewTitle || tw('view_title')) : editTitle)
    : createTitle;

  return (
    <>
    <MasterDataFormLayout 
      title={displayTitle} 
      backHref='/master-data/warehouses' 
      isSaving={isSaving} 
      saveDisabled={conflict.saveDisabled}
      onSubmit={onSubmit}
      onCancel={() => guardedRouter.push('/master-data/warehouses', { skipGuard: true })}
      hideSave={isReadOnly}
      isDirty={isDirty}
      isValid={isValid}
      headerActions={
        id && !isReadOnly && (
          <PermissionGate action="delete" resource="master_data_warehouses">
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="text-status-error hover:text-status-error hover:bg-status-error/10 rounded-full w-10 h-10 transition-all duration-200"
              onClick={() => setShowDeleteConfirm(true)}
              disabled={isSaving}
            >
              <Trash2 className="w-5 h-5" />
            </Button>
          </PermissionGate>
        )
      }
    >
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          <Card className="bg-surface-container-low border-none overflow-hidden">
            <CardContent className="p-8 space-y-8">
              <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                  <Warehouse className="w-5 h-5 text-tertiary" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold text-foreground uppercase">{tw('title')}</h3>
                  <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">
                    {tw('description')}
                  </p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-2">
                  <Label htmlFor="wh-branch" className="text-label-xs font-semibold uppercase text-muted-foreground/70">
                    {tw('fields.branch')}
                  </Label>
                  <Controller
                    name="branch_id"
                    control={control}
                    render={({ field }) => (
                      <Select 
                        value={field.value} 
                        onValueChange={field.onChange}
                        disabled={isReadOnly}
                      >
                        <SelectTrigger id="wh-branch">
                          <SelectValue placeholder={t('null_select')} />
                        </SelectTrigger>
                        <SelectContent>
                          {branches.map((b) => (
                            <SelectItem key={b.id} value={b.id} className="font-semibold text-label-sm uppercase">
                              {b.code} — {b.name_en}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    )}
                  />
                  {errors.branch_id && <p className="text-label-xs font-semibold text-status-error uppercase">{tw(`validation.${errors.branch_id.message}`)}</p>}
                </div>

                <div className="space-y-2">
                  <Label htmlFor="wh-code" className="text-label-xs font-semibold uppercase text-muted-foreground/70">
                    {tw('fields.code')}
                  </Label>
                  <Input 
                    id="wh-code" 
                    dir="ltr" 
                    {...register('code')} 
                    disabled={isReadOnly}
                    className="font-mono font-semibold uppercase text-status-active"
                    placeholder={tw('code_placeholder')}
                  />
                  {errors.code && <p className="text-label-xs font-semibold text-status-error uppercase">{tw(`validation.${errors.code.message}`)}</p>}
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-2">
                  <Label htmlFor="wh-name-en" className="text-label-xs font-semibold uppercase text-muted-foreground/70">
                    {tw('fields.name_en')}
                  </Label>
                  <Input 
                    id="wh-name-en" 
                    dir="ltr" 
                    {...register('name_en')} 
                    disabled={isReadOnly}
                    className="font-semibold" 
                  />
                  {errors.name_en && <p className="text-label-xs font-semibold text-status-error uppercase">{tw(`validation.${errors.name_en.message}`)}</p>}
                </div>
                <div className="space-y-2">
                  <Label htmlFor="wh-name-ar" className="text-label-xs font-semibold uppercase text-muted-foreground/70">
                    {tw('fields.name_ar')}
                  </Label>
                  <Input 
                    id="wh-name-ar" 
                    dir="rtl" 
                    {...register('name_ar')} 
                    disabled={isReadOnly}
                    className="font-semibold text-end" 
                  />
                  {errors.name_ar && <p className="text-label-xs font-semibold text-status-error uppercase">{tw(`validation.${errors.name_ar.message}`)}</p>}
                </div>
              </div>
            </CardContent>
          </Card>

          <Card className="bg-surface-container-low border-none overflow-hidden">
            <CardContent className="p-8 space-y-8">
              <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                  <MapPin className="w-5 h-5 text-tertiary" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold text-foreground uppercase">{tw('fields.type')}</h3>
                  <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">
                    {t('operational_status')}
                  </p>
                </div>
              </div>

              <div className="space-y-2 max-w-md">
                <Label htmlFor="wh-type" className="text-label-xs font-semibold uppercase text-muted-foreground/70">
                  {tw('fields.type')}
                </Label>
                <Controller
                  name="type"
                  control={control}
                  render={({ field }) => (
                    <Select 
                      value={field.value} 
                      onValueChange={field.onChange}
                      disabled={isReadOnly}
                    >
                      <SelectTrigger id="wh-type">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {(['MAIN','DRY','COLD','VIRTUAL'] as const).map((ty) => (
                          <SelectItem key={ty} value={ty} className="font-semibold text-label-sm uppercase">
                            {tw(`types.${ty.toLowerCase()}` as any)}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  )}
                />
              </div>
            </CardContent>
          </Card>
        </div>

        <div className="space-y-8">
          <Card className="bg-surface-container-low border-none overflow-hidden">
            <CardContent className="p-8 space-y-6">
              <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                  <Activity className="w-5 h-5 text-tertiary" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold text-foreground uppercase">{t('status')}</h3>
                  <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">
                    {t('operational_status')}
                  </p>
                </div>
              </div>

              <div className="flex items-center justify-between p-4 bg-surface-container-highest/20 rounded-md border border-surface-variant/10 group transition-all hover:bg-surface-container-highest/30">
                <div className="space-y-1">
                  <Label htmlFor="wh-active" className="text-label-xs font-semibold uppercase cursor-pointer text-muted-foreground/60">{tw('fields.is_active')}</Label>
                  <p className={`text-label-sm font-semibold uppercase ${isActive ? 'text-status-active' : 'text-status-error'}`}>
                    {isActive ? t('active') : t('inactive')}
                  </p>
                </div>
                <Switch 
                  id="wh-active" 
                  checked={isActive} 
                  onCheckedChange={(v: boolean) => !isReadOnly && setValue('is_active', v)} 
                  disabled={isReadOnly}
                  className="data-[state=checked]:bg-status-active"
                />
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </MasterDataFormLayout>

      <ConflictDialog
        open={conflict.open}
        onReload={conflict.handleReload}
        onClose={conflict.handleClose}
      />

      <PostConfirmDialog
        open={showDeleteConfirm}
        onOpenChange={setShowDeleteConfirm}
        onConfirm={handleDelete}
        title={tw('delete_confirm_title')}
        description={tw('delete_confirm_desc')}
        isLoading={deleteWarehouse.isPending}
        variant="destructive"
      />
    </>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { useRouter, Link } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { Plus, Home, MapPin, CheckCircle2, Search } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { ColumnDef } from '@tanstack/react-table';
import { useWarehouses } from '@/features/warehouses/hooks/useWarehouses';
import { type Warehouse } from '@/types/master-data';
import { PageHeader } from '@/components/shared/PageHeader';
import { Input } from '@/components/ui/input';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { MetricCard } from '@/components/ui/metric-card';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';
import { EmptyState } from '@/components/shared/EmptyState';

export function WarehouseListClient({ locale }: { locale: string }) {
  const t = useTranslations('master_data.warehouses');
  const tc = useTranslations('common');
  const router = useRouter();
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);

  const { data, isLoading, isError, refetch } = useWarehouses({ search });
  const warehouses = data?.data || [];

  const WAREHOUSE_TYPE_STYLES: Record<string, { label: string; color: string; shadow: string }> = useMemo(() => ({
    MAIN: { label: t('types.MAIN'), color: 'text-primary', shadow: 'shadow-[0_0_8px_rgba(var(--primary-rgb),0.4)]' },
    COLD: { label: t('types.COLD'), color: 'text-operational-cyan', shadow: 'shadow-[0_0_8px_rgba(var(--cyan-rgb),0.4)]' },
    DRY: { label: t('types.DRY'), color: 'text-operational-orange', shadow: 'shadow-[0_0_8px_rgba(var(--orange-rgb),0.4)]' },
  }), [t]);

  const stats = useMemo(() => ({
    total: data?.meta?.total || 0,
    active: warehouses.filter(w => w.is_active).length,
    physical: warehouses.filter(w => w.type === 'MAIN' || w.type === 'COLD').length,
  }), [data, warehouses]);

  const columns = useMemo<ColumnDef<Warehouse, any>[]>(() => [
    {
      accessorKey: 'code',
      header: tc('code'),
      cell: ({ row }) => (
        <span className="font-mono text-label-xs font-bold text-operational-cyan uppercase px-2.5 py-1 bg-operational-cyan/10 rounded-lg border border-operational-cyan/5" dir="ltr">
          {row.original.code}
        </span>
      )
    },
    { 
      accessorKey: 'name', 
      header: tc('name'), 
      cell: ({ row }) => (
        <div className="flex flex-col gap-0.5">
          <span className="font-bold text-label-sm">{row.original.name_en}</span>
          <span className="text-label-xs opacity-40 font-medium" dir="rtl">{row.original.name_ar}</span>
        </div>
      )
    },
    {
      accessorKey: 'type', 
      header: tc('fields.type'),
      cell: ({ row }) => {
        const style = WAREHOUSE_TYPE_STYLES[row.original.type] || { label: row.original.type, color: 'text-muted-foreground', shadow: '' };
        return (
          <div className={`flex items-center gap-2 ${style.color} font-bold text-label-xxs uppercase bg-current/5 px-2.5 py-1 rounded-lg border border-current/10 w-fit`}>
            <div className={`w-1.5 h-1.5 rounded-full bg-current ${style.shadow}`} />
            {style.label}
          </div>
        );
      }
    },
    {
      accessorKey: 'is_active', 
      header: tc('fields.is_active'),
      cell: ({ row }) => (
        <StatusBadge 
          status={row.original.is_active ? 'ACTIVE' : 'INACTIVE'} className="rounded-lg px-2.5"
        />
      )
    },
    {
      id: 'actions',
      header: '',
      cell: ({ row }) => (
        <div className="flex justify-end gap-3">
          <PermissionGate action="view" resource="master_data">
            <Button 
              variant="ghost" 
              size="sm" 
              className="text-label-xs font-bold uppercase text-operational-cyan hover:bg-operational-cyan/10 h-9 px-4 rounded-xl transition-all"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/warehouses/${row.original.id}`);
              }}
            >
              {tc('view')}
            </Button>
          </PermissionGate>
          <PermissionGate action="edit" resource="master_data">
            <Button 
              variant="ghost" 
              size="sm" 
              className="text-label-xs font-bold uppercase text-status-warning hover:bg-status-warning/10 h-9 px-4 rounded-xl transition-all"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/warehouses/${row.original.id}/edit`);
              }}
            >
              {tc('edit')}
            </Button>
          </PermissionGate>
        </div>
      ),
    },
  ], [tc, t, locale, router, WAREHOUSE_TYPE_STYLES]);

  if (isLoading) return <PageSkeleton variant="list" />;
  if (isError) return <ErrorState onRetry={refetch} />;

  return (
    <div className="p-8 max-w-[1600px] mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <div className="space-y-4">
        <Breadcrumb 
          items={[
            { label: tc('home'), href: `/dashboard` },
            { label: tc('master_data'), href: `/master-data` },
            { label: t('title') }
          ]} 
        />
        <PageHeader 
          title={t('title')} 
          description={t('description')}
          actions={
            <PermissionGate action="create" resource="master_data">
              <Link href={`/master-data/warehouses/new`}>
                <Button className="h-11 px-8 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-semibold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                  <Plus className="w-3.5 h-3.5 me-2" />
                  {tc('create_new')}
                </Button>
              </Link>
            </PermissionGate>
          }
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard
          label={t('total_locations')}
          value={stats.total}
          icon={Home}
          color="cyan"
          dir="ltr"
        />

        <MetricCard
          label={tc('statuses.active')}
          value={stats.active}
          icon={CheckCircle2}
          color="emerald"
          dir="ltr"
        />

        <MetricCard
          label={tc('fields.type')}
          value={stats.physical}
          icon={MapPin}
          color="amber"
          dir="ltr"
        />
      </div>

      <DataTable 
        columns={columns} 
        data={warehouses} 
        isLoading={isLoading}
        collectionName="master_data_warehouses"
        onRowClick={(r: Warehouse) => router.push(`/master-data/warehouses/${r.id}`)}
        emptyState={
          <EmptyState 
            title={t('empty.title')}
            description={t('empty.description')}
            action={
              <PermissionGate action="create" resource="master_data">
                <Link href={`/master-data/warehouses/new`}>
                  <Button className="h-10 px-6 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-semibold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                    <Plus className="w-3.5 h-3.5 me-2" />
                    {tc('create_new')}
                  </Button>
                </Link>
              </PermissionGate>
            }
          />
        }
        filters={
          <div className="flex flex-wrap items-end gap-6 w-full py-6 px-8 bg-surface-container-medium/30 rounded-sm">
            <div className="flex flex-col gap-2 min-w-[300px] flex-1">
              <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ps-1">{tc('search')}</label>
              <div className="relative">
                <Input
                  placeholder={tc('search')}
                  value={search}
                  onChange={(e) => { setSearch(e.target.value); setPage(1); }}
                  className="w-full bg-surface-container-highest/30 border-none h-12 px-12 text-label-sm font-bold rounded-sm shadow-inner shadow-black/20"
                />
                <Search className="absolute start-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40" />
              </div>
            </div>
          </div>
        }
      />
    </div>
  );
}

