 </div>
 <div className="space-y-2">
 <h4 className="text-title-sm font-semibold uppercase text-foreground">{tip.title}</h4>
 <p className="text-label-xs font-semibold text-muted-foreground/60/40 uppercase leading-relaxed">{tip.desc}</p>
 </div>
 </div>
 ))}
 </div>
 )}
 </div>
 </div>
 </div>
 );
}

'use client';

import { useState } from 'react';
import { useTranslations } from 'next-intl';
import { Link } from '@/i18n/navigation';
import { useParams } from 'next/navigation';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { KeyRound, ArrowLeft, Mail, CheckCircle2, Loader2, Lock } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
 Form,
 FormControl,
 FormField,
 FormItem,
 FormLabel,
 FormMessage
} from '@/components/ui/form';
import { apiClient } from '@/lib/api/client';
import { ForgotPasswordSchema, ForgotPasswordInput, AuthSuccessResponseSchema } from '@/types/auth';

export default function ForgotPasswordPage() {
 const t = useTranslations('auth');
 const params = useParams();
 const locale = params.locale as string;

 const [isSubmitted, setIsSubmitted] = useState(false);
 const [error, setError] = useState<string | null>(null);

 const form = useForm<ForgotPasswordInput>({
 resolver: zodResolver(ForgotPasswordSchema),
 defaultValues: {
 email: '',
 },
 });

 const { isSubmitting } = form.formState;

 const onSubmit = async (data: ForgotPasswordInput) => {
 try {
 setError(null);
 await apiClient.post('/auth/forgot-password', AuthSuccessResponseSchema, data);
 setIsSubmitted(true);
 } catch (err) {
 setError(t('invalid_credentials')); // Fallback error
 }
 };

 if (isSubmitted) {
 return (
 <div className="w-full max-w-md p-8 bg-surface-container-low rounded-2xl border border-border-muted/50 animate-in fade-in slide-in-from-bottom-4 duration-500 text-center relative overflow-hidden">
 {/* Glow effect */}
 <div className="absolute -top-24 -start-24 w-48 h-48 bg-operational-cyan/10 blur-3xl rounded-full" />

 <div className="w-16 h-16 bg-status-success/10 rounded-full flex items-center justify-center mx-auto mb-6 border border-status-success/20">
 <CheckCircle2 className="w-8 h-8 text-status-success" />
 </div>
 <h2 className="text-headline-lg font-bold text-foreground mb-2">{t('email_sent')}</h2>
 <p className="text-muted-foreground/60 mb-8 text-body-md leading-relaxed">
 {t('email_sent_desc', { email: form.getValues('email') })}
 </p>
 <Link
        href="/login"
 className="inline-flex items-center gap-2 text-operational-cyan hover:text-operational-cyan/80 font-medium transition-colors group"
 >
 <ArrowLeft className="w-4 h-4 transition-transform group-hover:-translate-x-1 rtl:group-hover:translate-x-1" />
 {t('back_to_login')}
 </Link>
 </div>
 );
 }

 return (
 <div className="w-full max-w-md p-8 bg-surface-container-low rounded-2xl border border-border-muted/50 animate-in fade-in slide-in-from-bottom-4 duration-500 relative overflow-hidden">
 {/* Glow effect */}
 <div className="absolute -top-24 -end-24 w-48 h-48 bg-operational-cyan/10 blur-3xl rounded-full" />

 <div className="mb-8 text-center relative">
 <div className="w-12 h-12 bg-operational-cyan/10 rounded-xl flex items-center justify-center mx-auto mb-4 border border-operational-cyan/20">
 <Lock className="w-6 h-6 text-operational-cyan" />
 </div>
 <h1 className="text-headline-lg font-bold text-foreground">{t('forgot_password')}</h1>
 <p className="text-muted-foreground/60 mt-2 text-body-md">
 {t('forgot_password_desc')}
 </p>
 </div>

 <Form {...form}>
 <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6 relative">
 <FormField
 control={form.control}
 name="email"
 render={({ field }) => (
 <FormItem className="space-y-2">
 <FormLabel className="text-body-md font-medium text-foreground ms-1 flex items-center gap-2">
 <Mail className="w-4 h-4 text-muted-foreground/60" />
 {t('email')}
 </FormLabel>
 <FormControl>
 <Input
 {...field}
 type="email"
 placeholder="name@example.com"
 className="bg-surface-container-lowest border-border-muted/50 focus:border-operational-cyan/50 focus:ring-1 focus:ring-operational-cyan/30 transition-all py-6 h-12"
 />
 </FormControl>
 <FormMessage className="text-label-sm text-status-error" />
 </FormItem>
 )}
 />

 {error && (
 <div className="p-3 rounded-lg bg-status-error/10 border border-status-error/20 text-status-error text-label-sm animate-in fade-in duration-300">
 {error}
 </div>
 )}

 <Button
 type="submit"
 disabled={isSubmitting}
 className="w-full h-12 text-title-sm font-bold bg-primary hover:bg-primary/90 text-primary-foreground transition-all hover:scale-[0.98] active:scale-95 disabled:opacity-70 rounded-xl"
 >
 {isSubmitting ? (
 <Loader2 className="w-5 h-5 animate-spin" />
 ) : (
 t('send_reset_link')
 )}
 </Button>

 <div className="text-center mt-6">
 <Link
        href="/login"
 className="text-body-md text-muted-foreground/60 hover:text-operational-cyan transition-colors inline-flex items-center gap-2 group"
 >
 <ArrowLeft className="w-4 h-4 transition-transform group-hover:-translate-x-1 rtl:group-hover:translate-x-1" />
 {t('back_to_login')}
 </Link>
 </div>
 </form>
 </Form>
 </div>
 );
}

'use client';

import { useEffect, useState, useRef } from 'react';
import { useRouter } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { Loader2, AlertCircle, UtensilsCrossed, ShieldCheck, BadgeCheck, Key, EyeOff, LogIn } from 'lucide-react';
import { useAuth } from '@/providers/AuthProvider';
import LocaleSwitcher from '@/components/shared/LocaleSwitcher';

const loginSchema = z.object({
 email: z.string().email('Invalid email address'),
 password: z.string().min(6, 'Password must be at least 6 characters'),
});

type LoginValues = z.infer<typeof loginSchema>;

export default function LoginPage() {
 const t = useTranslations('auth');
 const router = useRouter();

 console.log(`[LoginPage] hero_title: ${t('login.hero_title')}`);

 const { login, user, isLoading: authLoading } = useAuth();
 const [error, setError] = useState<string | null>(null);
 const [isSubmitting, setIsSubmitting] = useState(false);
 const redirected = useRef(false);

 // Redirect authenticated users to dashboard
 useEffect(() => {
 if (!authLoading && user && !redirected.current) {
 redirected.current = true;
 router.replace('/dashboard');
 }
 }, [user, authLoading, router]);

 const { register, handleSubmit, setValue, formState: { errors } } = useForm<LoginValues>({
 resolver: zodResolver(loginSchema),
 });

 const onSubmit = async (values: LoginValues) => {
 setError(null);
 setIsSubmitting(true);
 try {
 await login(values.email, values.password);
 } catch (err: unknown) {
 setError(t('invalid_credentials'));
 setIsSubmitting(false);
 }
 };

 // Show overlay spinner only when redirecting (user is authenticated)
 if (!authLoading && user) {
 return (
 <div className="flex w-full items-center justify-center min-h-screen bg-background">
 <Loader2 className="w-8 h-8 animate-spin text-operational-cyan" />
 </div>
 );
 }

 return (
 <div className="flex w-full min-h-screen">
 {/* Left Panel */}
 <div className="hidden lg:flex w-[45%] relative flex-col justify-between p-12 overflow-hidden bg-surface-container-lowest border-r border-border-muted/50">
 {/* Faint Background image overlay (Placeholder gradient instead of photo) */}
 <div 
 className="absolute inset-0 opacity-[0.1]" 
 style={{ backgroundImage: 'radial-gradient(circle at center, var(--on-surface) 0%, transparent 70%)' }} 
 />
 <div className="absolute inset-0 bg-gradient-to-t from-surface-container-lowest via-transparent to-surface-container-lowest" />
 
 {/* Top Left */}
 <div className="relative z-10">
 <LocaleSwitcher />
 </div>

 {/* Bottom Left Content */}
 <div className="relative z-10 mt-auto">
 <div className="text-operational-cyan mb-6">
 <UtensilsCrossed className="w-10 h-10" strokeWidth={2.5} />
 </div>
 <h1 className="text-headline-lg font-bold text-foreground mb-4">
 {t('login.hero_title')}
 </h1>
 <p className="text-body-md text-muted-foreground/60 max-w-sm leading-relaxed mb-8">
 {t('login.hero_subtitle')}
 </p>
 <div className="flex items-center gap-2 text-label-xs text-muted-foreground/60 border border-border-muted/50 bg-surface-container-low/80 backdrop-blur-md w-fit px-3 py-1.5 rounded-md">
 <ShieldCheck className="w-3.5 h-3.5 text-operational-cyan" />
 <span>{t('login.v3_enabled')}</span>
 </div>
 </div>
 </div>

 {/* Right Panel */}
 <div className="flex-1 flex flex-col items-center justify-center p-8 bg-surface-container-low">
 <div className="w-full max-w-[380px]">
 <div className="mb-10">
 <h2 className="text-title-lg font-semibold text-foreground mb-2">
 {t('login.title')}
 </h2>
 <p className="text-body-md text-muted-foreground/60">
 {t('login.description')}
 </p>
 </div>

 <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
 {/* Operator ID */}
 <div className="space-y-1.5">
 <label className="text-label-xs font-medium text-muted-foreground/60">
 {t('login.operator_id')}
 </label>
 <div className="relative">
 <div className="absolute inset-y-0 start-0 ps-3.5 flex items-center pointer-events-none">
 <BadgeCheck className="w-4 h-4 text-muted-foreground/40" />
 </div>
 <input
 type="email"
 placeholder={t('login.operator_id_placeholder')}
 className="w-full bg-surface-container-lowest border border-border-muted/30 focus:border-operational-cyan/30 text-foreground text-body-md ps-10 pe-4 py-3 rounded-md outline-none transition-all placeholder:text-muted-foreground/40 focus:bg-surface-container-low"
 {...register('email')}
 />
 </div>
 {errors.email && <p className="text-label-xs text-status-error mt-1">{errors.email.message}</p>}
 </div>

 {/* Access Protocol */}
 <div className="space-y-1.5">
 <div className="flex items-center justify-between">
 <label className="text-label-xs font-medium text-muted-foreground/60">
 {t('login.access_protocol')}
 </label>
 <button type="button" onClick={() => router.push('/forgot-password')} className="text-label-xs text-operational-cyan hover:text-operational-cyan/80 font-medium">
 {t('login.recover_access')}
 </button>
 </div>
 <div className="relative">
 <div className="absolute inset-y-0 start-0 ps-3.5 flex items-center pointer-events-none">
 <Key className="w-4 h-4 text-muted-foreground/40" />
 </div>
 <input
 type="password"
 placeholder={t('login.password_placeholder')}
 className="w-full bg-surface-container-lowest border border-border-muted/30 focus:border-operational-cyan/30 text-foreground text-body-md ps-10 pe-10 py-3 rounded-md outline-none transition-all placeholder:text-muted-foreground/40 focus:bg-surface-container-low"
 {...register('password')}
 />
 <div className="absolute inset-y-0 end-0 pe-3.5 flex items-center cursor-pointer">
 <EyeOff className="w-4 h-4 text-muted-foreground/40 hover:text-muted-foreground/60 transition-colors" />
 </div>
 </div>
 {errors.password && <p className="text-label-xs text-status-error mt-1">{errors.password.message}</p>}
 </div>

 {error && (
 <div className="flex items-center gap-2 p-3 rounded-md bg-status-error/10 text-label-sm text-status-error border border-status-error/20">
 <AlertCircle className="w-4 h-4 shrink-0" />
 {error}
 </div>
 )}

 <button
 type="submit"
 disabled={isSubmitting}
 className="w-full bg-primary hover:bg-primary/90 text-primary-foreground font-semibold text-body-md py-3 rounded-xl mt-4 flex items-center justify-center gap-2 transition-all hover:scale-[0.98] active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed"
 >
 {isSubmitting ? (
 <Loader2 className="w-4 h-4 animate-spin" />
 ) : (
 <>
 <LogIn className="w-4 h-4" />
 {t('login.authenticate')}
 </>
 )}
 </button>
 </form>

 {/* Demo Credentials Helper - Subtle Design */}
 <div className="mt-8 border border-border-muted/20 rounded-md p-3 bg-surface-container-lowest/50">
 <div className="text-label-xxs text-muted-foreground/60 uppercase mb-2 font-semibold">{t('login.demo_access')}</div>
 <div className="grid grid-cols-2 gap-2">
 {[
 { role: t('roles.admin'), email: 'admin@kitchen.io' },
 { role: t('roles.manager'), email: 'store@kitchen.io' },
 { role: t('roles.chief'), email: 'kitchen@kitchen.io' },
 { role: t('roles.procurement'), email: 'procurement@kitchen.io' }
 ].map((cred, i) => (
 <div 
 key={i} 
 className="p-1.5 rounded hover:bg-surface-container-low transition-all cursor-pointer group" 
 onClick={() => {
 setValue('email', cred.email, { shouldValidate: true });
 setValue('password', 'password123', { shouldValidate: true });
 }}
 >
 <div className="text-label-xxs font-bold text-muted-foreground/60 group-hover:text-operational-cyan transition-colors">{cred.role}</div>
 <div className="text-label-xs font-mono text-muted-foreground/40 truncate">{cred.email}</div>
 </div>
 ))}
 </div>
 </div>

 <div className="mt-8 pt-4 border-t border-border-muted/30 flex items-center justify-between w-full">
 <div className="flex items-center gap-2">
 <div className="w-1.5 h-1.5 rounded-full bg-operational-cyan" />
 <span className="text-label-xs text-muted-foreground/60 font-medium">{t('login.system_online')}</span>
 </div>
 <span className="text-label-xs text-muted-foreground/40 font-mono">{t('login.version')}</span>
 </div>
 </div>
 </div>
 </div>
 );
}

'use client';

import { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { Link, useRouter } from '@/i18n/navigation';
import { useParams, useSearchParams } from 'next/navigation';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Lock, Eye, EyeOff, CheckCircle2, Loader2, AlertCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { 
 Form, 
 FormControl, 
 FormField, 
 FormItem, 
 FormLabel, 
 FormMessage 
} from '@/components/ui/form';
import { apiClient } from '@/lib/api/client';
import { ResetPasswordSchema, ResetPasswordInput, AuthSuccessResponseSchema } from '@/types/auth';

export default function ResetPasswordPage() {
 const t = useTranslations('auth');
 const params = useParams();
 const router = useRouter();
 const searchParams = useSearchParams();
 const locale = params.locale as string;
 const token = searchParams.get('token');
 
 const [showPassword, setShowPassword] = useState(false);
 const [isSuccess, setIsSuccess] = useState(false);
 const [error, setError] = useState<string | null>(null);

 const form = useForm<ResetPasswordInput>({
 resolver: zodResolver(ResetPasswordSchema),
 defaultValues: {
 token: token || '',
 password: '',
 confirmPassword: '',
 },
 });

 const { isSubmitting } = form.formState;

 // Sync token if it comes late or changes
 useEffect(() => {
 if (token) {
 form.setValue('token', token);
 }
 }, [token, form]);

 const onSubmit = async (data: ResetPasswordInput) => {
 try {
 setError(null);
 await apiClient.post('/auth/reset-password', AuthSuccessResponseSchema, data);
 setIsSuccess(true);
 
 // Auto redirect after 3 seconds
 setTimeout(() => {
  router.push('/login');
 }, 3000);
 } catch (err) {
 setError(t('invalid_credentials')); // Fallback error
 }
 };

 if (!token && !isSuccess) {
 return (
 <div className="w-full max-w-md p-8 bg-surface-container-low rounded-2xl border border-border-muted/50 text-center">
 <div className="w-16 h-16 bg-status-error/10 rounded-full flex items-center justify-center mx-auto mb-6 border border-status-error/20">
 <AlertCircle className="w-8 h-8 text-status-error" />
 </div>
 <h2 className="text-headline-lg font-bold text-foreground mb-2">{t('invalid_reset_link')}</h2>
 <p className="text-muted-foreground/60 mb-8 text-body-md">
 {t('invalid_reset_link_desc')}
 </p>
 <Link 
  href="/forgot-password" 
 className="inline-flex items-center gap-2 text-operational-cyan hover:text-operational-cyan/80 font-medium"
 >
 {t('forgot_password')}
 </Link>
 </div>
 );
 }

 if (isSuccess) {
 return (
 <div className="w-full max-w-md p-8 bg-surface-container-low rounded-2xl border border-border-muted/50 animate-in fade-in slide-in-from-bottom-4 duration-500 text-center relative overflow-hidden">
 {/* Glow effect */}
 <div className="absolute -top-24 -start-24 w-48 h-48 bg-operational-cyan/10 blur-3xl rounded-full" />
 
 <div className="w-16 h-16 bg-status-success/10 rounded-full flex items-center justify-center mx-auto mb-6 border border-status-success/20">
 <CheckCircle2 className="w-8 h-8 text-status-success" />
 </div>
 <h2 className="text-headline-lg font-bold text-foreground mb-2">{t('password_reset_success')}</h2>
 <p className="text-muted-foreground/60 mb-8 text-body-md leading-relaxed">
 {t('password_reset_redirect')}
 </p>
 <Link 
  href="/login" 
 className="inline-flex items-center gap-2 text-operational-cyan hover:text-operational-cyan/80 font-medium transition-colors"
 >
 {t('back_to_login')}
 </Link>
 </div>
 );
 }

 return (
 <div className="w-full max-w-md p-8 bg-surface-container-low rounded-2xl border border-border-muted/50 animate-in fade-in slide-in-from-bottom-4 duration-500 relative overflow-hidden">
 {/* Glow effect */}
 <div className="absolute -top-24 -end-24 w-48 h-48 bg-operational-cyan/10 blur-3xl rounded-full" />

 <div className="mb-8 text-center relative">
 <div className="w-12 h-12 bg-operational-cyan/10 rounded-xl flex items-center justify-center mx-auto mb-4 border border-operational-cyan/20">
 <Lock className="w-6 h-6 text-operational-cyan" />
 </div>
 <h1 className="text-headline-lg font-bold text-foreground">{t('reset_password')}</h1>
 <p className="text-muted-foreground/60 mt-2 text-body-md">
 {t('reset_password_desc')}
 </p>
 </div>

 <Form {...form}>
 <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-5 relative">
 <FormField
 control={form.control}
 name="password"
 render={({ field }) => (
 <FormItem className="space-y-2">
 <FormLabel className="text-body-md font-medium text-foreground ms-1">{t('new_password')}</FormLabel>
 <FormControl>
 <div className="relative">
 <Input
 {...field}
 type={showPassword ? 'text' : 'password'} className="bg-surface-container-lowest border-border-muted/50 focus:border-operational-cyan/50 focus:ring-1 focus:ring-operational-cyan/30 transition-all py-6 h-12 pe-10"
 />
 <button
 type="button"
 onClick={() => setShowPassword(!showPassword)}
 className="absolute end-3 top-1/2 -translate-y-1/2 text-muted-foreground/60 hover:text-foreground transition-colors"
 >
 {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
 </button>
 </div>
 </FormControl>
 <FormMessage className="text-label-sm text-status-error" />
 </FormItem>
 )}
 />

 <FormField
 control={form.control}
 name="confirmPassword"
 render={({ field }) => (
 <FormItem className="space-y-2">
 <FormLabel className="text-body-md font-medium text-foreground ms-1">{t('confirm_new_password')}</FormLabel>
 <FormControl>
 <Input
 {...field}
 type="password"
 className="bg-surface-container-lowest border-border-muted/50 focus:border-operational-cyan/50 focus:ring-1 focus:ring-operational-cyan/30 transition-all py-6 h-12"
 />
 </FormControl>
 <FormMessage className="text-label-sm text-status-error" />
 </FormItem>
 )}
 />

 {error && (
 <div className="p-3 rounded-lg bg-status-error/10 border border-status-error/20 text-status-error text-label-sm animate-in fade-in duration-300">
 {error}
 </div>
 )}

 <Button 
 type="submit" 
 disabled={isSubmitting}
 className="w-full h-12 mt-2 text-title-sm font-bold bg-primary hover:brightness-110 text-primary-foreground transition-all hover:scale-[0.98] active:scale-95 disabled:opacity-70 rounded-xl"
 >
 {isSubmitting ? (
 <Loader2 className="w-5 h-5 animate-spin" />
 ) : (
 t('reset_password')
 )}
 </Button>
 </form>
 </Form>
 </div>
 );
}

'use client';
