'use client';
import { useState, useMemo } from 'react';
import type { Lot } from '@/types/master-data';
import type { LotAllocation } from '@/types/documents';
import type { UserRole } from '@/providers/AuthProvider';
import { useTranslations } from 'next-intl';
import { sortLotsByFEFO, isExpired, isNearExpiry } from '@/utils/fefo';
import { LotRow } from './LotRow';

interface FEFOLotAllocatorProps {
 lots: Lot[];
 requestedQty: number;
 uomLabel: string;
 userRole: UserRole;
 onAllocate: (allocations: LotAllocation[]) => void;
 onClose: () => void;
}

export function FEFOLotAllocator({ lots, requestedQty, uomLabel, userRole, onAllocate, onClose }: FEFOLotAllocatorProps) {
 const t = useTranslations('operations.issue');
 const tc = useTranslations('common');
 const sortedLots = useMemo(() => sortLotsByFEFO(lots), [lots]);
 
 const [allocations, setAllocations] = useState<Record<string, { qty: number, reason: string }>>(() => {
 const initialAllocations: Record<string, { qty: number, reason: string }> = {};
 let remaining = requestedQty;
 
 for (const lot of sortedLots) {
 if (remaining <= 0) break;
 if (isExpired(lot.expiry_date) && !['ADMIN', 'INV_MGR'].includes(userRole)) {
 continue;
 }
 
 const toAllocate = Math.min(remaining, lot.qty_available);
 if (toAllocate > 0) {
 initialAllocations[lot.id] = { qty: toAllocate, reason: '' };
 remaining -= toAllocate;
 }
 }
 return initialAllocations;
 });

 const totalAllocated = Object.values(allocations).reduce((sum, current) => sum + (current.qty || 0), 0);
 
 const isValid = totalAllocated === requestedQty && sortedLots.every(lot => {
 const alloc = allocations[lot.id];
 if (alloc && alloc.qty > 0 && isExpired(lot.expiry_date)) {
 return !!alloc.reason;
 }
 return true;
 });

 const handleConfirm = () => {
 if (!isValid) return;
 const finalAllocations = Object.entries(allocations)
 .filter(([__unused_id, data]) => data.qty > 0)
 .map(([id, data]) => {
 const lot = lots.find(l => l.id === id)!;
 return {
 lot_id: lot.id,
 lot_number: lot.lot_number,
 expiry_date: lot.expiry_date,
 allocated_qty: data.qty,
 override_reason: isExpired(lot.expiry_date) ? data.reason : null
 };
 });
 onAllocate(finalAllocations);
 };

 return (
 <div className="flex flex-col gap-4">
 <div className="flex justify-between items-center bg-surface-container p-4 rounded-xl border border-border-surface">
 <h3 className="font-bold text-foreground">{t('fefo_allocator_title')}</h3>
 <div className={`font-mono font-bold ${totalAllocated !== requestedQty ? 'text-status-error' : 'text-operational-cyan'}`}>
 {t('allocated')}: <span dir="ltr">{totalAllocated} / {requestedQty}</span> {uomLabel}
 </div>
 </div>
 
 <div className="flex flex-col gap-2 max-h-96 overflow-y-auto">
 {sortedLots.map(lot => (
 <LotRow 
 key={lot.id}
 lot={lot}
 allocatedQty={allocations[lot.id]?.qty || 0}
 onQtyChange={(qty) => setAllocations(prev => ({ ...prev, [lot.id]: { ...prev[lot.id], qty } }))}
 isExpired={isExpired(lot.expiry_date)}
 isNearExpiry={isNearExpiry(lot.expiry_date)}
 userRole={userRole}
 onExpiredOverride={(reason) => setAllocations(prev => ({ ...prev, [lot.id]: { ...prev[lot.id], reason } }))}
 />
 ))}
 </div>
 
 <div className="flex justify-end gap-2 mt-4">
 <button onClick={onClose} className="px-4 py-2 bg-surface-container-high text-foreground rounded-xl font-medium hover:bg-surface-container-highest transition-colors">{tc('cancel')}</button>
 <button 
 onClick={handleConfirm}
 disabled={!isValid}
 className="px-6 py-2.5 bg-operational-cyan text-primary-foreground rounded-xl font-bold disabled:opacity-50 disabled:cursor-not-allowed hover:brightness-110 transition-all active:scale-[0.98]"
 >
 {t('confirm_allocation')}
 </button>
 </div>
 </div>
 );
}

import { useTranslations, useLocale } from 'next-intl';
import { formatDate } from '@/utils/currency';
import type { Lot } from '@/types/master-data';
import type { UserRole } from '@/providers/AuthProvider';
import { ExpiredOverrideInline } from './ExpiredOverrideInline';

export function LotRow({ 
 lot, 
 allocatedQty, 
 onQtyChange, 
 isExpired, 
 isNearExpiry, 
 userRole, 
 onExpiredOverride 
}: { 
 lot: Lot; 
 allocatedQty: number; 
 onQtyChange: (qty: number) => void; 
 isExpired: boolean; 
 isNearExpiry: boolean; 
 userRole: UserRole; 
 onExpiredOverride: (reason: string) => void;
}) {
 const t = useTranslations('common.table_headers');
 const tc = useTranslations('operations.issue');
  const locale = useLocale();
  const bgClass = isExpired ? 'bg-status-error/10' : isNearExpiry ? 'bg-status-warning/10' : 'bg-surface-container';
 
 const canOverride = ['ADMIN', 'INV_MGR'].includes(userRole);
 const inputDisabled = isExpired && !canOverride;

 return (
 <div className={`p-3 rounded-xl border border-border-surface ${bgClass}`}>
 <div className="flex justify-between items-center mb-2">
 <div className="flex gap-4">
 <div>
 <span className="text-label-sm text-muted-foreground block mb-1">{t('lot')}</span>
 <span dir="ltr" className="font-mono font-medium text-body-md text-foreground">{lot.lot_number}</span>
 </div>
 <div>
 <span className="text-label-sm text-muted-foreground block mb-1">{t('expiry')}</span>
  <span dir="ltr" className="font-mono text-body-md text-foreground">{formatDate(lot.expiry_date, locale as any)}</span>
 </div>
 <div>
 <span className="text-label-sm text-muted-foreground block mb-1">{t('available')}</span>
 <span dir="ltr" className="font-mono text-body-md text-foreground">{lot.qty_available}</span>
 </div>
 </div>
 
 <div className="flex items-center gap-2">
 {isExpired && !canOverride && (
 <span className="text-label-sm bg-status-error text-white px-2 py-1 rounded font-bold">{tc('expired_status')}</span>
 )}
 
 <input 
 type="number" 
 min="0"
 max={lot.qty_available}
 value={allocatedQty || ''} onChange={(e) => onQtyChange(Number(e.target.value))}
 disabled={inputDisabled}
 className="w-20 bg-surface-container-high border border-border-surface text-foreground rounded-lg p-1 text-center font-mono focus:border-operational-cyan outline-none disabled:opacity-50"
 />
 </div>
 </div>
 
 {isExpired && canOverride && (
 <ExpiredOverrideInline onReasonChange={onExpiredOverride} />
 )}
 </div>
 );
}

'use client';
import { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { Loader2 } from 'lucide-react';
import { apiClient } from '@/lib/api/client';
import { z } from 'zod';

const FxRateSchema = z.object({
 rate: z.number()
});

interface FXRateCaptureProps {
 fromCurrencyCode: string;
 toCurrencyCode: string;
 defaultRate?: number;
 onRateConfirmed: (rate: number) => void;
}

export function FXRateCapture({ fromCurrencyCode, toCurrencyCode, defaultRate, onRateConfirmed }: FXRateCaptureProps) {
 const t = useTranslations('procurement.grn');
 const tCommon = useTranslations('common');
 const [rate, setRate] = useState<number | ''>(defaultRate || '');
 const [isLoading, setIsLoading] = useState(!defaultRate);
 
 useEffect(() => {
 if (defaultRate) return;
 
 const controller = new AbortController();
 const fetchRate = async () => {
 try {
 const response = await apiClient.get(
 `/currencies/fx-rates?from=${fromCurrencyCode}&to=${toCurrencyCode}`,
 z.object({ data: FxRateSchema }),
 controller.signal
 );
 setRate(response.data.rate);
 setIsLoading(false);
 } catch (err) {
 setIsLoading(false);
 }
 };
 
 fetchRate();
 
 return () => { controller.abort(); };
 }, [defaultRate, fromCurrencyCode, toCurrencyCode]);

 const numericRate = Number(rate);
 const isValid = numericRate > 0;

 return (
 <div className="bg-surface-container-lowest border border-transparent rounded-2xl p-6">
 <h3 className="text-title-sm font-bold text-foreground mb-4 flex items-center gap-2">
 <div className="w-1.5 h-6 bg-operational-cyan rounded-full" />
 {t('fx_capture_title')}
 </h3>
 
 <div className="flex flex-col gap-5">
 <div className="flex items-center gap-3">
 <span className="font-mono text-muted-foreground bg-surface-container-lowest px-4 py-3 rounded-xl border border-outline-low text-body-md">
 1 {fromCurrencyCode} =
 </span>
 <input 
 dir="ltr"
 type="number"
 min="0.0001"
 step="0.0001"
 value={rate}
 onChange={(e) => {
 const val = e.target.value;
 setRate(val === '' ? '' : Number(val));
 }}
 disabled={isLoading}
 className="flex-1 bg-surface-container-lowest border border-outline-low text-foreground rounded-xl px-4 py-3 focus:border-operational-cyan focus:ring-1 focus:ring-operational-cyan/50 outline-none font-mono text-title-sm shadow-inner transition-all"
 />
 <span className="font-mono text-muted-foreground bg-surface-container-lowest px-4 py-3 rounded-xl border border-outline-low text-body-md">
 {toCurrencyCode}
 </span>
 </div>
 
 <div className="text-label-sm text-status-warning bg-status-warning/10 border border-status-warning/20 rounded-xl p-4 flex items-start gap-3">
 <div className="w-1 h-1 rounded-full bg-status-warning mt-1.5 shrink-0" />
 <p className="leading-relaxed opacity-90">
 {t('fx_permanent_warning')}
 </p>
 </div>
 
 <div className="flex justify-end mt-2">
 <button 
 onClick={() => onRateConfirmed(numericRate)}
 disabled={!isValid || isLoading}
 className="px-6 py-3 bg-primary text-primary-foreground font-bold rounded-xl disabled:opacity-50 transition-all hover:shadow-[0_0_20px_rgba(var(--primary-rgb),0.3)] hover:brightness-110 active:scale-[0.98] flex items-center gap-2"
 >
 {isLoading && <Loader2 className="w-4 h-4 animate-spin" />}
 {tCommon('confirm_rate') || 'تأكيد السعر'}
 </button>
 </div>
 </div>
 </div>
 );
}

'use client';

import React, { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
}

export class GlobalErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false
  };

  public static getDerivedStateFromError(_: Error): State {
    return { hasError: true };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error:', error, errorInfo);
  }

  public render() {
    if (this.state.hasError) {
      return this.props.fallback || (
        <div className="flex min-h-screen items-center justify-center bg-background p-4 text-center">
          <div className="space-y-4">
            <h1 className="text-2xl font-bold text-destructive">Something went wrong</h1>
            <p className="text-muted-foreground">The application encountered an unexpected error.</p>
            <button
              onClick={() => window.location.reload()}
              className="rounded bg-primary px-4 py-2 text-primary-foreground hover:bg-primary/90"
            >
              Reload Page
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

