  DocumentStatus,
} from '@/contracts/statuses';
import { isDocumentLocked as engineIsDocumentLocked, DocumentType } from '@/core/workflow/document-engine';

/**
 * Issue Guards
 */
export const isIssuePosted = (status?: string | null): boolean => 
  status === ISSUE_STATUS.POSTED;

export const isIssueDraft = (status?: string | null): boolean => 
  status === ISSUE_STATUS.DRAFT;

/**
 * Stocktake Guards
 */
export const canStartStocktake = (status?: string | null): boolean => 
  status === STOCKTAKE_STATUS.DRAFT || status === STOCKTAKE_STATUS.STARTED;

export const isStocktakeCounting = (status?: string | null): boolean => 
  status === STOCKTAKE_STATUS.COUNTING;

export const isStocktakeInReview = (status?: string | null): boolean => 
  status === STOCKTAKE_STATUS.REVIEW;

export const isStocktakeApproved = (status?: string | null): boolean => 
  status === STOCKTAKE_STATUS.APPROVED;

export const isStocktakeDraft = (status?: string | null): boolean => 
  status === STOCKTAKE_STATUS.DRAFT;

export const isStocktakePosted = (status?: string | null): boolean =>
  status === STOCKTAKE_STATUS.POSTED;

export const isStocktakeClosed = (status?: string | null): boolean =>
  status === STOCKTAKE_STATUS.CLOSED;

export const isStocktakeInProgress = (status?: string | null): boolean => 
  !!status && ([STOCKTAKE_STATUS.STARTED, STOCKTAKE_STATUS.COUNTING, STOCKTAKE_STATUS.REVIEW] as string[]).includes(status);

/**
 * Transfer Guards
 */
export const isTransferInTransit = (status?: string | null): boolean => 
  status === TRANSFER_STATUS.IN_TRANSIT;

export const isTransferPosted = (status?: string | null): boolean => 
  status === TRANSFER_STATUS.POSTED;

/**
 * Adjustment Guards
 */
export const isAdjustmentDraft = (status?: string | null): boolean =>
  status === ADJUSTMENT_STATUS.DRAFT;

export const isAdjustmentPosted = (status?: string | null): boolean =>
  status === ADJUSTMENT_STATUS.POSTED;

export const isAdjustmentPending = (status?: string | null): boolean =>
  status === ADJUSTMENT_STATUS.SUBMITTED;

/**
 * PR/PO/GRN Guards
 */
export const isPRDraft = (status?: string | null): boolean => status === PR_STATUS.DRAFT;
export const isPODraft = (status?: string | null): boolean => status === PO_STATUS.DRAFT;
export const isGRNDraft = (status?: string | null): boolean => status === GRN_STATUS.DRAFT;

/**
 * Generic & Workflow Guards
 */
export const isDraft = (status?: string | null): boolean => 
  status === 'DRAFT';

export const isPosted = (status?: string | null): boolean => 
  status === 'POSTED';

/**
 * Wraps the document engine's lock logic with a simpler domain interface.
 */
export const isLocked = (type: DocumentType, status?: string | null): boolean => {
  if (!status) return false;
  return engineIsDocumentLocked(type, status);
};

import { 
  ISSUE_STATUS, 
  STOCKTAKE_STATUS, 
  TRANSFER_STATUS, 
  PR_STATUS,
  PO_STATUS,
  GRN_STATUS,
  ADJUSTMENT_STATUS,
  KITCHEN_REQUEST_STATUS,
  DocumentStatus 
} from '@/contracts/statuses';

export type BadgeVariant = 'default' | 'brand' | 'warning' | 'error' | 'success' | 'outline' | 'info';

interface StatusConfig {
  variant: BadgeVariant;
  labelKey: string;
}

/**
 * Global Status to UI Mapping
 * Used as the base for all document types.
 */
export const STATUS_UI_CONFIG: Record<string, StatusConfig> = {
  // Generic / Common
  DRAFT: { variant: 'outline', labelKey: 'statuses.draft' },
  POSTED: { variant: 'success', labelKey: 'statuses.posted' },
  CANCELLED: { variant: 'error', labelKey: 'statuses.cancelled' },
  SUBMITTED: { variant: 'info', labelKey: 'statuses.submitted' },
  APPROVED: { variant: 'success', labelKey: 'statuses.approved' },
  REJECTED: { variant: 'error', labelKey: 'statuses.rejected' },
  PENDING: { variant: 'warning', labelKey: 'statuses.pending' },
  COMPLETED: { variant: 'success', labelKey: 'statuses.completed' },
  
  // PR/PO Specific
  CLOSED: { variant: 'default', labelKey: 'statuses.closed' },
  PARTIAL: { variant: 'info', labelKey: 'statuses.partial' },
  FULFILLED: { variant: 'success', labelKey: 'statuses.fulfilled' },

  // GRN Specific
  RECEIVED: { variant: 'success', labelKey: 'statuses.received' },

  // Stocktake Specific
  STARTED: { variant: 'brand', labelKey: 'statuses.started' },
  COUNTING: { variant: 'info', labelKey: 'statuses.counting' },
  REVIEW: { variant: 'warning', labelKey: 'statuses.review' },
  
  // Transfer Specific
  IN_TRANSIT: { variant: 'warning', labelKey: 'statuses.in_transit' },

  // Specialized / Missing
  VARIANCE_SUBMITTED: { variant: 'warning', labelKey: 'statuses.variance_submitted' },
  COUNTING_COMPLETED: { variant: 'info', labelKey: 'statuses.counting_completed' },
  ACTIVE: { variant: 'success', labelKey: 'statuses.active' },
  INACTIVE: { variant: 'error', labelKey: 'statuses.inactive' },
};

/**
 * Domain-specific overrides or specialized mappings
 */
export const ISSUE_STATUS_UI: Record<string, StatusConfig> = {
  ...STATUS_UI_CONFIG,
  [ISSUE_STATUS.SUBMITTED]: { variant: 'warning', labelKey: 'statuses.pending_review' },
};

export const ADJUSTMENT_STATUS_UI: Record<string, StatusConfig> = {
  ...STATUS_UI_CONFIG,
  [ADJUSTMENT_STATUS.SUBMITTED]: { variant: 'warning', labelKey: 'statuses.pending_approval' },
};

export const STOCKTAKE_STATUS_UI: Record<string, StatusConfig> = {
  ...STATUS_UI_CONFIG,
  [STOCKTAKE_STATUS.REVIEW]: { variant: 'warning', labelKey: 'statuses.variance_review' },
};

export const TRANSFER_STATUS_UI: Record<string, StatusConfig> = {
  ...STATUS_UI_CONFIG,
  [TRANSFER_STATUS.IN_TRANSIT]: { variant: 'warning', labelKey: 'statuses.in_transit' },
};

/**
 * Helper to get config with a fallback
 */
export const getStatusConfig = (status: string, customMap?: Record<string, StatusConfig>): StatusConfig => {
  const map = customMap || STATUS_UI_CONFIG;
  return map[status] || STATUS_UI_CONFIG[status] || { variant: 'default', labelKey: 'statuses.unknown' };
};

