export function useCurrency(id: string | null) {

 return useQuery({
 queryKey: [...QUERY_KEY, id],
    queryFn: async () => {
      if (!id) return null;
      // In production, fetch specific ID
      const response = await fetch(`/api/currencies/${id}`);
      if (!response.ok) return null;
      return response.json();
    },
