 { label: getEntityTitle() },
 ]}
 />

 <PageHeader
 title={`${t('title')} — ${getEntityTitle()}`}
 description={t('select_type')}
 />

 {/* Stepper Container */}
 <div 
 className={cn(
 "flex items-center justify-between relative px-10 py-8",
 isRtl && "flex-row-reverse"
 )}
 >
