 className={`h-14 px-12 rounded-2xl text-label-xs font-semibold uppercase gap-3 transition-all hover:scale-[0.98] hover:brightness-110 active:scale-95 ${ step === 3 ? 'bg-status-success hover:bg-status-success/90 text-white' : 'primary-gradient text-white hover:opacity-90' }`}
 >
 {isSubmitting ? (
 t('actions.saving')
 ) : (
 <>
 {step === 3 ? t('actions.save') : t('actions.next')}
 {step < 3 && <ChevronRight className={`w-4 h-4 ${isRtl ? 'rotate-180' : ''}`} />}
 {step === 3 && <CheckCircle2 className="w-4 h-4" />}
 </>
 )}
 </Button>
 </div>
 </div>
 </form>
 </Form>
 </div>
 </div>
 );
}

'use client';

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useSafeMutation } from '@/core/concurrency/useSafeMutation';
import { toast } from 'sonner';
import { useTranslations } from 'next-intl';
import { type Item, type ItemFormValues, ItemSchema } from '@/types/master-data';
import { apiClient } from '@/lib/api/client';
import { z } from 'zod';

const QUERY_KEY = ['items'];

const PaginatedItemsSchema = z.object({
  data: z.array(ItemSchema),
  meta: z.object({
    total: z.number(),
    page: z.number(),
    page_size: z.number(),
    total_pages: z.number()
  })
});

export function useItems(filters?: { search?: string; category_id?: string; is_active?: boolean }) {
  return useQuery({
    queryKey: [...QUERY_KEY, filters],
    queryFn: ({ signal }) => {
      const params = new URLSearchParams();
      if (filters?.search) params.append('search', filters.search);
      if (filters?.category_id) params.append('category_id', filters.category_id);
      if (filters?.is_active !== undefined) params.append('is_active', String(filters.is_active));

      const path = `/items${params.toString() ? `?${params.toString()}` : ''}`;
      return apiClient.get(path, PaginatedItemsSchema, signal);
    }
  });
}

export function useItem(id: string | null) {
  return useQuery({
    queryKey: [...QUERY_KEY, id],
    queryFn: ({ signal }) => {
      if (!id) return null;
      return apiClient.get(`/items/${id}`, ItemSchema, signal);
    },
    enabled: !!id,
  });
}

export function useCreateItem() {
  const queryClient = useQueryClient();
  const t = useTranslations('master_data.items');

  return useMutation({
    mutationFn: (values: ItemFormValues & { signal?: AbortSignal }) => {
      const { signal, ...dataValues } = values;
      return apiClient.post('/items', ItemSchema, {
        ...dataValues,
        code: dataValues.code.toUpperCase()
      }, signal);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: QUERY_KEY });
      toast.success(t('created_success'));
    },
    onError: (error) => {
      if (error instanceof Error && error.name === 'AbortError') return;
      toast.error(t('errors.create_failed'));
    }
  });
}

export function useUpdateItem(options?: { onConflict?: () => void }) {
  const queryClient = useQueryClient();
  const t = useTranslations('master_data.items');

  return useSafeMutation({
    onConflict: options?.onConflict,
    meta: { suppressGlobalConflict: true },
    mutationFn: ({ id, values, signal }: { id: string; values: ItemFormValues; signal?: AbortSignal }) => {
      return apiClient.put(`/items/${id}`, ItemSchema, {
        ...values,
        code: values.code.toUpperCase()
      }, signal);
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: QUERY_KEY });
      queryClient.setQueryData([...QUERY_KEY, data.id], data);
      toast.success(t('updated_success'));
    },
    onError: (error: unknown) => {
      const err = error as { name?: string; code?: string; message?: string };
      if (err.name === 'AbortError') return;

      const errorCode = err.code || err.message;
      if (errorCode === 'GUARD_STOCK_EXISTS') {
        toast.error(t('errors.cannot_deactivate_with_stock'));
      } else {
        toast.error(t(`errors.${errorCode}`) || t('errors.update_failed'));
      }
    }
  });
}

export function useDeleteItem() {
  const queryClient = useQueryClient();
  const t = useTranslations('master_data.items');

  return useMutation({
    mutationFn: ({ id, signal }: { id: string; signal?: AbortSignal }) => {
      return apiClient.del(`/items/${id}`, z.any(), signal);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: QUERY_KEY });
      toast.success(t('deleted_success'));
    },
    onError: (error: unknown) => {
      const err = error as { name?: string; code?: string; message?: string };
      if (err.name === 'AbortError') return;
      const errorCode = err.code || err.message;
      if (errorCode === 'GUARD_STOCK_EXISTS') {
        toast.error(t('errors.cannot_deactivate_with_stock'));
      } else {
        toast.error(t(`errors.${errorCode}`) || t('errors.delete_failed'));
      }
    }
  });
}

