import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { canPerformActionV2, isDocumentLocked, type DocumentStatus } from '@/core/workflow/document-engine';
import { useAuth } from '@/providers/AuthProvider';
import type { LotAllocation, StockIssue } from '@/types/documents';
import { ActionGuard } from '@/core/workflow/ActionGuard';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { StatusTimeline, type StatusTimelineEntry, type Status } from '@/components/shared/StatusTimeline';
import { cn } from '@/lib/utils';
import { ISSUE_STATUS } from '@/contracts/statuses';
import { useAbortController } from '@/hooks/useAbortController';
import type { ApiError } from '@/types/api';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';

interface IssueFormProps {
  issue?: StockIssue;
  id: string;
  isNew: boolean;
  onConflict?: () => void;
}

export function IssueForm({ issue, id, isNew, onConflict }: IssueFormProps) {
  const t = useTranslations('operations.issue');
  const locale = useLocale();
  const router = useRouter();
  const { user } = useAuth();
  const abortController = useAbortController();
  
  const postIssue = usePostIssue(id, { onConflict });
  const isPostPending = postIssue.isPending;

  const [lines, setLines] = useState<LineItem[]>(() => (issue?.lines || []) as unknown as LineItem[]);
  const [destinationId, setDestinationId] = useState(() => issue?.destination_dept_id ?? '');
  const [warehouseId, setWarehouseId] = useState(() => issue?.warehouse_id || 'wh-1');
  const [notes, setNotes] = useState(() => issue?.notes || '');
  const [scanError, setScanError] = useState('');
  const [requestedBy, setRequestedBy] = useState(() => issue?.requested_by ?? '');

  // Unsaved Changes Guard
  const isDirty = useMemo(() => {
    if (isNew) {
      return lines.length > 0 || !!destinationId || !!notes || !!requestedBy;
    }
    
    // Check if lines have changed
    const linesChanged = JSON.stringify(lines) !== JSON.stringify(issue?.lines || []);
    const destChanged = destinationId !== (issue?.destination_dept_id ?? '');
    const notesChanged = notes !== (issue?.notes || '');
    const reqByChanged = requestedBy !== (issue?.requested_by ?? '');
    
    return linesChanged || destChanged || notesChanged || reqByChanged;
  }, [isNew, lines, destinationId, notes, requestedBy, issue]);

  const { router: guardedRouter } = useUnsavedChangesGuard(isDirty);
  
  const [isPostDialogOpen, setIsPostDialogOpen] = useState(false);
  const [isWarehouseLockedError, setIsWarehouseLockedError] = useState(false);

  // FEFO Allocator State
  const [fefoOpen, setFefoOpen] = useState(false);
  const [activeLine, setActiveLine] = useState<LineItem | null>(null);

  const { data: deptData } = useDepartments();
  const departments = deptData?.data || [];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (lines.length > 0 && !!destinationId) {
      setIsPostDialogOpen(true);
    }
  };

  // Auto fetch lots when activeLine changes
  const { data: lots = [] } = useLotsByItem({ 
    item_id: activeLine?.item?.id || '', 
    warehouse_id: warehouseId 
  });

  // Lock Banner state
  const { data: lockState } = useWarehouseLock(warehouseId);

  // Workflow Engine Integrations
  const status = (issue?.status || ISSUE_STATUS.DRAFT) as DocumentStatus;
  const isDocLocked = isDocumentLocked("ISSUE", status);
  const isWarehouseLocked = !!lockState?.isLocked;
  
  const canEdit = !isDocLocked;


  const handleScan = async (barcode: string) => {
    try {
      setScanError('');
      const ItemSchema = z.object({
        data: z.array(z.object({
          id: z.string(), code: z.string(), name_ar: z.string(), name_en: z.string(),
          primary_uom: z.object({ id: z.string(), code: z.string(), name_ar: z.string(), name_en: z.string() })
        }))
      });
      const res = await apiClient.get(`/master-data/items?barcode=${barcode}`, ItemSchema, abortController.signal);
      if (res.data && res.data.length > 0) {
        const item = res.data[0];
        setLines(prev => {
          const existing = prev.find(l => l.item.id === item.id);
          if (existing) {
            return prev.map(l => l.item.id === item.id ? { ...l, qty: l.qty + 1 } : l);
          }
          return [...prev, {
            id: `new-${Date.now()}`,
            item,
            qty: 1,
            uom_id: item.primary_uom.id,
            lot_allocations: []
          }];
        });
      } else {
        setScanError(t('no_item_found'));
      }
    } catch (err: unknown) {
      if ((err as Error)?.name === 'AbortError') return;
      setScanError(t('no_item_found'));
    }
  };

  const removeLine = (lineId: string) => {
    setLines(prev => prev.filter(l => l.id !== lineId));
  };

  const handleLotClick = (line: LineItem) => {
    setActiveLine(line);
    setFefoOpen(true);
  };

  const handlePost = async () => {
    if (!issue) return;
    try {
      await postIssue.mutateAsync({ 
        confirmation: 'ACKNOWLEDGE_IRREVERSIBLE',
        version: issue.version,
        signal: abortController.signal
      });
      setIsPostDialogOpen(false);
      guardedRouter.push('/issues', { skipGuard: true });
    } catch (err: unknown) {
      const apiErr = err as { code?: string; name?: string };
      if (apiErr?.name === 'AbortError') return;
      if (apiErr?.code === 'WAREHOUSE_LOCKED') {
        setIsWarehouseLockedError(true);
        setIsPostDialogOpen(false);
      }
    }
  };

  const history = useMemo((): StatusTimelineEntry[] => {
    if (!issue) return [];
    const h: StatusTimelineEntry[] = [
      { status: ISSUE_STATUS.DRAFT.toLowerCase() as Status, at: issue.created_at ?? '', by: issue.created_by ?? 'System' }
    ];
    if (issue.posted_at) {
      h.push({ status: ISSUE_STATUS.POSTED.toLowerCase() as Status, at: issue.posted_at, by: issue.posted_by != null ? issue.posted_by : 'System' });
    }
    return h;
  }, [issue]);

  return (
    <div className="min-h-screen bg-surface-container-low flex flex-col animate-in fade-in duration-1000 pb-32">
      <div className="glass-header sticky top-0 z-50 h-16 px-6 lg:px-10 flex items-center justify-between gap-6">
        <div className="flex items-center gap-6">
          <Button 
            variant="ghost" 
            size="icon" 
            onClick={() => guardedRouter.back()} 
            className="rounded-lg shrink-0 hover:bg-primary/5 transition-colors"
          >
            <ArrowLeft className={cn("w-5 h-5 text-primary", locale === 'ar' && "rotate-180")} />
          </Button>
          <div className="flex flex-col">
            <div className="flex items-center gap-3">
              <h1 className="text-title-lg font-semibold uppercase italic text-foreground leading-none">
                {isNew ? t('create_new') : t('detail_title')}
              </h1>
              {!isNew && (
                <div className="px-2 py-0.5 bg-primary/10 rounded flex items-center gap-1.5">
                  <span className="text-label-xxs font-semibold uppercase text-primary leading-none">
                    {issue?.document_number || '—'}
                  </span>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col">
        <DocumentLockBanner isLocked={isDocLocked} status={status} />
        
        <DocumentLockWrapper isLocked={isDocLocked}>
          <div className="flex-1 px-6 lg:px-10 py-8">
        
        <div className="grid grid-cols-12 gap-8">
          <div className="col-span-12 lg:col-span-8 space-y-8">
            {!isDocLocked && (
              <div className="bg-surface-container-lowest p-8 rounded-lg shadow-sm relative overflow-hidden group transition-all hover:shadow-md">
                <div className="relative space-y-6">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center">
                      <Package className="w-4 h-4 text-primary" />
                    </div>
                    <h3 className="text-label-xs font-semibold uppercase text-primary/30 group-hover:text-primary transition-colors">{t('scan_and_add')}</h3>
                  </div>
                  <ScanInput 
                    onScan={handleScan} 
                    disabled={isDocLocked} 
                    placeholder={t('scan_placeholder')} 
                    onError={(bc) => setScanError(t('not_found_prefix') + bc)}
                    className="bg-surface-container-low rounded-lg transition-all focus-within:ring-1 focus-within:ring-primary-fixed-dim/10 shadow-none border-none"
                  />
                  {scanError && (
                    <div className="flex items-center gap-3 p-4 bg-red-500/5 rounded-xl text-label-xs font-bold text-red-500 uppercase animate-in shake duration-500">
                      <AlertCircle className="w-4 h-4" />
                      {scanError}
                    </div>
                  )}
                </div>
              </div>
            )}
            
            <div className="bg-surface-container-lowest rounded-lg overflow-hidden shadow-sm">
                  <div className="p-8 flex justify-between items-center">
                    <div className="flex items-center gap-4">
                      <div className="w-1 h-6 bg-primary/20 rounded-full" />
                      <h3 className="text-label-xs font-semibold uppercase text-primary/30">{t('line_items')}</h3>
                    </div>
                    <div className="px-4 py-2 bg-surface-container-low rounded-lg text-label-xs font-mono text-primary/40">
                      {lines.length} {t('entries').toUpperCase()}
                    </div>
                  </div>
                  <DocumentLineItemTable 
                    lines={lines} 
                    locale={locale as 'ar' | 'en'} isReadOnly={isDocLocked}
                    onRemoveLine={removeLine}
                    extraColumns={[
                      {
                        header: t('qty'),
                        cell: (line) => (
                          <div className="flex items-center gap-2">
                            <Input 
                              type="number" 
                              dir="ltr"
                              className="w-24 h-10 bg-surface-container-low border-none rounded-lg text-center font-mono text-body-md shadow-none focus-visible:ring-1 focus-visible:ring-primary-fixed-dim/10 disabled:opacity-50 transition-all"
                              value={line.qty as number} 
                              disabled={isDocLocked}
                              onChange={e => {
                                const val = Number(e.target.value);
                                setLines(prev => prev.map(l => l.id === line.id ? { ...l, qty: val } : l));
                              }} 
                            />
                            <span className="text-label-xs font-semibold uppercase text-primary/20">{line.item.primary_uom.code}</span>
                          </div>
                        )
                      },
                      {
                        header: t('allocate'),
                        cell: (line: LineItem) => {
                          const lineAllocations = line.lot_allocations || [];
                          const totalAllocated = lineAllocations.reduce((sum: number, a: LotAllocation) => sum + a.allocated_qty, 0);
                          const isFullyAllocated = totalAllocated >= line.qty;
                          
                          if (isDocLocked) {
                            return (
                              <div className="flex flex-wrap gap-1.5 max-w-[200px]">
                                {lineAllocations.map((alloc, idx) => (
                                  <div key={idx} className="px-2.5 py-1 bg-emerald-500/10 rounded-lg flex items-center gap-1.5">
                                    <span className="text-label-xxs font-mono text-emerald-500/80">{alloc.lot_number}</span>
                                    <div className="w-1 h-1 rounded-full bg-emerald-500/30" />
                                    <span className="text-label-xxs font-semibold text-emerald-500">{alloc.allocated_qty}</span>
                                  </div>
                                ))}
                                {lineAllocations.length === 0 && (
                                  <span className="text-label-xxs font-semibold uppercase text-muted-foreground/30">—</span>
                                )}
                              </div>
                            );
                          }

                          return (
                            <Button 
                              variant="ghost"
                              size="sm"
                              className={`h-10 px-5 text-label-xs font-semibold uppercase rounded-lg transition-all ${ isFullyAllocated ? 'bg-emerald-500/10 text-emerald-500 hover:bg-emerald-500/20' : 'bg-primary/10 text-primary hover:bg-primary/20' }`}
                              onClick={() => handleLotClick(line)}
                            >
                              {lineAllocations.length > 0 
                                ? <div className="flex items-center gap-2" dir="ltr">
                                    <span>{totalAllocated}</span>
                                    <div className="w-1 h-1 rounded-full bg-current/30" />
                                    <span className="opacity-50">{line.qty}</span>
                                  </div> 
                                : t('allocate')}
                            </Button>
                          );
                        }
                      }
                    ]}
                  />
                </div>
            </div>


          <div className="col-span-12 lg:col-span-4 space-y-8">
            <div className="bg-surface-container-lowest p-8 rounded-lg shadow-sm relative overflow-hidden group transition-all hover:shadow-md">
              <div className="relative space-y-10">
                <div className="flex items-center gap-4 pb-6">
                  <div className="w-12 h-12 rounded-lg bg-primary/10 flex items-center justify-center">
                    <FileText className="w-6 h-6 text-primary" />
                  </div>
                  <div>
                    <h3 className="text-label-xs font-semibold uppercase text-primary/30 group-hover:text-primary transition-colors">{t('document_manifest')}</h3>
                    <p className="text-label-xs text-primary/20 font-bold">{t('operational_parameters')}</p>
                  </div>
                </div>

                <div className="space-y-8">
                  <div className="space-y-3 group">
                    <div className="flex items-center gap-2">
                      <ArrowRight className={cn("w-4 h-4 opacity-50 group-hover:opacity-100 transition-opacity", locale === 'ar' ? "rotate-180" : "")} />
                      <label className="text-label-xs font-semibold uppercase text-muted-foreground/60">{t('destination')}</label>
                    </div>
                    <Select 
                      value={destinationId} 
                      onValueChange={(val) => setDestinationId(val || '')} 
                      disabled={isDocLocked}
                    >
                      <SelectTrigger className="w-full h-12 bg-surface-container-highest border-none rounded-lg px-4 font-bold text-label-sm transition-all shadow-none focus:ring-1 focus:ring-primary-fixed-dim/10">
                        <SelectValue placeholder={t('select_department')} />
                      </SelectTrigger>
                      <SelectContent className="bg-surface-container-highest border-none rounded-lg shadow-2xl">
                        {departments.map((dept) => (
                          <SelectItem key={dept.id} value={dept.id} className="text-label-sm font-bold focus:bg-primary/10 focus:text-primary">
                            {locale === 'ar' ? dept.name_ar : dept.name_en}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-3 group">
                    <div className="flex items-center gap-2">
                      <User className="w-3 h-3 text-cyan-500/50" />
                      <label className="text-label-xs font-semibold uppercase text-muted-foreground/60">{t('requested_by')}</label>
                    </div>
                    <Input 
                      type="text"
                      value={requestedBy}
                      onChange={e => setRequestedBy(e.target.value)}
                      disabled={isDocLocked}
                      placeholder={t('requested_by_placeholder')}
                      className="w-full h-12 bg-surface-container-highest border-none rounded-lg px-4 font-bold text-label-sm transition-all placeholder:text-muted-foreground/20 shadow-none focus-visible:ring-1 focus-visible:ring-primary-fixed-dim/10"
                    />
                  </div>

                  <div className="space-y-3 group pt-4">
                    <div className="flex items-center gap-2">
                      <Clock className="w-3 h-3 text-cyan-500/50" />
                      <label className="text-label-xs font-semibold uppercase text-muted-foreground/60">{t('operational_notes')}</label>
                    </div>
                    <Textarea 
                      value={notes} 
                      onChange={e => setNotes(e.target.value)} 
                      disabled={isDocLocked} 
                      placeholder={t('notes_placeholder')}
                      className="w-full bg-surface-container-highest border-none rounded-lg p-5 text-label-sm font-medium transition-all min-h-[140px] resize-none placeholder:text-muted-foreground/20 leading-relaxed shadow-none focus-visible:ring-1 focus-visible:ring-primary-fixed-dim/10"
                    />
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-surface-container-lowest p-8 rounded-lg shadow-sm relative overflow-hidden group transition-all hover:shadow-md">
              <div className="flex items-center gap-4 mb-8">
                <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center">
                  <History className="w-5 h-5 text-primary" />
                </div>
                <h4 className="text-label-xs font-semibold uppercase text-primary/30 group-hover:text-primary transition-colors">{t('status_history')}</h4>
              </div>
              
              <div className="relative ps-2">
                <StatusTimeline entries={history} />
              </div>

              {!isNew && (
                <div className="mt-10 pt-8 border-t border-primary/5 space-y-4">
                  <div className="flex justify-between items-center group">
                    <span className="text-label-xs text-primary/20 font-semibold uppercase">{t('created_by')}</span>
                    <div className="px-3 py-1 bg-surface-container-low rounded-lg transition-colors group-hover:bg-primary/5">
                      <span className="text-label-xs font-mono font-semibold text-primary/60 group-hover:text-primary transition-colors" dir="ltr">{user?.name || 'System'}</span>
                    </div>
                  </div>
                  <div className="flex justify-between items-center group">
                    <span className="text-label-xs text-primary/20 font-semibold uppercase">{t('created_at')}</span>
                    <div className="px-3 py-1 bg-surface-container-low rounded-lg transition-colors group-hover:bg-primary/5">
                      <span className="text-label-xs font-mono font-semibold text-primary/60 group-hover:text-primary transition-colors" dir="ltr">
                        {formatDate(issue?.created_at, locale as 'ar' | 'en')}
                      </span>
                    </div>
                  </div>
                </div>
              )}
            </div>

          </div>
            </div>
          </div>
        </DocumentLockWrapper>

        <FormFooter 
          isLocked={isDocLocked}
          onCancel={() => guardedRouter.push('/issues')}
          onSubmit={() => setIsPostDialogOpen(true)}
          isPending={isPostPending}
          submitLabel={t('post_issue')}
          canSubmit={lines.length > 0 && !!destinationId}
        />
      </form>

      <PostConfirmDialog 
        open={isPostDialogOpen} 
        onOpenChange={setIsPostDialogOpen}
        title={t('post_confirm_title')}
        description={t('post_confirm_desc')}
        warningText=""
        requiresTextConfirmation={true}
        onConfirm={handlePost}
        isLoading={isPostPending}
      />

          <Dialog open={fefoOpen} onOpenChange={setFefoOpen}>
            <DialogContent className="max-h-[85vh] max-w-2xl bg-surface-container-lowest border-none shadow-2xl rounded-lg p-0 overflow-hidden">
              <div className="p-8 border-b border-primary/5 bg-primary/[0.02]">
                <DialogHeader>
                  <DialogTitle className="text-title-lg font-semibold uppercase italic italic text-foreground">
                    {t('fefo_drawer_title')}: <span className="text-primary font-mono">{locale === 'ar' ? activeLine?.item.name_ar : activeLine?.item.name_en}</span>
                  </DialogTitle>
                </DialogHeader>
              </div>
              <div className="p-8">
                {activeLine && (
                  <FEFOLotAllocator
                    lots={lots}
                    requestedQty={activeLine.qty}
                    uomLabel={activeLine.item.primary_uom.code}
                    userRole={user?.role || 'WH_KEEPER'} onAllocate={(allocations) => {
                      setLines(prev => prev.map(l => l.id === activeLine.id ? {
                        ...l, lot_allocations: allocations
                      } : l));
                      setFefoOpen(false);
                    }}
                    onClose={() => setFefoOpen(false)}
                  />
                )}
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { useTranslations, useLocale } from 'next-intl';
import { useRouter } from '@/i18n/navigation';
import { PageHeader } from '@/components/shared/PageHeader';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { Button } from '@/components/ui/button';
import { StatusBadge, type BadgeStatus } from '@/components/shared/StatusBadge';
import { DocumentReadOnlyOverlay } from '@/components/shared/DocumentReadOnlyOverlay';
import { DocumentLineItemTable } from '@/components/shared/DocumentLineItemTable/DocumentLineItemTable';
import { LockBanner } from '@/components/shared/LockBanner';
import { TransferLine } from '@/features/operations/hooks/useTransfer';
import { useWarehouseLock } from '@/hooks/useWarehouseLock';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { Truck, PackageCheck, Printer, ArrowLeft } from 'lucide-react';
import { format } from 'date-fns';
import { ActionGuard } from '@/core/workflow/ActionGuard';
import { TRANSFER_STATUS } from '@/contracts/statuses';
import { type DocumentStatus } from '@/core/workflow/document-engine';
import { useAuth } from '@/providers/AuthProvider';
import { Link } from '@/i18n/navigation';
import { DocumentLockBanner, DocumentLockWrapper } from '@/components/shared/DocumentLockBanner';
import { FormFooter } from '@/components/shared/FormFooter';
import type { Transfer } from '@/types/documents';

interface TransferFormProps {
  transfer: Transfer;
  id: string;
  onConflict: (type: string, id: string) => void;
}

export function TransferForm({ transfer, id, onConflict }: TransferFormProps) {
  const locale = useLocale();
  const t = useTranslations('operations.transfer');
  const tCommon = useTranslations('common');
  const router = useRouter();
  const { user } = useAuth();

  // Dual warehouse lock
  const { data: fromLockState } = useWarehouseLock(transfer?.from_warehouse_id ?? '');
  const { data: toLockState } = useWarehouseLock(transfer?.to_warehouse_id ?? '');
  const isFromLocked = fromLockState?.isLocked ?? false;
  const isToLocked = toLockState?.isLocked ?? false;
  const isEitherLocked = isFromLocked || isToLocked;

  const transferStatus = (transfer?.transfer_status || TRANSFER_STATUS.DRAFT) as DocumentStatus;
  const isLocked = transferStatus !== TRANSFER_STATUS.DRAFT;

  return (
    <div className="p-8 max-w-[1600px] mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <div className="flex items-center justify-between">
        <Breadcrumb 
          items={[
            { label: tCommon('modules.operations'), href: `/transfers` },
            { label: t('title'), href: `/transfers` },
            { label: t('detail_title') }
          ]} 
        />
        <Button
          variant="ghost"
          onClick={() => router.back()}
          className="text-label-xs font-semibold uppercase text-muted-foreground hover:text-foreground transition-colors"
        >
          <ArrowLeft className="w-3 h-3 me-2" />
          {tCommon('back')}
        </Button>
      </div>

      <PageHeader
        title={t('detail_title')}
        description={
          <div className="flex items-center gap-2">
            <span>{tCommon('doc_number')}</span>
            <span dir="ltr" className="font-mono text-cyan-500/80">{transfer?.document_number}</span>
          </div>
        }
        actions={
          <div className="flex gap-4 items-center">
            <StatusBadge status={transferStatus as BadgeStatus} />
            
            <Button
              variant="outline"
              className="bg-surface-container-high border-white/5 rounded-xl h-11 px-6 text-label-xs font-semibold uppercase transition-all hover:bg-surface-container-highest"
              onClick={() => window.print()}
            >
              <Printer className="w-4 h-4 me-2" />
              {tCommon('print')}
            </Button>
          </div>
        }
      />

      <form 
        onSubmit={(e) => e.preventDefault()} 
        className="space-y-8"
      >
        <DocumentLockBanner 
          status={transferStatus} 
          isLocked={isLocked} 
        />

        <DocumentLockWrapper isLocked={isLocked}>
          <div className="space-y-8">
            <div className="space-y-2">
              {isFromLocked && <LockBanner lockState={fromLockState} />}
              {isToLocked && toLockState?.sessionId !== fromLockState?.sessionId && (
                <LockBanner lockState={toLockState} />
              )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-8 bg-surface-container-low/50 p-8 rounded-2xl border border-white/5 relative overflow-hidden shadow-2xl">
              <div className="absolute top-0 inset-x-0 h-1 bg-gradient-to-e from-cyan-500/50 via-cyan-500/20 to-transparent" />

              <div className="space-y-2">
                <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{t('from_warehouse')}</label>
                <div className="bg-surface-container-highest/40 border border-white/5 rounded-xl p-4 font-bold text-body-md">
                  {transfer?.from_warehouse_name}
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{t('to_warehouse')}</label>
                <div className="bg-surface-container-highest/40 border border-white/5 rounded-xl p-4 font-bold text-body-md">
                  {transfer?.to_warehouse_name}
                </div>
              </div>

              {transfer?.shipped_at && (
                <div className="space-y-2">
                  <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{t('shipped_at')}</label>
                  <div className="bg-surface-container-highest/30 border border-white/5 rounded-xl p-4 flex items-center justify-between">
                    <span dir="ltr" className="font-mono text-body-md font-bold text-cyan-500/80">
                      {format(new Date(transfer.shipped_at), 'MMM dd, yyyy HH:mm')}
                    </span>
                    <Truck className="w-4 h-4 text-cyan-500/40" />
                  </div>
                </div>
              )}

              {transfer?.received_at && (
                <div className="space-y-2">
                  <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{t('received_at')}</label>
                  <div className="bg-surface-container-highest/30 border border-white/5 rounded-xl p-4 flex items-center justify-between">
                    <span dir="ltr" className="font-mono text-body-md font-bold text-emerald-500/80">
                      {format(new Date(transfer.received_at), 'MMM dd, yyyy HH:mm')}
                    </span>
                    <PackageCheck className="w-4 h-4 text-emerald-500/40" />
                  </div>
                </div>
              )}

              <div className="col-span-1 md:col-span-4 space-y-2">
                <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{tCommon('notes')}</label>
                <div className="bg-surface-container-highest/40 border border-white/5 rounded-xl p-4 font-medium text-body-md min-h-[60px]">
                  {transfer?.notes || '—'}
                </div>
              </div>

              {transfer?.variance_reason && (
                <div className="col-span-1 md:col-span-4 space-y-2">
                  <label className="text-label-xs font-semibold uppercase text-status-warning/80 ms-1">{t('variance_reason')}</label>
                  <div className="bg-status-warning/5 border border-status-warning/20 rounded-xl p-4 font-medium text-body-md">
                    {transfer.variance_reason}
                  </div>
                </div>
              )}
            </div>

            <div className="bg-surface-container-low/30 rounded-2xl border border-white/5 overflow-hidden shadow-2xl">
              <DocumentReadOnlyOverlay isPosted={true}>
                <DocumentLineItemTable
                  lines={transfer?.lines ?? []}
                  isReadOnly={true}
                  onRemoveLine={() => {}}
                  hideLotColumns={true}
                  headers={{
                    code: tCommon('table_headers.code'),
                    name: tCommon('table_headers.name'),
                    qty: t('transfer_qty'),
                    uom: tCommon('table_headers.uom'),
                  }}
                  extraColumns={[
                    {
                      header: t('shipped_qty'),
                      cell: (line: TransferLine) => (
                        <div className="flex justify-center">
                          <span dir="ltr" className="font-mono text-body-md font-semibold bg-surface-container-highest px-3 py-1 rounded-lg border border-white/5">
                            {line.shipped_qty ?? line.qty}
                          </span>
                        </div>
                      ),
                    },
                    {
                      header: t('received_qty'),
                      cell: (line: TransferLine) => (
                        <div className="flex justify-center">
                          <span dir="ltr" className={`font-mono text-body-md font-semibold px-3 py-1 rounded-lg border border-white/5 ${line.received_qty ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 'bg-surface-container-highest text-muted-foreground/40'}`}>
                            {line.received_qty ?? '—'}
                          </span>
                        </div>
                      ),
                    },
                  ]}
                />
              </DocumentReadOnlyOverlay>
            </div>
          </div>
        </DocumentLockWrapper>

        <FormFooter 
          onCancel={() => router.push(`/transfers`)}
          isSaving={false}
          isLocked={isLocked}
          isDirty={false}
          isValid={true}
          actions={
            <PermissionGate action="post" resource="transfer">
              <div className="flex items-center gap-3">
                {transferStatus === TRANSFER_STATUS.DRAFT && (
                  <ActionGuard documentType="TRANSFER" status={transferStatus} action="SHIP" role={user?.role || 'WH_KEEPER'}>
                    <div title={isEitherLocked ? tCommon('warehouse_locked') : undefined}>
                      <Link href={`/transfers/${id}/ship`}>
                        <Button
                          disabled={isEitherLocked}
                          className="bg-cyan-600 hover:bg-cyan-500 text-white rounded-xl h-14 px-10 text-label-xs font-semibold uppercase transition-all shadow-lg shadow-cyan-900/20"
                        >
                          <Truck className="w-5 h-5 me-2" />
                          {t('ship')}
                        </Button>
                      </Link>
                    </div>
                  </ActionGuard>
                )}

                {transferStatus === TRANSFER_STATUS.IN_TRANSIT && (
                  <ActionGuard documentType="TRANSFER" status={transferStatus} action="RECEIVE" role={user?.role || 'WH_KEEPER'}>
                    <div title={isEitherLocked ? tCommon('warehouse_locked') : undefined}>
                      <Link href={`/transfers/${id}/receive`}>
                        <Button
                          disabled={isEitherLocked}
                          className="bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl h-14 px-10 text-label-xs font-semibold uppercase transition-all shadow-lg shadow-emerald-900/20"
                        >
                          <PackageCheck className="w-5 h-5 me-2" />
                          {t('confirm_receipt')}
                        </Button>
                      </Link>
                    </div>
                  </ActionGuard>
                )}
              </div>
            </PermissionGate>
          }
        />
      </form>
    </div>
  );
}

'use client';

import { useTranslations, useLocale } from 'next-intl';
import { useRouter } from '@/i18n/navigation';
import { PageHeader } from '@/components/shared/PageHeader';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { Button } from '@/components/ui/button';
import { StatusBadge, type BadgeStatus } from '@/components/shared/StatusBadge';
import { DocumentLineItemTable } from '@/components/shared/DocumentLineItemTable/DocumentLineItemTable';
import { Truck, PackageCheck, Printer, ArrowLeft } from 'lucide-react';
import { format } from 'date-fns';
import { TransferLine } from '@/features/operations/hooks/useTransfer';
import { TRANSFER_STATUS } from '@/contracts/statuses';
import type { Transfer } from '@/types/documents';

interface TransferViewerProps {
  transfer: Transfer;
}

export function TransferViewer({ transfer }: TransferViewerProps) {
  const locale = useLocale();
  const t = useTranslations('operations.transfer');
  const tCommon = useTranslations('common');
  const router = useRouter();

  const transferStatus = transfer?.transfer_status ?? TRANSFER_STATUS.DRAFT;

  return (
    <div className="p-8 max-w-[1600px] mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <div className="flex items-center justify-between">
        <Breadcrumb 
          items={[
            { label: tCommon('modules.operations'), href: `/transfers` },
            { label: t('title'), href: `/transfers` },
            { label: t('detail_title') }
          ]} 
        />
        <Button
          variant="ghost"
          onClick={() => router.back()}
          className="text-label-xs font-semibold uppercase text-muted-foreground hover:text-foreground transition-colors"
        >
          <ArrowLeft className="w-3 h-3 me-2" />
          {tCommon('back')}
        </Button>
      </div>

      <PageHeader
        title={t('detail_title')}
        description={
          <div className="flex items-center gap-2">
            <span>{tCommon('doc_number')}</span>
            <span dir="ltr" className="font-mono text-cyan-500/80">{transfer?.document_number}</span>
          </div>
        }
        actions={
          <div className="flex gap-4 items-center">
            <StatusBadge status={transferStatus as BadgeStatus} />
            
            <Button
              variant="outline"
              className="bg-surface-container-high border-white/5 rounded-xl h-11 px-6 text-label-xs font-semibold uppercase transition-all hover:bg-surface-container-highest"
              onClick={() => window.print()}
            >
              <Printer className="w-4 h-4 me-2" />
              {tCommon('print')}
            </Button>
          </div>
        }
      />

      <div className="grid grid-cols-1 md:grid-cols-4 gap-8 bg-surface-container-low/50 p-8 rounded-2xl border border-white/5 relative overflow-hidden shadow-2xl">
        <div className="absolute top-0 inset-x-0 h-1 bg-gradient-to-e from-cyan-500/50 via-cyan-500/20 to-transparent" />

        <div className="space-y-2">
          <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{t('from_warehouse')}</label>
          <div className="bg-surface-container-highest/40 border border-white/5 rounded-xl p-4 font-bold text-body-md">
            {transfer?.from_warehouse_name}
          </div>
        </div>

        <div className="space-y-2">
          <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{t('to_warehouse')}</label>
          <div className="bg-surface-container-highest/40 border border-white/5 rounded-xl p-4 font-bold text-body-md">
            {transfer?.to_warehouse_name}
          </div>
        </div>

        {transfer?.shipped_at && (
          <div className="space-y-2">
            <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{t('shipped_at')}</label>
            <div className="bg-surface-container-highest/30 border border-white/5 rounded-xl p-4 flex items-center justify-between">
              <span dir="ltr" className="font-mono text-body-md font-bold text-cyan-500/80">
                {format(new Date(transfer.shipped_at), 'MMM dd, yyyy HH:mm')}
              </span>
              <Truck className="w-4 h-4 text-cyan-500/40" />
            </div>
          </div>
        )}

        {transfer?.received_at && (
          <div className="space-y-2">
            <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{t('received_at')}</label>
            <div className="bg-surface-container-highest/30 border border-white/5 rounded-xl p-4 flex items-center justify-between">
              <span dir="ltr" className="font-mono text-body-md font-bold text-emerald-500/80">
                {format(new Date(transfer.received_at), 'MMM dd, yyyy HH:mm')}
              </span>
              <PackageCheck className="w-4 h-4 text-emerald-500/40" />
            </div>
          </div>
        )}

        <div className="col-span-1 md:col-span-4 space-y-2">
          <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{tCommon('notes')}</label>
          <div className="bg-surface-container-highest/40 border border-white/5 rounded-xl p-4 font-medium text-body-md min-h-[60px]">
            {transfer?.notes || '—'}
          </div>
        </div>

        {transfer?.variance_reason && (
          <div className="col-span-1 md:col-span-4 space-y-2">
            <label className="text-label-xs font-semibold uppercase text-status-warning/80 ms-1">{t('variance_reason')}</label>
            <div className="bg-status-warning/5 border border-status-warning/20 rounded-xl p-4 font-medium text-body-md">
              {transfer.variance_reason}
            </div>
          </div>
        )}
      </div>

      <div className="bg-surface-container-low/30 rounded-2xl border border-white/5 overflow-hidden shadow-2xl">
        <DocumentLineItemTable
          lines={transfer?.lines ?? []}
          isReadOnly={true}
          onRemoveLine={() => {}}
          hideLotColumns={true}
          headers={{
            code: tCommon('table_headers.code'),
            name: tCommon('table_headers.name'),
            qty: t('transfer_qty'),
            uom: tCommon('table_headers.uom'),
          }}
          extraColumns={[
            {
              header: t('shipped_qty'),
              cell: (line: TransferLine) => (
                <div className="flex justify-center">
                  <span dir="ltr" className="font-mono text-body-md font-semibold bg-surface-container-highest px-3 py-1 rounded-lg border border-white/5">
                    {line.shipped_qty ?? line.qty}
                  </span>
                </div>
              ),
            },
            {
              header: t('received_qty'),
              cell: (line: TransferLine) => (
                <div className="flex justify-center">
                  <span dir="ltr" className={`font-mono text-body-md font-semibold px-3 py-1 rounded-lg border border-white/5 ${line.received_qty ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 'bg-surface-container-highest text-muted-foreground/40'}`}>
                    {line.received_qty ?? '—'}
                  </span>
                </div>
              ),
            },
          ]}
        />
      </div>
    </div>
  );
}

'use client';
import { z } from 'zod';
import { useQuery } from '@tanstack/react-query';
import { apiClient } from '@/lib/api/client';


import { AdjustmentStatus, ALL_STATUSES } from '@/contracts/statuses';

export const AdjustmentStatusSchema = z.enum(ALL_STATUSES);


export const AdjustmentLineSchema = z.object({
 id: z.string(),
 item: z.object({
 id: z.string(),
 code: z.string(),
 name_ar: z.string(),
 name_en: z.string(),
 primary_uom: z.object({
 id: z.string(),
 code: z.string(),
 }),
 }),
 direction: z.enum(['INCREASE', 'DECREASE']),
 qty_before: z.number(),
 qty_adjusted: z.number(),
 uom_id: z.string(),
 reason_notes: z.string().optional(),
});

export const AdjustmentDetailSchema = z.object({
 id: z.string(),
 document_number: z.string(),
 status: AdjustmentStatusSchema,
 warehouse_id: z.string(),
 reason: z.string(),
 notes: z.string().nullable().optional(),
 reject: z.string().nullable().optional(),
 movement_id: z.string().nullable().optional(),
 approved_by: z.string().nullable().optional(),
 posted_at: z.string().nullable().optional(),
 created_at: z.string().optional(),
 version: z.number().optional(),
 lines: z.array(AdjustmentLineSchema),
 timeline: z.array(z.object({
 status: z.string(),
 at: z.string(),
 by: z.string(),
 })).optional(),
});


export type AdjustmentDetail = z.infer<typeof AdjustmentDetailSchema>;
export type AdjustmentLine = z.infer<typeof AdjustmentLineSchema>;

export function useAdjustment(id: string | null) {
  return useQuery({
    queryKey: ['adjustment', id],
    queryFn: ({ signal }) => apiClient.get(`/operations/adjustments/${id}`, AdjustmentDetailSchema, signal),
    enabled: !!id,
    staleTime: 60_000,
  });
}

