  lines: z.array(z.object({
    id: z.string().optional(),
    item_id: z.string(),
    qty: z.number().positive(),
    uom_id: z.string(),
    direction: z.enum(['INCREASE', 'DECREASE']),
    lot_allocations: z.array(LotAllocationSchema).optional()
  })).optional()
});

export type UpdateAdjustmentPayload = z.infer<typeof UpdateAdjustmentPayloadSchema>;

export function useUpdateAdjustment(options?: { onConflict?: () => void }) {
  const queryClient = useQueryClient();
  return useSafeMutation({
    onConflict: options?.onConflict,
    mutationFn: ({ id, payload, signal }: { id: string; payload: UpdateAdjustmentPayload; signal?: AbortSignal }) => 
      apiClient.put(`/operations/adjustments/${id}`, AdjustmentDetailSchema, UpdateAdjustmentPayloadSchema.parse(payload), signal),
    onSuccess: (data) => {
      queryClient.setQueryData(['adjustment', data.id], data);
      queryClient.invalidateQueries({ queryKey: ['adjustments'] });
    },
    onError: (error) => {
      console.error('[useUpdateAdjustment] Failed to update adjustment:', error);
    }
  });
}

'use client';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useSafeMutation } from '@/core/concurrency/useSafeMutation';
import { apiClient } from '@/lib/api/client';
import { z } from 'zod';

const CountSchema = z.object({
  id: z.string(),
  session_id: z.string(),
  item_id: z.string(),
  item: z.object({ id: z.string(), code: z.string(), name_ar: z.string(), name_en: z.string() }),
  lot_id: z.string().nullable(),
  snapshot_qty: z.number(),
  counted_qty: z.number().nullable(),
  variance: z.number().nullable(),
  variance_reason: z.string().nullable(),
});

export function useUpdateCount(sessionId: string, options?: { onConflict?: () => void }) {
  const qc = useQueryClient();
  return useSafeMutation({
    onConflict: options?.onConflict,
    mutationFn: ({ countId, counted_qty, variance_reason, version }: { countId: string; counted_qty: number; variance_reason?: string; version: number }) =>
      apiClient.put(`/stocktake/sessions/${sessionId}/counts/${countId}`, CountSchema, { counted_qty, variance_reason, version }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['stocktake-session', sessionId] });
    },
    onError: (error) => {
      console.error('Failed to update count:', error);
    }
  });
}

'use client';

import { useState, useEffect, useMemo, useRef } from 'react';
import { useTranslations, useLocale } from 'next-intl';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';
import { useForm, Controller, useWatch, useFieldArray } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { 
  TrendingUp, 
  Wallet, 
  PackageSearch, 
  MessageSquare, 
  Send
} from 'lucide-react';
import { DocumentLockBanner, DocumentLockWrapper } from '@/components/shared/DocumentLockBanner';
import { DocumentReadOnlyOverlay } from '@/components/shared/DocumentReadOnlyOverlay';
import { FormFooter } from '@/components/shared/FormFooter';
import { ScanInput } from '@/components/shared/ScanInput/ScanInput';
import { DocumentLineItemTable } from '@/components/shared/DocumentLineItemTable/DocumentLineItemTable';
import { toast } from 'sonner';
import { ActionGuard } from '@/core/workflow/ActionGuard';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { useCurrencies } from '@/features/purchasing/hooks/useCurrencies';
import { useFXRates } from '@/features/purchasing/hooks/useFXRates';
import { apiClient } from '@/lib/api/client';
import { useAuth } from '@/providers/AuthProvider';
import { type GRNDetail, LineItemSchema } from '@/features/purchasing/hooks/useGRN';
import { isDocumentLocked, type DocumentStatus } from '@/core/workflow/document-engine';
import { GRN_STATUS } from '@/contracts/statuses';
import { useSuppliers } from '@/features/purchasing/hooks/useSuppliers';
import { useWarehouses } from '@/features/warehouses/api/useWarehouses';
import { useCreateGRN } from '@/features/purchasing/hooks/useCreateGRN';
import { useUpdateGRN } from '@/features/purchasing/hooks/useUpdateGRN';
import { useAdminSettings } from '@/features/admin/hooks/useAdminSettings';
import { formatCurrency } from '@/utils/currency';

const grnFormSchema = z.object({
  supplier_id: z.string().min(1, 'Required'),
  currency_id: z.string().min(1, 'Required'),
  warehouse_id: z.string().min(1, 'Required'),
  notes: z.string().optional(),
  lines: z.array(LineItemSchema)
});

type GRNFormValues = z.infer<typeof grnFormSchema>;
type LineItem = z.infer<typeof LineItemSchema>;

interface GRNFormProps {
  actions?: React.ReactNode;
  initialData?: GRNDetail;
  id: string;
  onConflict?: () => void;
}

export function GRNForm({ initialData, id, onConflict, actions }: GRNFormProps) {
  const t = useTranslations('procurement.grn');
  const tc = useTranslations('common');
  const locale = useLocale();
  const { user } = useAuth();
  
  const isNew = id === 'new';
  const lastResetId = useRef<string | null>(null);

  const { data: suppliers } = useSuppliers();
  const { data: warehouses } = useWarehouses();
  const { data: currencies } = useCurrencies();
  
  const createMutation = useCreateGRN({ onConflict });
  const updateMutation = useUpdateGRN(initialData?.id || '', { onConflict });

  const [scanError, setScanError] = useState('');
  
  const status = (initialData?.status || GRN_STATUS.DRAFT) as DocumentStatus;
  const isLocked = isDocumentLocked('GRN', status);

  const { handleSubmit, reset, control, register, getValues, formState: { errors, isDirty } } = useForm<GRNFormValues>({
    resolver: zodResolver(grnFormSchema),
    defaultValues: {
      supplier_id: initialData?.supplier_id || '',
      currency_id: initialData?.currency_id || '',
      warehouse_id: initialData?.warehouse_id || 'wh-1',
      notes: initialData?.notes || '',
      lines: initialData?.lines || []
    }
  });

  const { fields, append, remove, update } = useFieldArray({
    control,
    name: "lines"
  });

  const { router } = useUnsavedChangesGuard(isDirty);

  const currencyId = useWatch({ control, name: 'currency_id' });
  const watchedLines = useWatch({ control, name: 'lines' });

  const { data: settings } = useAdminSettings();
  const baseCurrency = settings?.base_currency;
  const { data: fxRates } = useFXRates(currencyId, baseCurrency);
  const currentFxRate = fxRates?.[0]?.rate || 1;

  const totalForeign = useMemo(() => {
    return (watchedLines || []).reduce((acc, line) => acc + (line.received_qty * (line.unit_cost_foreign || 0)), 0);
  }, [watchedLines]);

  useEffect(() => {
    if (initialData && initialData.id !== lastResetId.current) {
      lastResetId.current = initialData.id;
      reset({
        supplier_id: initialData.supplier_id || '',
        currency_id: initialData.currency_id || '',
        warehouse_id: initialData.warehouse_id || 'wh-1',
        notes: initialData.notes || '',
        lines: initialData.lines || []
      }, { 
        keepDirty: false,
        keepTouched: false
      });
    }
  }, [initialData, reset]);


  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    return () => {
      abortControllerRef.current?.abort();
    };
  }, []);

  const handleScan = async (barcode: string) => {
    try {
      setScanError('');
      
      // Abort any existing scan request
      abortControllerRef.current?.abort();
      abortControllerRef.current = new AbortController();

      const ItemSchema = z.object({
        data: z.array(z.object({
          id: z.string(), code: z.string(), name_ar: z.string(), name_en: z.string(),
          primary_uom: z.object({ id: z.string(), code: z.string() })
        }))
      });
      const res = await apiClient.get(`/master-data/items?barcode=${barcode}`, ItemSchema, abortControllerRef.current.signal);
      
      if (res.data && res.data.length > 0) {
        const item = res.data[0];
        const currentLines = getValues("lines") || [];
        const index = currentLines.findIndex(l => l.item.id === item.id);

        if (index >= 0) {
          const existing = currentLines[index];
          update(index, { 
            ...existing, 
            qty: existing.qty + 1, 
            received_qty: existing.received_qty + 1 
          });
        } else {
          append({
            id: `new-${Date.now()}`,
            item: item,
            lot: null,
            qty: 1,
            received_qty: 1,
            uom_id: item.primary_uom.id,
            unit_cost_foreign: 0,
            unit_cost_base: 0
          });
        }
      } else {
        setScanError(t('no_item_found'));
      }
    } catch (err: any) {
      if (err.name === 'AbortError') return;
      setScanError(t('no_item_found'));
    }
  };

  const handleLotClick = (_line: LineItem) => {
    toast.info("Standardized lot allocation pending");
  };
  

  const workflowActions = (
    <div className="flex items-center gap-3">
      <ActionGuard documentType="GRN" status={status} action="POST" role={user?.role || 'WH_KEEPER'}>
        <PermissionGate action="post" resource="grn">
          <Button 
            onClick={() => router.push(`/goods-received/${id}/post`)}
            className="h-12 px-8 bg-operational-cyan hover:brightness-110 text-white text-label-xs font-semibold uppercase shadow-xl shadow-operational-cyan/20 transition-all rounded-xl"
          >
            <Send className="w-4 h-4 me-2" />
            {t('post_grn')}
          </Button>
        </PermissionGate>
      </ActionGuard>
    </div>
  );

  const isPending = createMutation.isPending || updateMutation.isPending;

  const onSubmit = async (values: GRNFormValues) => {
    if (!currencies || currencies.length === 0) {
      toast.error(t('errors.no_currencies_available'));
      return;
    }
    try {
      const payload = {
        ...values,
        lines: values.lines.map(l => ({
          id: l.id.startsWith('new-') ? undefined : l.id,
          item_id: l.item.id,
          lot_id: l.lot?.id || null,
          qty: l.received_qty,
          received_qty: l.received_qty,
          uom_id: l.uom_id,
          unit_cost_foreign: l.unit_cost_foreign || 0,
        }))
      };

      if (isNew) {
        const result = await createMutation.mutateAsync(payload);
        toast.success(t('create_success'));
        router.push(`/goods-received/${result.id}`, { skipGuard: true });
      } else if (initialData) {
        await updateMutation.mutateAsync({
          ...payload,
          version: initialData.version
        });
        toast.success(t('update_success'));
      }
    } catch (error) {
      console.error('[GRNForm] Submit Error:', error);
      const isConflict = error && typeof error === 'object' && 'name' in error && error.name === 'ConflictError';
      if (!isConflict) {
        toast.error(tc('error_occurred'));
      }
    }
  };

  return (
    <div className="flex flex-col min-h-screen bg-surface-container-low pb-32">
      <DocumentLockBanner status={status} isLocked={isLocked} />
      
      <form onSubmit={handleSubmit(onSubmit)} className="flex-1 w-full max-w-[1400px] mx-auto p-4 md:p-8 space-y-8">
        <div className="flex items-center justify-between px-2">
          <div className="flex flex-col">
            <h1 className="text-headline-lg font-semibold uppercase italic text-foreground flex items-center gap-4">
              {isNew ? t('create_new') : `#${initialData?.document_number}`}
            </h1>
            <p className="text-label-xs font-semibold uppercase text-primary/40 mt-1">
              {isNew ? t('new_manifest_sub') : t('detail_sub')}
            </p>
          </div>
        </div>

        <DocumentLockWrapper isLocked={isLocked}>
          <DocumentReadOnlyOverlay isPosted={isLocked}>
            <div className="space-y-10">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <div className="bg-surface-container-lowest p-6 rounded-lg shadow-sm flex flex-col gap-1 group relative overflow-hidden border border-surface-variant/5">
            <Label htmlFor="supplier-select" className="text-label-xs font-semibold uppercase text-primary/30 group-hover:text-primary transition-colors">{tc('supplier')}</Label>
            <Controller
              name="supplier_id"
              control={control}
              render={({ field }) => (
                <Select onValueChange={field.onChange} value={field.value}>
                  <SelectTrigger className="mt-2 h-12 bg-surface-container-low border-none rounded-lg px-4 font-semibold uppercase text-foreground shadow-none focus:ring-1 focus:ring-primary-fixed-dim/10 transition-all">
                    <SelectValue placeholder={tc('select_supplier')} />
                  </SelectTrigger>
                  <SelectContent className="bg-surface-container-highest border-none rounded-lg shadow-2xl">
                    {suppliers?.map(s => (
                      <SelectItem key={s.id} value={s.id} className="text-label-sm font-bold focus:bg-primary/10 focus:text-primary">
                        {locale === 'ar' ? s.name_ar : s.name_en} ({s.code})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            />
            {errors.supplier_id && <span className="text-label-xs text-destructive mt-1 font-bold">{errors.supplier_id.message}</span>}
          </div>

          <div className="bg-surface-container-lowest p-6 rounded-lg shadow-sm flex flex-col gap-1 group relative overflow-hidden border border-surface-variant/5">
            <div className="absolute top-0 end-0 p-4 opacity-[0.02] group-hover:opacity-[0.05] transition-opacity">
              <Wallet className="w-12 h-12" />
            </div>
            <Label htmlFor="currency-select" className="text-label-xs font-semibold uppercase text-primary/30 group-hover:text-primary transition-colors">{tc('order_currency')}</Label>
            <Controller
              name="currency_id"
              control={control}
              render={({ field }) => (
                <Select onValueChange={field.onChange} value={field.value}>
                  <SelectTrigger className="mt-2 h-12 bg-surface-container-low border-none rounded-lg px-4 font-semibold font-mono text-foreground shadow-none focus:ring-1 focus:ring-primary-fixed-dim/10 transition-all">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="bg-surface-container-highest border-none rounded-lg shadow-2xl">
                    {currencies?.map(c => (
                      <SelectItem key={c.id} value={c.code} className="text-label-sm font-bold focus:bg-primary/10 focus:text-primary font-mono">
                        {c.code} — {locale === 'ar' ? c.name_ar : c.name_en}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            />
            {errors.currency_id && <span className="text-label-xs text-destructive mt-1 font-bold">{errors.currency_id.message}</span>}
          </div>

          <div className="bg-surface-container-lowest p-6 rounded-lg shadow-sm flex flex-col gap-1 group relative overflow-hidden border border-surface-variant/5">
            <div className="absolute top-0 end-0 p-4 opacity-[0.02] group-hover:opacity-[0.05] transition-opacity">
              <PackageSearch className="w-12 h-12" />
            </div>
            <p className="text-label-xs font-semibold uppercase text-primary/30 group-hover:text-primary transition-colors">{tc('ref_document')}</p>
            <div className="mt-2">
              {initialData?.po_number ? (
                <Badge variant="outline" className="h-8 px-4 bg-primary/5 text-primary border-primary/20 text-label-xs font-semibold uppercase rounded-lg">
                  <span dir="ltr" className="font-mono">{initialData.po_number}</span>
                </Badge>
              ) : (
                <p className="font-semibold text-title-sm text-primary/10 italic uppercase">{t('direct_receipt')}</p>
              )}
            </div>
          </div>

          <div className="bg-surface-container-lowest p-6 rounded-lg shadow-sm flex flex-col gap-1 group relative overflow-hidden border border-surface-variant/5">
            <Label htmlFor="warehouse-select" className="text-label-xs font-semibold uppercase text-primary/30 group-hover:text-primary transition-colors">{tc('warehouse')}</Label>
            <Controller
              name="warehouse_id"
              control={control}
              render={({ field }) => (
                <Select onValueChange={field.onChange} value={field.value}>
                  <SelectTrigger className="mt-2 h-12 bg-surface-container-low border-none rounded-lg px-4 font-semibold uppercase text-foreground shadow-none focus:ring-1 focus:ring-primary-fixed-dim/10 transition-all">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="bg-surface-container-highest border-none rounded-lg shadow-2xl">
                    {warehouses?.map(w => (
                      <SelectItem key={w.id} value={w.id} className="text-label-sm font-bold focus:bg-primary/10 focus:text-primary">
                        {locale === 'ar' ? w.nameAr : w.nameEn}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            />
            {errors.warehouse_id && <span className="text-label-xs text-destructive mt-1 font-bold">{errors.warehouse_id.message}</span>}
          </div>

            <div className="col-span-full bg-surface-container-lowest p-6 rounded-lg shadow-sm flex flex-col gap-1 group relative overflow-hidden border border-surface-variant/5">
              <div className="absolute top-0 end-0 p-4 opacity-[0.02] group-hover:opacity-[0.05] transition-opacity">
                <MessageSquare className="w-12 h-12" />
              </div>
              <Label htmlFor="notes-area" className="text-label-xs font-semibold uppercase text-primary/30 group-hover:text-primary transition-colors">{tc('notes')}</Label>
              <Textarea 
                id="notes-area"
                {...register('notes')}
                disabled={isLocked}
                className="mt-2 w-full bg-surface-container-low border-none rounded-lg p-4 focus-visible:ring-1 focus-visible:ring-primary-fixed-dim/10 outline-none transition-all text-body-md font-medium min-h-[100px] resize-none text-foreground shadow-none" 
                placeholder={tc('notes_placeholder')} 
              />
            </div>
          </div>

          <div className="space-y-6">
            <ScanInput 
              onScan={handleScan} 
              placeholder={t('scan_placeholder')} 
              onError={(bc) => setScanError(t('no_item_found') + ': ' + bc)}
              className="bg-surface-container-lowest rounded-lg transition-all focus-within:ring-1 focus-within:ring-primary-fixed-dim/10 shadow-sm border border-surface-variant/5"
            />
            {scanError && <div dir="ltr" className="text-destructive text-label-xs font-semibold uppercase ps-2">{scanError}</div>}
            
            <div className="bg-surface-container-lowest rounded-lg overflow-hidden shadow-sm border border-surface-variant/5">
              <DocumentLineItemTable<LineItem> 
                lines={fields as unknown as LineItem[]} 
                isReadOnly={isLocked}
                onRemoveLine={(id) => {
                  const idx = fields.findIndex(f => f.id === id);
                  if (idx >= 0) remove(idx);
                }}
                extraColumns={[
                  {
                    header: tc('table_headers.received_qty'),
                    cell: (field: LineItem) => {
                      const index = fields.findIndex(f => f.id === field.id);
                      return (
                        <input type="number" 
                          dir="ltr"
                          className="w-20 bg-surface-container-low rounded-lg text-center px-2 py-1.5 font-mono text-body-md focus:ring-1 focus:ring-primary-fixed-dim/10 outline-none transition-all"
                          {...register(`lines.${index}.received_qty` as const, { valueAsNumber: true })}
                          onChange={e => {
                            const val = Number(e.target.value);
                            update(index, { ...fields[index], received_qty: val, qty: val } as LineItem);
                          }}
                        />
                      );
                    }
                  },
                  {
                    header: tc('table_headers.lot_allocation'),
                    cell: (field: LineItem) => (
                      <button 
                        type="button" 
                        className="text-primary underline underline-offset-4 decoration-dotted decoration-primary/40 hover:decoration-primary text-label-xs font-semibold uppercase transition-all"
                        onClick={() => handleLotClick(field)}
                      >
                        {field.lot ? (
                          <span dir="ltr" className="font-mono">{field.lot.lot_number}</span>
                        ) : t('allocate_lot')}
                      </button>
                    )
                  }
                ]}
              />
            </div>
            </div>
          </div>
        </DocumentReadOnlyOverlay>

        <div className="flex flex-col md:flex-row justify-end items-start md:items-center gap-8 pt-10">
          <div className="flex flex-col items-end gap-1 px-6 border-e border-surface-container-high/20">
            <p className="text-label-xs font-semibold uppercase text-muted-foreground/50">
              {t('market_index_ref')}
            </p>
            <div className="flex items-center gap-2 text-primary">
              <TrendingUp className="w-3 h-3" />
              <p dir="ltr" className="text-label-sm font-mono font-semibold">
                1 {currencyId} = {currentFxRate} {baseCurrency}
              </p>
            </div>
          </div>

            <div className="bg-surface-container-lowest p-8 rounded-lg shadow-xl relative overflow-hidden min-w-[340px] group transition-all hover:shadow-2xl border border-surface-variant/5">
              <div className="absolute top-0 end-0 w-1 h-full bg-primary/20 shadow-[0_0_20px_rgba(var(--primary-rgb),0.3)] group-hover:bg-primary transition-all" />
              
              <div className="space-y-6 relative z-10">
                <div className="flex justify-between items-baseline gap-10">
                  <p className="text-label-xs font-semibold uppercase text-primary/30 group-hover:text-primary transition-colors">{t('receipt_total', { currency: currencyId || '' })}</p>
                  <p dir="ltr" className="text-headline-lg font-display font-semibold text-foreground">
                    {formatCurrency(totalForeign, currencyId, locale as 'ar' | 'en')}
                  </p>
                </div>
                
                <div className="h-px bg-surface-container-high/20 w-full" />
                
                <div className="flex justify-between items-center gap-10">
                  <p className="text-label-xs font-semibold uppercase text-primary/20">{t('base_value', { currency: baseCurrency || '' })}</p>
                  <p dir="ltr" className="text-title-lg font-mono font-semibold text-primary/60">
                    {formatCurrency(totalForeign * currentFxRate, baseCurrency, locale as 'ar' | 'en')}
                  </p>
                </div>
              </div>
            </div>
          </div>
        </DocumentLockWrapper>

        <FormFooter 
          isLocked={isLocked}
          onCancel={() => router.push('/goods-received', { skipGuard: !isDirty })}
          actions={actions || workflowActions}
          onSubmit={handleSubmit(onSubmit)}
          isPending={isPending}
          submitLabel={isNew ? t('actions.submit') : tc('save')}
        />
      </form>

    </div>
  );
}

'use client';

import * as React from 'react';
import { useForm, useFieldArray } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { 
  Trash2, 
  Plus, 
  Calendar, 
  Package, 
  Calculator, 
  ArrowLeft, 
  Send, 
  Save, 
  Building2,
  ShieldCheck,
  Edit3,
  ArrowRight,
  History
} from 'lucide-react';
import { useTranslations, useLocale } from 'next-intl';
import { toast } from 'sonner';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';

import {
 Form,
 FormControl,
 FormField,
 FormItem,
 FormLabel,
 FormMessage,
} from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { PostConfirmDialog } from '@/components/shared/PostConfirmDialog';
import { useCreatePR } from '@/features/purchasing/hooks/useCreatePR';
import { useUpdatePR } from '@/features/purchasing/hooks/useUpdatePR';
import { useSubmitPR } from '@/features/purchasing/hooks/useSubmitPR';
import { PRDetail } from '@/features/purchasing/hooks/usePR';
import { useMasterDataList } from '@/features/master-data/hooks/useMasterDataCRUD';
import { ScanInput } from '@/components/shared/ScanInput/ScanInput';
import { Item, Warehouse, ItemSchema, WarehouseSchema } from '@/types/master-data';
import { isDocumentLocked, type DocumentStatus } from '@/core/workflow/document-engine';
import { PR_STATUS } from '@/contracts/statuses';
import { DocumentLockBanner, DocumentLockWrapper } from '@/components/shared/DocumentLockBanner';
import { FormFooter } from '@/components/shared/FormFooter';
import { ActionGuard } from '@/core/workflow/ActionGuard';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { useAuth } from '@/providers/AuthProvider';
import { cn } from '@/lib/utils';
import { Badge } from '@/components/ui/badge';

const lineItemSchema = z.object({
 id: z.string().optional(), // For existing lines
 item_id: z.string().min(1),
 item_name: z.string().optional(),
 item_code: z.string().optional(),
 req_qty: z.number().min(0.01),
 uom_id: z.string().min(1),
});

const formSchema = z.object({
 department_id: z.string().min(1),
 expected_date: z.string().min(1),
 notes: z.string().optional(),
 lines: z.array(lineItemSchema).min(1),
});

type PurchaseRequestFormValues = z.infer<typeof formSchema>;

interface PurchaseRequestFormProps {
  initialData?: PRDetail;
  onConflict?: () => void;
}

export function PurchaseRequestForm({ initialData, onConflict }: PurchaseRequestFormProps) {
  const locale = useLocale();
  const t = useTranslations('procurement.pr');
  const tc = useTranslations('common');
  const { user } = useAuth();
  const [isSubmitting, setIsSubmitting] = React.useState(false);
  const [submitConfirmOpen, setSubmitConfirmOpen] = React.useState(false);
  const [pendingValues, setPendingValues] = React.useState<PurchaseRequestFormValues | null>(null);

  const status = initialData?.status as DocumentStatus;
  const isLocked = isDocumentLocked('PR', status);

  // Mocks/Hooks for data selection
  const { data: warehouses } = useMasterDataList('warehouses', WarehouseSchema);
  const { data: itemsData } = useMasterDataList('items', ItemSchema);

  const createPR = useCreatePR();
  const updatePR = useUpdatePR({ onConflict });
  const submitPR = useSubmitPR({ onConflict });

  const form = useForm<PurchaseRequestFormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: initialData ? {
      department_id: initialData.department_id,
      expected_date: initialData.expected_date.split('T')[0],
      notes: initialData.notes || '',
      lines: initialData.lines.map(l => ({
        id: l.id,
        item_id: l.item.id,
        item_name: locale === 'ar' ? l.item.name_ar : l.item.name_en,
        item_code: l.item.code,
        req_qty: l.req_qty,
        uom_id: l.uom_id,
      })),
    } : {
      department_id: '',
      expected_date: '',
      notes: '',
      lines: [],
    },
  });

  const { router } = useUnsavedChangesGuard(form.formState.isDirty);


  const { fields, append, remove } = useFieldArray({
    control: form.control,
    name: 'lines',
  });

  const handleScan = (barcode: string) => {
    const item = itemsData?.data?.find((i: Item) => i.barcode === barcode || i.code === barcode);
    if (item) {
      append({
        item_id: item.id,
        item_name: locale === 'ar' ? item.name_ar : item.name_en,
        item_code: item.code,
        req_qty: 1,
        uom_id: item.primary_uom?.id || 'EA',
      });
      toast.success(tc('items') + ': ' + (locale === 'ar' ? item.name_ar : item.name_en));
    } else {
      toast.error(tc('not_found'));
    }
  };

  const onSave = async (values: PurchaseRequestFormValues, submitAfterSave = false) => {
    setIsSubmitting(true);
    try {
      let prId = initialData?.id;
      
      if (prId) {
        await updatePR.mutateAsync({ 
          id: prId, 
          payload: { ...values, version: initialData?.version ?? 0 } 
        });
      } else {
        const res = await createPR.mutateAsync(values);
        prId = res.id;
      }

      if (submitAfterSave && prId) {
        const currentVersion = initialData ? ((initialData.version ?? 0) + 1) : 1;
        await submitPR.mutateAsync({ id: prId, version: currentVersion });
        toast.success(t('submit_success'));
      } else {
        toast.success(tc('save') + ' ' + tc('completed'));
      }

      router.push('/purchase-requests', { skipGuard: true });
    } catch (error) {
      console.error(error);
      toast.error(tc('error'));
    } finally {
      setIsSubmitting(false);
      setSubmitConfirmOpen(false);
    }
  };

  const handleSubmitClick = (values: PurchaseRequestFormValues) => {
    setPendingValues(values);
    setSubmitConfirmOpen(true);
  };

  const workflowActions = (
    <div className="flex items-center gap-3">
      {/* Standard Submit Button for Drafts */}
      {!isLocked && (
        <>
          <Button
            type="button"
            variant="outline"
            disabled={isSubmitting}
            onClick={form.handleSubmit((v) => onSave(v, false))}
            className="h-12 px-8 border-none bg-surface-container-low text-foreground text-label-xs font-semibold uppercase rounded-xl hover:bg-surface-container-high/50 active:scale-95 transition-all shadow-xl shadow-black/5"
          >
            <Save className="w-3.5 h-3.5 me-2" />
            {tc('save')}
          </Button>
          <Button
            type="button"
            disabled={isSubmitting}
            onClick={form.handleSubmit(handleSubmitClick)}
            className="h-12 px-10 bg-operational-cyan hover:brightness-110 text-primary-foreground text-label-xs font-semibold uppercase rounded-xl transition-all active:scale-95 shadow-xl shadow-operational-cyan/20"
          >
            {isSubmitting ? tc('saving') : (
              <>
                <Send className="w-3.5 h-3.5 me-2" />
                {t('submit')}
              </>
            )}
          </Button>
        </>
      )}

      {/* Workflow Actions for Locked Documents */}
      {isLocked && (
        <>
          <ActionGuard documentType="PR" status={status} action="EDIT" role={user?.role || 'WH_KEEPER'}>
            <PermissionGate action="update" resource="pr">
              <Button
                onClick={() => router.push(`/purchase-requests/${initialData?.id}/edit`)}
                variant="outline"
                className="h-12 px-8 border-none bg-surface-container-low text-operational-cyan text-label-xs font-semibold uppercase rounded-xl hover:bg-operational-cyan/5 transition-all shadow-xl shadow-black/5"
              >
                <Edit3 className="w-4 h-4 me-2 opacity-60" />
                {tc('edit')}
              </Button>
            </PermissionGate>
          </ActionGuard>

          <ActionGuard documentType="PR" status={status} action="APPROVE" role={user?.role || 'WH_KEEPER'}>
            <PermissionGate action="approve" resource="pr">
              <Button
                onClick={() => router.push(`/purchase-requests/${initialData?.id}/approve`)}
                className="h-12 px-10 bg-operational-cyan hover:bg-operational-cyan/90 text-primary-foreground text-label-xs font-semibold uppercase shadow-xl shadow-operational-cyan/20 rounded-xl transition-all active:scale-95"
              >
                <ShieldCheck className="w-4 h-4 me-2" />
                {t('go_to_approval')}
              </Button>
            </PermissionGate>
          </ActionGuard>

          <ActionGuard documentType="PR" status={status} action="CONVERT_TO_PO" role={user?.role || 'WH_KEEPER'}>
            <PermissionGate action="create" resource="po">
              <Button
                onClick={() => router.push(`/purchase-orders/new?pr_id=${initialData?.id}`)}
                className="primary-gradient h-12 px-10 text-white text-label-xs font-semibold uppercase rounded-xl transition-all active:scale-95 border-none shadow-xl shadow-primary/20"
              >
                <ArrowRight className="w-4 h-4 me-2 rtl:rotate-180" />
                {t('convert_to_po')}
              </Button>
            </PermissionGate>
          </ActionGuard>
        </>
      )}
    </div>
  );

  return (
    <div className="flex flex-col min-h-screen bg-surface-container-low pb-32">
      <DocumentLockBanner status={status} isLocked={isLocked} />
      
      <Form {...form}>
        <form className="flex-1 w-full max-w-[1400px] mx-auto p-4 md:p-8 space-y-8">
          <DocumentLockWrapper isLocked={isLocked}>
            <div className="space-y-10 w-full bg-surface-container-lowest p-8 rounded-[2rem] relative transition-all duration-700">
            <div className="flex items-center justify-between">
              <div className="space-y-1">
                <h3 className="text-title-lg font-semibold text-operational-cyan uppercase flex items-center gap-3">
                  {t('detail_title')}
                  {isLocked && <Badge variant="outline" className="bg-surface-container-high/50 border-none text-muted-foreground/60"><History className="w-3 h-3 me-1" /> {tc('read_only')}</Badge>}
                </h3>
              </div>
              {initialData?.document_number && (
                <span className="font-mono text-label-sm font-semibold text-muted-foreground/40 bg-surface-container-low px-4 py-1.5 rounded-full">
                  {initialData.document_number}
                </span>
              )}
            </div>
            
            {/* Step 1: Request Header */}
            <div className="bg-surface-container-low p-8 rounded-[2rem] relative">
              <div className="flex items-center gap-4 mb-8 pb-6 border-none">
                <div className="p-3 rounded-2xl bg-operational-cyan/10 text-operational-cyan">
                  <Building2 className="w-5 h-5" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold uppercase text-foreground">{t('new_intent')}</h3>
                  <p className="text-label-xs font-bold text-muted-foreground/60 uppercase mt-0.5">{t('specification')}</p>
                </div>
              </div>
              
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                <FormField<PurchaseRequestFormValues, 'department_id'>
                  control={form.control}
                  name="department_id"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-label-xs font-semibold uppercase text-muted-foreground/40 mb-3 flex items-center gap-2 ps-1">
                        <Package className="w-3 h-3" />
                        {t('department')}
                      </FormLabel>
                      <Select onValueChange={field.onChange} defaultValue={field.value}>
                        <FormControl>
                          <SelectTrigger className="bg-surface-container-lowest border-none h-11 rounded-xl text-label-xs font-semibold uppercase focus:ring-1 focus:ring-operational-cyan/30">
                            <SelectValue placeholder={tc('select_warehouse')} />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent className="bg-surface-container-low border-none rounded-2xl">
                          {warehouses?.data?.map((w: Warehouse) => (
                            <SelectItem key={w.id} value={w.id} className="text-label-xs font-bold">
                              {locale === 'ar' ? w.name_ar : w.name_en}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <FormMessage className="text-label-xxs font-semibold uppercase" />
                    </FormItem>
                  )}
                />

                <FormField<PurchaseRequestFormValues, 'expected_date'>
                  control={form.control}
                  name="expected_date"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-label-xs font-semibold uppercase text-muted-foreground/40 mb-3 flex items-center gap-2 ps-1">
                        <Calendar className="w-3 h-3" />
                        {t('expected_date')}
                      </FormLabel>
                      <FormControl>
                        <Input type="date" className="bg-surface-container-lowest border-none h-11 rounded-xl font-semibold text-label-xs uppercase focus-visible:ring-operational-cyan/30" {...field} />
                      </FormControl>
                      <FormMessage className="text-label-xxs font-semibold uppercase" />
                    </FormItem>
                  )}
                />

                <FormField<PurchaseRequestFormValues, 'notes'>
                  control={form.control}
                  name="notes"
                  render={({ field }) => (
                    <FormItem className="lg:col-span-3">
                      <FormLabel className="text-label-xs font-semibold uppercase text-muted-foreground/40 mb-3 ps-1">{tc('notes')}</FormLabel>
                      <FormControl>
                        <Input placeholder={tc('notes')} className="bg-surface-container-lowest border-none h-11 rounded-xl font-semibold text-label-xs uppercase focus-visible:ring-operational-cyan/30" {...field} />
                      </FormControl>
                      <FormMessage className="text-label-xxs font-semibold uppercase" />
                    </FormItem>
                  )}
                />
              </div>
            </div>

            {/* Step 2: Line Items */}
            <div className="space-y-6">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 px-2">
                <div className="flex items-center gap-4">
                  <div className="p-2.5 rounded-xl bg-status-warning/10 text-status-warning">
                    <Calculator className="w-4 h-4" />
                  </div>
                  <div>
                    <h3 className="text-label-xs font-semibold uppercase text-muted-foreground/70">{tc('items')}</h3>
                    <p className="text-label-xxs font-semibold text-muted-foreground/30 uppercase mt-0.5">{t('specification')}</p>
                  </div>
                </div>
                
                {!isLocked && (
                  <div className="flex-1 max-w-md">
                    <ScanInput 
                      onScan={handleScan}
                      placeholder={tc('select_item')}
                      className="h-12"
                    />
                  </div>
                )}

                {!isLocked && (
                  <Button 
                    type="button" 
                    variant="outline" 
                    size="sm" 
                    className="h-12 px-6 border-none text-operational-cyan bg-operational-cyan/10 hover:bg-operational-cyan hover:text-white rounded-xl text-label-xs font-semibold uppercase transition-all"
                    onClick={() => append({ item_id: '', item_name: '', item_code: '', req_qty: 1, uom_id: 'EA' })}
                  >
                    <Plus className="h-3.5 w-3.5 me-2" />
                    {tc('create')}
                  </Button>
                )}
              </div>

              <div className="grid grid-cols-1 gap-4">
                {fields.map((field, index) => (
                  <div key={field.id} className="grid grid-cols-1 lg:grid-cols-[2fr_1fr_1fr_auto] gap-6 items-end bg-surface-container-low/50 p-6 rounded-2xl group hover:bg-surface-container transition-all">
                    <FormField<PurchaseRequestFormValues, `lines.${number}.item_id`>
                      control={form.control}
                      name={`lines.${index}.item_id`}
                      render={({ field: inputField }) => (
                        <FormItem>
                          <FormLabel className="text-label-xxs font-semibold uppercase text-muted-foreground/40 mb-2">{tc('item')}</FormLabel>
                          <Select 
                            onValueChange={(val) => {
                              const item = itemsData?.data?.find((i: Item) => i.id === val);
                              form.setValue(`lines.${index}.item_id`, val as string);
                              form.setValue(`lines.${index}.item_name`, locale === 'ar' ? item?.name_ar : item?.name_en);
                              form.setValue(`lines.${index}.item_code`, item?.code);
                              form.setValue(`lines.${index}.uom_id`, item?.primary_uom?.id || 'EA');
                            }} 
                            value={inputField.value}
                            disabled={isLocked}
                          >
                            <FormControl>
                              <SelectTrigger className="bg-surface-container-low border-none h-11 rounded-xl text-label-xs font-semibold uppercase focus:ring-1 focus:ring-operational-cyan/30">
                                <SelectValue placeholder={tc('select_item')} />
                              </SelectTrigger>
                            </FormControl>
                            <SelectContent className="bg-surface-container-low border-none rounded-2xl max-h-[300px]">
                              {itemsData?.data?.map((i: Item) => (
                                <SelectItem key={i.id} value={i.id} className="text-label-xs font-bold">
                                  {i.code} - {locale === 'ar' ? i.name_ar : i.name_en}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                          <FormMessage className="text-label-xxs font-semibold" />
                        </FormItem>
                      )}
                    />

                    <FormField<PurchaseRequestFormValues, `lines.${number}.req_qty`>
                      control={form.control}
                      name={`lines.${index}.req_qty`}
                      render={({ field: inputField }) => (
                        <FormItem>
                          <FormLabel className="text-label-xxs font-semibold uppercase text-muted-foreground/40 mb-2">{t('requested_qty')}</FormLabel>
                          <FormControl>
                            <Input 
                              type="number" 
                              step="0.01"
                              className="bg-surface-container-low border-none h-11 rounded-xl font-mono font-semibold text-label-xs focus-visible:ring-operational-cyan/30" 
                              dir="ltr"
                              {...inputField} 
                              onChange={(e) => inputField.onChange(e.target.valueAsNumber || 0)}
                              disabled={isLocked}
                            />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField<PurchaseRequestFormValues, `lines.${number}.uom_id`>
                      control={form.control}
                      name={`lines.${index}.uom_id`}
                      render={({ field: inputField }) => (
                        <FormItem>
                          <FormLabel className="text-label-xxs font-semibold uppercase text-muted-foreground/40 mb-2">{tc('uom')}</FormLabel>
                          <FormControl>
                            <Input disabled className="bg-surface-container-high/10 border-none h-11 rounded-xl font-semibold text-label-xs uppercase opacity-50" {...inputField} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    {!isLocked && (
                      <Button 
                        type="button" 
                        variant="ghost" 
                        size="icon" 
                        className="w-10 h-10 rounded-xl text-muted-foreground/20 hover:text-status-error hover:bg-status-error/10 transition-all border-none"
                        onClick={() => remove(index)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    )}
                  </div>
                ))}
                {fields.length === 0 && (
                  <div className="py-12 border-2 border-dashed border-surface-variant/10 rounded-3xl flex flex-col items-center justify-center text-muted-foreground/20 italic text-label-xs font-semibold uppercase">
                    {tc('no_items')}
                  </div>
                )}
              </div>
              
              {/* Summary */}
              <div className="flex flex-col md:flex-row items-center justify-between gap-6 p-8 bg-surface-container-low rounded-[2rem]">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 rounded-2xl bg-operational-cyan/10 flex items-center justify-center">
                    <Package className="w-6 h-6 text-operational-cyan" />
                  </div>
                  <div>
                    <div className="text-label-xs font-semibold uppercase text-muted-foreground/30">{tc('items')}</div>
                    <div className="text-body-md font-semibold text-foreground">{fields.length} {tc('items')}</div>
                  </div>
                </div>
              </div>
            </div>
            </div>
          </DocumentLockWrapper>

          <FormFooter 
            isLocked={isLocked}
            onCancel={() => router.push('/purchase-requests')}
            actions={workflowActions}
            isSaving={isSubmitting}
            isDirty={form.formState.isDirty}
            isValid={form.formState.isValid}
          />

          <PostConfirmDialog
            open={submitConfirmOpen}
            onOpenChange={setSubmitConfirmOpen}
            onConfirm={() => { if (pendingValues) onSave(pendingValues, true); }}
            title={t('submit')}
            description={t('approve_confirm_desc')}
            warningText={t('irreversible')}
          />
        </form>
      </Form>
    </div>
  );
}

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useSafeMutation } from '@/core/concurrency/useSafeMutation';
import { apiClient } from '@/lib/api/client';
import { successSchema } from '@/types/api';
import { PO_STATUS } from '@/contracts/statuses';
import { PODetail } from './usePO';

export function useApprovePO(options?: { onConflict?: () => void }) {
  const queryClient = useQueryClient();

  return useSafeMutation({
    onConflict: options?.onConflict,
    mutationFn: async ({ id, version }: { id: string; version: number }) => {
      const response = await apiClient.post(`/procurement/purchase-orders/${id}/approve`, successSchema, { version });
      return response;
    },
    onSuccess: (_, { id }) => {
      // Simulate state transition in cache
      queryClient.setQueryData(['purchase-order', id], (old: PODetail | undefined) => {
        if (!old) return old;
        return { ...old, status: PO_STATUS.APPROVED };
      });
      
      queryClient.invalidateQueries({ queryKey: ['purchase-orders'] });
    },
    onError: (error) => {
      console.error('[useApprovePO] Failed to approve PO:', error);
    },
  });
}

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useSafeMutation } from '@/core/concurrency/useSafeMutation';
import { apiClient } from '@/lib/api/client';
import { successSchema } from '@/types/api';
import { PR_STATUS } from '@/contracts/statuses';
import { PRDetail } from './usePR';

export function useApprovePR(options?: { onConflict?: () => void }) {
  const queryClient = useQueryClient();
  return useSafeMutation({
    onConflict: options?.onConflict,
    mutationFn: ({ id, version, signal }: { id: string; version: number; signal?: AbortSignal }) => 
      apiClient.post(`/procurement/purchase-requests/${id}/approve`, successSchema, { version }, signal),
    onSuccess: (_, { id }) => {
      // Simulate state transition in cache
      queryClient.setQueryData(['purchase-request', id], (old: PRDetail | undefined) => {
        if (!old) return old;
        return { ...old, status: PR_STATUS.APPROVED };
      });

      queryClient.invalidateQueries({ queryKey: ['purchase-requests'] });
    },
    onError: (error) => {
      console.error('[useApprovePR] Failed to approve PR:', error);
    },
  });
}

'use client';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useSafeMutation } from '@/core/concurrency/useSafeMutation';
import { apiClient } from '@/lib/api/client';
import { z } from 'zod';
import { PODetailSchema } from './usePO';

const CreatePOPayloadSchema = z.object({
 pr_id: z.string().optional(),
 target_warehouse_id: z.string().optional(),
 supplier_id: z.string(),
 currency_code: z.string(),
 exchange_rate: z.number(),
 expected_date: z.string(),
 notes: z.string().optional(),
 lines: z.array(z.object({
 item_id: z.string(),
 quantity: z.number().positive(),
 unit_price: z.number().nonnegative(),
 uom_id: z.string(),
 notes: z.string().optional()
 }))
});

export type CreatePOPayload = z.infer<typeof CreatePOPayloadSchema>;

export function useCreatePO(options?: { onConflict?: () => void }) {
 const queryClient = useQueryClient();
 return useSafeMutation({
 onConflict: options?.onConflict,
 mutationFn: (payload: CreatePOPayload) => 
 apiClient.post('/procurement/purchase-orders', z.object({ data: PODetailSchema }), CreatePOPayloadSchema.parse(payload)).then(res => res.data),
 onSuccess: (data) => {
 // Seed the cache for the newly created PO
 queryClient.setQueryData(['purchase-order', data.id], data);
 queryClient.invalidateQueries({ queryKey: ['purchase-orders'] });
 }
 });
}

'use client';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useSafeMutation } from '@/core/concurrency/useSafeMutation';
import { apiClient } from '@/lib/api/client';
import { z } from 'zod';
import { PRDetailSchema } from './usePR';

const CreatePRPayloadSchema = z.object({
 department_id: z.string(),
 expected_date: z.string(),
 notes: z.string().optional(),
 lines: z.array(z.object({
 item_id: z.string(),
 req_qty: z.number().positive(),
 uom_id: z.string()
 }))
});

export type CreatePRPayload = z.infer<typeof CreatePRPayloadSchema>;

export function useCreatePR(options?: { onConflict?: () => void }) {
  const queryClient = useQueryClient();
  return useSafeMutation({
    onConflict: options?.onConflict,
    mutationFn: (payload: CreatePRPayload & { signal?: AbortSignal }) => {
      const { signal, ...data } = payload;
      return apiClient.post('/procurement/purchase-requests', PRDetailSchema, CreatePRPayloadSchema.parse(data), signal);
    },
    onSuccess: (data) => {
      // Seed the cache for the newly created PR
      queryClient.setQueryData(['purchase-request', data.id], data);
      queryClient.invalidateQueries({ queryKey: ['purchase-requests'] });
    },
    onError: (error) => {
      if (error instanceof Error && error.message === 'Aborted') return;
    }
  });
}

'use client';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useSafeMutation } from '@/core/concurrency/useSafeMutation';
import { apiClient } from '@/lib/api/client';
import { successSchema } from '@/types/api';

export function usePostGRN(id: string, options?: { onConflict?: () => void }) {
  const queryClient = useQueryClient();
  
  return useSafeMutation({
    onConflict: options?.onConflict,
    mutationFn: (data: { fx_rate: number; confirmation: 'ACKNOWLEDGE_IRREVERSIBLE'; version: number }) => 
      apiClient.post(`/procurement/grns/${id}/post`, successSchema, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['grns'] });
      queryClient.invalidateQueries({ queryKey: ['grn', id] });
    },
    onError: (error) => {
      console.error('[usePostGRN] Failed to post GRN:', error);
    }
  });
}

